// ── عداد زوار بارز لأعلى الصفحات العامة ──
function BoldVisitorBadge({ pageKey }) {
  const [count, setCount] = React.useState(null);
  React.useEffect(() => {
    const key = `school-visitor-${pageKey}`;
    DB.get(key, 0).then(c => {
      const n = (c || 0) + 1;
      setCount(n);
      DB.set(key, n);
    });
  }, [pageKey]);
  if (count === null) return null;
  return (
    <div style={{
      display:"inline-flex", alignItems:"center", gap:8,
      background:"linear-gradient(135deg,rgba(255,255,255,.22),rgba(255,255,255,.10))",
      backdropFilter:"blur(8px)",
      border:"1.5px solid rgba(255,255,255,.35)",
      borderRadius:40, padding:"6px 18px",
      boxShadow:"0 4px 16px rgba(0,0,0,.12)"
    }}>
      <span style={{fontSize:18}}>👁️</span>
      <div style={{textAlign:"right"}}>
        <div style={{fontWeight:900, fontSize:20, color:"#fff", lineHeight:1,
          textShadow:"0 1px 4px rgba(0,0,0,.2)"}}>
          {count.toLocaleString("ar-SA-u-nu-latn")}
        </div>
        <div style={{fontSize:10, color:"rgba(255,255,255,.85)", fontWeight:700, marginTop:1}}>زيارة</div>
      </div>
    </div>
  );
}

// ── مكوّن تعليقات للإعلانات والأنشطة ──
function PublicComments({ itemKey, itemTitle }) {
  const DB_KEY = `school-comments-${itemKey}`;
  const [comments, setComments] = React.useState([]);
  const [name, setName] = React.useState("");
  const [text, setText] = React.useState("");
  const [saving, setSaving] = React.useState(false);
  const [showForm, setShowForm] = React.useState(false);
  const [loaded, setLoaded] = React.useState(false);
  const [showAll, setShowAll] = React.useState(false);

  React.useEffect(() => {
    DB.get(DB_KEY, []).then(d => {
      setComments(Array.isArray(d) ? d : []);
      setLoaded(true);
    });
  }, [DB_KEY]);

  const submit = async () => {
    if (!text.trim()) return;
    setSaving(true);
    const newC = {
      id: Date.now(),
      name: name.trim() || "زائر",
      text: text.trim(),
      date: new Date().toLocaleDateString("ar-SA"),
      time: new Date().toLocaleTimeString("ar-SA-u-nu-latn", {hour:"2-digit", minute:"2-digit"}),
    };
    const updated = [newC, ...comments];
    await DB.set(DB_KEY, updated);
    setComments(updated);
    setName(""); setText(""); setSaving(false); setShowForm(false);
  };

  const visible = showAll ? comments : comments.slice(0, 3);

  if (!loaded) return null;

  return (
    <div dir="rtl" style={{marginTop:16, borderTop:"1.5px solid #e2e8f0", paddingTop:14}}>
      {/* عنوان قسم التعليقات */}
      <div style={{display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:10}}>
        <div style={{display:"flex", alignItems:"center", gap:7}}>
          <span style={{fontSize:18}}>💬</span>
          <span style={{fontWeight:900, fontSize:14, color:"#0d3b6e"}}>التعليقات</span>
          {comments.length > 0 && (
            <span style={{background:"#0d9488", color:"#fff", borderRadius:"50%",
              width:20, height:20, display:"flex", alignItems:"center", justifyContent:"center",
              fontSize:11, fontWeight:900}}>{comments.length}</span>
          )}
        </div>
        <button onClick={() => setShowForm(p => !p)}
          style={{padding:"5px 14px", borderRadius:20, background:showForm?"#fee2e2":"linear-gradient(135deg,#0d9488,#0f766e)",
            color:showForm?"#dc2626":"#fff", fontWeight:700, fontSize:12,
            border:showForm?"1.5px solid #fca5a5":"none", cursor:"pointer",
            fontFamily:"'Cairo',sans-serif"}}>
          {showForm ? "✕ إلغاء" : "✍️ أضف تعليقاً"}
        </button>
      </div>

      {/* نموذج التعليق */}
      {showForm && (
        <div style={{background:"#f8fafc", borderRadius:14, padding:14, marginBottom:12,
          border:"1.5px solid #e2e8f0"}}>
          <input value={name} onChange={e => setName(e.target.value)}
            placeholder="اسمك (اختياري)"
            style={{width:"100%", padding:"8px 12px", borderRadius:10, border:"1.5px solid #e2e8f0",
              fontSize:13, fontFamily:"'Cairo',sans-serif", marginBottom:8, boxSizing:"border-box"}} />
          <textarea value={text} onChange={e => setText(e.target.value)}
            placeholder="اكتب تعليقك هنا..."
            rows={3}
            style={{width:"100%", padding:"8px 12px", borderRadius:10, border:"1.5px solid #e2e8f0",
              fontSize:13, fontFamily:"'Cairo',sans-serif", resize:"vertical",
              marginBottom:8, boxSizing:"border-box", lineHeight:1.8}} />
          <button onClick={submit} disabled={saving || !text.trim()}
            style={{padding:"8px 20px", borderRadius:10,
              background:saving||!text.trim()?"#94a3b8":"linear-gradient(135deg,#0d9488,#0f766e)",
              color:"#fff", fontWeight:700, fontSize:13, border:"none",
              cursor:saving||!text.trim()?"not-allowed":"pointer",
              fontFamily:"'Cairo',sans-serif"}}>
            {saving ? "⏳ جاري الإرسال..." : "إرسال التعليق 📤"}
          </button>
        </div>
      )}

      {/* قائمة التعليقات */}
      {comments.length === 0 ? (
        <div style={{textAlign:"center", padding:"20px 0", color:"#94a3b8", fontSize:13}}>
          <div style={{fontSize:32, marginBottom:6}}>💬</div>
          لا توجد تعليقات بعد — كن أول من يعلّق!
        </div>
      ) : (
        <>
          <div style={{display:"grid", gap:8}}>
            {visible.map(c => (
              <div key={c.id} style={{background:"#f8fafc", borderRadius:12,
                padding:"10px 14px", border:"1px solid #e2e8f0"}}>
                <div style={{display:"flex", alignItems:"center", gap:8, marginBottom:5}}>
                  <div style={{width:32, height:32, borderRadius:"50%",
                    background:"linear-gradient(135deg,#0d9488,#0d3b6e)",
                    color:"#fff", display:"flex", alignItems:"center",
                    justifyContent:"center", fontWeight:900, fontSize:14, flexShrink:0}}>
                    {c.name.charAt(0)}
                  </div>
                  <div>
                    <div style={{fontWeight:800, fontSize:13, color:"#1e293b"}}>{c.name}</div>
                    <div style={{fontSize:10, color:"#94a3b8"}}>{c.date} — {c.time}</div>
                  </div>
                </div>
                <p style={{fontSize:13, color:"#374151", lineHeight:1.8, margin:0, paddingRight:40}}>
                  {c.text}
                </p>
              </div>
            ))}
          </div>
          {comments.length > 3 && (
            <button onClick={() => setShowAll(p => !p)}
              style={{width:"100%", marginTop:8, padding:"8px 0",
                background:"#f1f5f9", borderRadius:10,
                color:"#0d9488", fontWeight:700, fontSize:12,
                border:"1.5px solid #e2e8f0", cursor:"pointer",
                fontFamily:"'Cairo',sans-serif"}}>
              {showAll ? "▲ عرض أقل" : `▼ عرض كل التعليقات (${comments.length})`}
            </button>
          )}
        </>
      )}
    </div>
  );
}

// ══════════════════════════════════════════════════════════
// AnnDatePicker — اختيار تاريخ الإعلان (هجري أم القرى / ميلادي)
// يسمح بأي تاريخ حتى لو كان سابقًا. يحفظ:
//   dateG : التاريخ الميلادي بصيغة yyyy-mm-dd
//   date  : النص المعروض "هجري — ميلادي"
// ══════════════════════════════════════════════════════════
const ANN_HIJRI_MONTHS = ["محرم","صفر","ربيع الأول","ربيع الآخر","جمادى الأولى","جمادى الآخرة","رجب","شعبان","رمضان","شوال","ذو القعدة","ذو الحجة"];
const _annHijriFmt = new Intl.DateTimeFormat("en-u-ca-islamic-umalqura", { day:"numeric", month:"numeric", year:"numeric", timeZone:"UTC" });
function annGToHijri(iso) {
  const d = new Date(iso + "T12:00:00Z");
  const p = {}; _annHijriFmt.formatToParts(d).forEach(x => { p[x.type] = x.value; });
  return { y: parseInt(p.year), m: parseInt(p.month), d: parseInt(p.day) };
}
function annHijriToG(hy, hm, hd) {
  // تقدير أولي ثم بحث دقيق حول التقدير
  const approx = Date.UTC(622, 6, 16) + ((hy - 1) * 354.367 + (hm - 1) * 29.5306 + (hd - 1)) * 86400000;
  for (let off = -30; off <= 30; off++) {
    const iso = new Date(approx + off * 86400000).toISOString().slice(0, 10);
    const h = annGToHijri(iso);
    if (h.y === hy && h.m === hm && h.d === hd) return iso;
  }
  return null; // اليوم غير موجود (مثل ٣٠ في شهر من ٢٩ يومًا)
}
function annDateLabel(iso) {
  const d = new Date(iso + "T12:00:00Z");
  const h = new Intl.DateTimeFormat("ar-SA-u-ca-islamic-umalqura-nu-arab", { day:"numeric", month:"long", year:"numeric", timeZone:"UTC" }).format(d).replace(/\s*هـ$/, "");
  const g = new Intl.DateTimeFormat("ar-SA-u-ca-gregory-nu-arab", { day:"numeric", month:"long", year:"numeric", timeZone:"UTC" }).format(d);
  const w = new Intl.DateTimeFormat("ar-SA", { weekday:"long", timeZone:"UTC" }).format(d);
  return `${w} ${h} هـ — ${g} م`;
}
function annTodayISO() {
  const n = new Date();
  return `${n.getFullYear()}-${String(n.getMonth()+1).padStart(2,"0")}-${String(n.getDate()).padStart(2,"0")}`;
}
const ANN_AUDIENCES = [
  { v:"أولياء الأمور", icon:"👨‍👩‍👦", c:"#0f766e" },
  { v:"المعلمون",     icon:"👨‍🏫",   c:"#1d4ed8" },
  { v:"الطلاب",       icon:"🎒",     c:"#b45309" },
  { v:"الجميع",       icon:"🏫",     c:"#7c3aed" },
];
// شارة الفئة المستهدفة — تظهر أعلى الإعلان
function AnnAudience({ ann, size = "md" }) {
  if (!ann || !ann.audience) return null;
  const a = ANN_AUDIENCES.find(x => x.v === ann.audience) || { icon:"📢", c:"#0f766e", v:ann.audience };
  const big = size === "lg", small = size === "sm";
  return (
    <div style={{ display:"inline-flex", alignItems:"center", gap:6, background:a.c, color:"#fff", borderRadius:999,
      padding: big ? "7px 18px" : small ? "2px 10px" : "4px 14px", fontWeight:900,
      fontSize: big ? 16 : small ? 11 : 13, marginBottom: big ? 12 : 6, fontFamily:"'Cairo',sans-serif" }}>
      <span>{a.icon}</span><span>موجّه إلى: {a.v}</span>
    </div>
  );
}
// سطر اليوم والتاريخ — يظهر تحت عنوان الإعلان
function AnnDateLine({ ann, size = "md", dark = false }) {
  if (!ann || !ann.date) return null;
  const big = size === "lg", small = size === "sm";
  return (
    <div style={{ display:"flex", alignItems:"center", gap:6, flexWrap:"wrap", fontWeight:800,
      fontSize: big ? 18 : small ? 11.5 : 14, color: dark ? "#e2e8f0" : "#0f766e",
      marginTop: small ? 3 : 6, marginBottom: big ? 12 : 8, lineHeight:1.6, fontFamily:"'Cairo',sans-serif" }}>
      <span>📅</span><span>{ann.date}</span>
    </div>
  );
}
function AnnDatePicker({ ann, setAnn }) {
  const [mode, setMode] = React.useState("hijri");
  const [err, setErr] = React.useState("");
  const iso = ann.dateG || "";
  const h = iso ? annGToHijri(iso) : annGToHijri(annTodayISO());
  const apply = (newIso) => { setErr(""); setAnn(p => ({ ...p, dateG: newIso, date: annDateLabel(newIso) })); };
  const setHijri = (y, m, d) => {
    const g = annHijriToG(y, m, d);
    if (!g) { setErr(`لا يوجد يوم ${d} في شهر ${ANN_HIJRI_MONTHS[m-1]} ${y}هـ`); return; }
    apply(g);
  };
  const box = { padding:"7px 8px", borderRadius:8, border:"1.5px solid #e2e8f0", fontSize:12, fontFamily:"'Cairo',sans-serif", outline:"none", background:"#fff" };
  const tab = (on) => ({ padding:"5px 14px", borderRadius:20, border:"none", cursor:"pointer", fontWeight:700, fontSize:12, fontFamily:"'Cairo',sans-serif", background: on ? "#0d9488" : "#f1f5f9", color: on ? "#fff" : "#475569" });
  const years = []; for (let y = 1420; y <= 1470; y++) years.push(y);
  return (
    <div dir="rtl" style={{ background:"#f8fafc", border:"1.5px solid #e2e8f0", borderRadius:12, padding:10, marginBottom:10 }}>
      <div style={{ display:"flex", alignItems:"center", gap:8, flexWrap:"wrap", marginBottom:8 }}>
        <span style={{ fontWeight:800, fontSize:12, color:"#0d3b6e" }}>🎯 الفئة المستهدفة:</span>
        <select value={ann.audience || ""} onChange={e => setAnn(p => ({ ...p, audience: e.target.value }))}
          style={{ ...box, fontWeight:700, minWidth:150 }}>
          <option value="">— اختر —</option>
          {ANN_AUDIENCES.map(a => <option key={a.v} value={a.v}>{a.icon} {a.v}</option>)}
        </select>
      </div>
      <div style={{ display:"flex", alignItems:"center", gap:8, flexWrap:"wrap", marginBottom:8 }}>
        <span style={{ fontWeight:800, fontSize:12, color:"#0d3b6e" }}>📅 تاريخ الإعلان:</span>
        <button type="button" style={tab(mode==="hijri")} onClick={()=>setMode("hijri")}>هجري</button>
        <button type="button" style={tab(mode==="greg")} onClick={()=>setMode("greg")}>ميلادي</button>
        <button type="button" style={{ ...tab(false), background:"#fff", border:"1.5px solid #e2e8f0" }} onClick={()=>apply(annTodayISO())}>اليوم</button>
      </div>
      {mode === "greg" ? (
        <input type="date" value={iso} onChange={e => e.target.value && apply(e.target.value)} style={{ ...box, width:"100%" }} />
      ) : (
        <div style={{ display:"grid", gridTemplateColumns:"70px 1fr 90px", gap:6 }}>
          <select value={h.d} onChange={e => setHijri(h.y, h.m, +e.target.value)} style={box}>
            {Array.from({length:30},(_,i)=>i+1).map(d => <option key={d} value={d}>{d}</option>)}
          </select>
          <select value={h.m} onChange={e => setHijri(h.y, +e.target.value, Math.min(h.d, 29))} style={box}>
            {ANN_HIJRI_MONTHS.map((n,i) => <option key={i} value={i+1}>{n}</option>)}
          </select>
          <select value={h.y} onChange={e => setHijri(+e.target.value, h.m, Math.min(h.d, 29))} style={box}>
            {years.map(y => <option key={y} value={y}>{y}</option>)}
          </select>
        </div>
      )}
      {err && <div style={{ color:"#dc2626", fontSize:11, marginTop:6, fontWeight:700 }}>{err}</div>}
      <div style={{ fontSize:12, color:"#0f766e", marginTop:8, fontWeight:700 }}>
        {iso ? annDateLabel(iso) : (ann.date ? `التاريخ الحالي: ${ann.date}` : "لم يُحدد — سيُستخدم تاريخ اليوم")}
      </div>
    </div>
  );
}

// ══════════════════════════════════════════════════════════
// تخزين الإعلانات: كل إعلان في عقدة مستقلة  school/school-ann-items/{id}
// (سابقاً كانت كل الإعلانات تُرفع دفعة واحدة، فتفشل عند وجود صور كبيرة ولا تصل للأجهزة الأخرى)
// ══════════════════════════════════════════════════════════
const ANN_NODE = "school-ann-items";
const ANN_META = "school-ann-meta";
let annLoadFailed = false; // {id:{at}} — يُعرف منه ما تغيّر فيُحمَّل فقط (بدل تحميل كل الإعلانات بصورها كل مرة)
const idbKV = {
  db: null,
  open() { if (!this.db) this.db = new Promise((res, rej) => { try { const r = indexedDB.open("pam-cache", 1); r.onupgradeneeded = () => r.result.createObjectStore("kv"); r.onsuccess = () => res(r.result); r.onerror = () => rej(r.error); } catch (e) { rej(e); } }); return this.db; },
  async get(k) { try { const db = await this.open(); return await new Promise(res => { const q = db.transaction("kv").objectStore("kv").get(k); q.onsuccess = () => res(q.result); q.onerror = () => res(undefined); }); } catch { return undefined; } },
  async set(k, v) { try { const db = await this.open(); await new Promise(res => { const t = db.transaction("kv", "readwrite"); t.objectStore("kv").put(v, k); t.oncomplete = res; t.onerror = res; }); } catch {} },
};
async function annPut(id, value) {
  const ok = await dbFirebasePut(`${ANN_NODE}/${id}`, value);
  const mv = { at: Date.now() };
  if (!ok) { try { dbQueue.add(`${ANN_NODE}/${id}`, value); dbQueue.add(`${ANN_META}/${id}`, mv); } catch {} }
  else { const ok2 = await dbFirebasePut(`${ANN_META}/${id}`, mv); if (!ok2) { try { dbQueue.add(`${ANN_META}/${id}`, mv); } catch {} } }
  return ok;
}
async function annDelete(id) {
  try { fetch(`${FIREBASE_URL}/school/${ANN_META}/${id}.json`, { method: "DELETE" }).catch(() => {}); const r = await fetch(`${FIREBASE_URL}/school/${ANN_NODE}/${id}.json`, { method: "DELETE" }); return r.ok; } catch { return false; }
}
async function annBuildMeta(arr) {
  const now = Date.now(); const m = {}; (arr || []).forEach(a => { if (a && a.id != null) m[String(a.id)] = { at: now }; });
  if (!Object.keys(m).length) return;
  await dbFirebasePut(ANN_META, m);
  await idbKV.set("ann-cache", { items: Object.fromEntries(arr.filter(a => a && a.id != null).map(a => [String(a.id), a])), at: m });
}
// تحميل الإعلانات: يُنزَّل فقط الجديد أو المعدَّل منذ آخر زيارة (مخزَّن على الجهاز)
async function annLoadAll() { return (await annLoadAllRaw()).filter(a => a && !annIsSample(a)); }
async function annLoadAllRaw() {
  let meta; try { const r = await fetch(`${FIREBASE_URL}/school/${ANN_META}.json`); meta = await r.json(); } catch { meta = undefined; }
  const c = (await idbKV.get("ann-cache")) || { items: {}, at: {} };
  if (meta === undefined) return Object.values(c.items || {});
  if (!meta || typeof meta !== "object") {
    let items = null; try { const r = await fetch(`${FIREBASE_URL}/school/${ANN_NODE}.json`); items = await r.json(); } catch {}
    const arr = items && typeof items === "object" ? Object.values(items).filter(x => x && x.id != null) : [];
    await annBuildMeta(arr); return arr;
  }
  try { const r = await fetch(`${FIREBASE_URL}/school/${ANN_NODE}.json?shallow=true`); const keys = await r.json(); if (keys && typeof keys === "object") { const now = Date.now(); const fix = {}; Object.keys(keys).forEach(id => { if (!meta[id]) { meta[id] = { at: now }; fix[`${ANN_META}/${id}`] = { at: now }; } }); if (Object.keys(fix).length) fbPatch(fix); } } catch {}
  const items = { ...(c.items || {}) }, at = { ...(c.at || {}) }; let ch = false;
  Object.keys(items).forEach(id => { if (!meta[id]) { delete items[id]; delete at[id]; ch = true; } });
  const need = Object.keys(meta).filter(id => !items[id] || !at[id] || at[id].at !== (meta[id] && meta[id].at));
  await Promise.all(need.map(async id => { try { const r = await fetch(`${FIREBASE_URL}/school/${ANN_NODE}/${id}.json`); const v = await r.json(); if (v && typeof v === "object") { items[id] = v; at[id] = meta[id]; } else { delete items[id]; } ch = true; } catch {} }));
  if (ch) await idbKV.set("ann-cache", { items, at });
  return Object.values(items);
}
async function annFetchOne(id) {
  try {
    const r = await fetch(`${FIREBASE_URL}/school/${ANN_NODE}/${id}.json`);
    const d = await r.json();
    if (d && typeof d === "object") return d;
  } catch {}
  try {
    const r = await fetch(`${FIREBASE_URL}/school/school-announcements.json`);
    const d = await r.json();
    const arr = Array.isArray(d) ? d : (d && typeof d === "object" ? Object.values(d) : []);
    return arr.find(a => a && String(a.id) === String(id)) || null;
  } catch { return null; }
}
// ══════════ الأنشطة: كل نشاط في عقدة مستقلة school/school-act-items/{id} ══════════
// (سابقاً: كل الأنشطة بصورها في عقدة واحدة — تفشل الكتابة مع الصور وقد تستبدل بيانات الخادم بنسخة ناقصة)
const ACT_NODE = "school-act-items", ACT_MIG = "school-act-migrated";
async function fetchJ(path, ms = 30000) { const c = new AbortController(); const t = setTimeout(() => c.abort(), ms); try { const r = await fetch(`${FIREBASE_URL}/school/${path}.json`, { signal: c.signal }); if (!r.ok) throw new Error("HTTP " + r.status); return await r.json(); } finally { clearTimeout(t); } }
const actArr = v => (Array.isArray(v) ? v : v && typeof v === "object" ? Object.values(v) : []).filter(a => a && a.id != null);
const actSort = L => L.sort((a, b) => (Number(b.id) || 0) - (Number(a.id) || 0));
// يُرجع {ok, list} — ok=false عند تعذّر الوصول للخادم (لا يُكتب شيء ولا تُستخدم بيانات افتراضية)
async function actLoad() {
  let items, mig;
  try { [items, mig] = await Promise.all([fetchJ(ACT_NODE, 40000), fetchJ(ACT_MIG, 15000)]); } catch { try { [items, mig] = await Promise.all([fetchJ(ACT_NODE, 60000), fetchJ(ACT_MIG, 20000)]); } catch { const c = await idbKV.get("act-cache"); return { ok: false, list: actSort(actArr(c)) }; } }
  const byId = new Map(actArr(items).map(a => [String(a.id), a]));
  if (!mig) { // ترحيل لمرة واحدة من العقدة القديمة + أي نسخة محلية لم تُرفع
    let leg = null; try { leg = await fetchJ("school-activities", 60000); } catch { const c = await idbKV.get("act-cache"); return { ok: false, list: actSort([...byId.values(), ...actArr(c).filter(a => !byId.has(String(a.id)))]) }; }
    const local = []; try { local.push(...actArr(JSON.parse(localStorage.getItem(DB_CACHE_PREFIX + "school-activities") || "null"))); } catch {} try { const q = JSON.parse(localStorage.getItem(DB_QUEUE_KEY) || "[]"); q.filter(i => i && i.key === "school-activities").forEach(i => local.push(...actArr(i.value))); } catch {}
    const src = [...actArr(leg), ...local]; const o = {};
    src.forEach(a => { if (!byId.has(String(a.id))) { byId.set(String(a.id), a); o[`${ACT_NODE}/${a.id}`] = a; } });
    if (!actArr(leg).length && !byId.size) DEFAULT_ACTIVITIES.forEach(a => { byId.set(String(a.id), a); o[`${ACT_NODE}/${a.id}`] = a; });
    o[ACT_MIG] = Date.now(); try { await fbPatch(o); } catch {}
    try { const q = JSON.parse(localStorage.getItem(DB_QUEUE_KEY) || "[]").filter(i => i && i.key !== "school-activities"); localStorage.setItem(DB_QUEUE_KEY, JSON.stringify(q)); } catch {}
  }
  const list = actSort([...byId.values()]); idbKV.set("act-cache", list); return { ok: true, list };
}
async function actPut(a) { const content = await annCompressHtml(a.description || ""); const v = { ...a, description: content }; if (JSON.stringify(v).length > 9000000) return "big"; const ok = await dbFirebasePut(`${ACT_NODE}/${a.id}`, v); if (!ok) { try { dbQueue.add(`${ACT_NODE}/${a.id}`, v); } catch {} } return ok; }
async function actDel(id) { try { const r = await fetch(`${FIREBASE_URL}/school/${ACT_NODE}/${id}.json`, { method: "DELETE" }); return r.ok; } catch { return false; } }

// تصغير الصور المضمّنة داخل نص الإعلان (base64) قبل الحفظ
async function annCompressHtml(html) {
  if (!html || typeof html !== "string" || !html.includes("data:image")) return html;
  const re = /data:image\/(png|jpe?g|webp|gif|bmp);base64,[A-Za-z0-9+/=]+/g;
  const found = [...new Set(html.match(re) || [])].filter(u => u.length > 200000 && !u.startsWith("data:image/gif"));
  let out = html;
  for (const src of found) {
    try {
      const img = await new Promise((res, rej) => { const im = new Image(); im.onload = () => res(im); im.onerror = rej; im.src = src; });
      const scale = Math.min(1, 1600 / Math.max(img.naturalWidth, img.naturalHeight));
      const cv = document.createElement("canvas");
      cv.width = Math.round(img.naturalWidth * scale); cv.height = Math.round(img.naturalHeight * scale);
      const cx = cv.getContext("2d"); cx.fillStyle = "#fff"; cx.fillRect(0, 0, cv.width, cv.height); cx.drawImage(img, 0, 0, cv.width, cv.height);
      const small = cv.toDataURL("image/jpeg", 0.82);
      if (small.length < src.length) out = out.split(src).join(small);
    } catch {}
  }
  return out;
}

// ── تهيئة نص الإعلان للعرض على الجوال: تصغير الخطوط الكبيرة، إزالة العروض الثابتة والمسافات الزائدة، ومنع انكسار التواريخ
function annFit(html) {
  if (!html || typeof html !== "string") return html || "";
  try {
    const doc = new DOMParser().parseFromString(`<div id="annr">${html}</div>`, "text/html");
    const root = doc.getElementById("annr"); if (!root) return html;
    root.querySelectorAll("*").forEach(el => {
      const st = el.style; const tag = el.tagName;
      if (st) {
        const fs = st.fontSize;
        if (fs) { let px = parseFloat(fs); if (/pt$/.test(fs)) px *= 1.333; else if (/r?em$/.test(fs)) px *= 16; else if (/%$/.test(fs)) px = px / 100 * 16; else if (!/px$/.test(fs)) px = 0; if (px > 0) { const cap = /^H[1-3]$/.test(tag) ? 26 : 21; st.fontSize = Math.round(Math.min(Math.max(px, 13), cap)) + "px"; } else st.fontSize = ""; }
        if (st.lineHeight) { const v = parseFloat(st.lineHeight); if (/px$/.test(st.lineHeight) ? v > 42 : v > 2.2) st.lineHeight = "1.9"; }
        ["width", "minWidth", "maxWidth", "textIndent", "letterSpacing", "wordSpacing", "whiteSpace", "position", "left", "right", "top", "bottom", "float"].forEach(k => { if (!(tag === "IMG" && k === "maxWidth")) st[k] = ""; });
        if (tag !== "IMG") st.height = "";
        ["marginLeft", "marginRight", "paddingLeft", "paddingRight"].forEach(k => { if (parseFloat(st[k]) > 18) st[k] = ""; });
      }
      if (tag === "IMG") { el.removeAttribute("width"); el.removeAttribute("height"); el.style.maxWidth = "100%"; el.style.height = "auto"; }
      else el.removeAttribute("width");
      if (tag === "FONT" && +el.getAttribute("size") > 4) el.setAttribute("size", "4");
      if ((el.getAttribute("dir") || "").toLowerCase() === "ltr" && /[؀-ۿ]/.test(el.textContent || "")) el.setAttribute("dir", "auto");
    });
    const tw = doc.createTreeWalker(root, 4); const nodes = []; while (tw.nextNode()) nodes.push(tw.currentNode);
    const re = /(\d{1,4}\s*[\/\-.]\s*\d{1,2}\s*[\/\-.]\s*\d{1,4}\s*(?:هـ|ه|م)?)/;
    nodes.forEach(t => {
      let v = t.nodeValue.replace(/ {2,}/g, " ").replace(/[ \t]{3,}/g, " ");
      if (re.test(v)) { const frag = doc.createDocumentFragment(); v.split(re).forEach((part, i) => { if (i % 2) { const sp = doc.createElement("span"); sp.className = "ann-nw"; sp.textContent = part; frag.appendChild(sp); } else if (part) frag.appendChild(doc.createTextNode(part)); }); t.parentNode.replaceChild(frag, t); }
      else if (v !== t.nodeValue) t.nodeValue = v;
    });
    return root.innerHTML;
  } catch { return html; }
}
