// ── طباعة جميع أعذار الطلاب (صفحة كاملة) ──
function printAllExcuses(excusesList) {
  if (!excusesList || excusesList.length === 0) { alert("لا توجد أعذار للطباعة"); return; }
  const STATUS_COLORS = {"مقبول":"#059669","مرفوض":"#dc2626","قيد المراجعة":"#d97706"};
  const REASON_ICONS  = {"مرض":"🏥","ظرف عائلي":"👨‍👩‍👦","سفر":"✈️","حادث أو إصابة":"🚑","موعد طبي":"🩺","وفاة في العائلة":"🕊️","أخرى":"📋"};

  const counts = {
    total: excusesList.length,
    pending: excusesList.filter(e=>e.status==="قيد المراجعة").length,
    accepted: excusesList.filter(e=>e.status==="مقبول").length,
    rejected: excusesList.filter(e=>e.status==="مرفوض").length,
  };

  const rows = excusesList.map((ex, i) => {
    const sc = STATUS_COLORS[ex.status] || "#64748b";
    return `<tr>
      <td style="text-align:center;font-weight:900;color:#64748b">${i+1}</td>
      <td style="font-weight:700">${ex.studentName||"—"}</td>
      <td style="text-align:center;font-size:11px">${ex.className||"—"}</td>
      <td style="font-size:10px">${REASON_ICONS[ex.reasonCat]||"📋"} ${ex.reasonCat||"—"}</td>
      <td style="font-size:10px">${ex.absenceDay||""} ${ex.absenceDateH||""}هـ</td>
      <td style="font-weight:700;font-size:11px">${ex.parentName||"—"} (${ex.parentRelation||"ولي الأمر"})</td>
      <td style="font-size:10px">${ex.parentPhone||"—"}</td>
      <td style="text-align:center">
        <span style="display:inline-block;padding:2px 10px;border-radius:12px;font-size:10px;font-weight:900;background:${sc}20;color:${sc};border:1px solid ${sc}">
          ${ex.status}
        </span>
      </td>
      <td style="font-size:10px;text-align:center">${ex.submittedAt||"—"}</td>
    </tr>`;
  }).join("");

  const reasonDist = {};
  excusesList.forEach(e => { reasonDist[e.reasonCat] = (reasonDist[e.reasonCat]||0)+1; });

  const win = window.open("","_blank","width=1100,height=800");
  if (!win) { alert("يرجى السماح بالنوافذ المنبثقة"); return; }
  win.document.write(`<!DOCTYPE html>
<html dir="rtl" lang="ar">
<head>
<meta charset="UTF-8"/>
<title>تقرير أعذار الطلاب</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Cairo:wght@400;700;900&display=swap');
  *{box-sizing:border-box;margin:0;padding:0;}
  body{font-family:'Cairo',sans-serif;background:#fff;color:#1e293b;padding:18px;font-size:12px;}

  /* رأس الصفحة */
  .page-header{display:flex;align-items:center;gap:14px;margin-bottom:16px;padding-bottom:12px;border-bottom:3px double #0d3b6e;}
  .logo-box{width:60px;height:60px;border-radius:12px;background:linear-gradient(135deg,#0d3b6e,#0d9488);display:flex;align-items:center;justify-content:center;font-size:26px;flex-shrink:0;}
  .school-info{flex:1;text-align:center;}
  .school-name{font-size:16px;font-weight:900;color:#0d3b6e;}
  .report-title{font-size:13px;font-weight:700;color:#0d9488;margin-top:2px;}
  .report-date{font-size:11px;color:#64748b;margin-top:2px;}

  /* إحصائيات */
  .stats{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:14px;}
  .stat{text-align:center;padding:10px;border-radius:10px;border:2px solid;}

  /* الجدول */
  table{width:100%;border-collapse:collapse;margin-bottom:12px;font-size:11px;}
  th{background:#0d3b6e;color:#fff;padding:7px 8px;text-align:right;font-weight:700;border:1px solid #0d3b6e;}
  td{padding:6px 8px;border:1px solid #cbd5e1;vertical-align:middle;}
  tr:nth-child(even) td{background:#f8fafc;}
  tr:hover td{background:#f0fdfa;}

  /* توزيع الأسباب */
  .dist{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px;}
  .dist-item{padding:6px 12px;border-radius:20px;background:#f0fdfa;border:1px solid #86efac;font-size:11px;font-weight:700;color:#0d9488;}

  /* توقيعات */
  .sigs{display:grid;grid-template-columns:1fr 1fr 1fr;gap:20px;margin-top:28px;}
  .sig{text-align:center;border-top:2px solid #1e293b;padding-top:8px;}

  .footer{text-align:center;margin-top:16px;font-size:10px;color:#94a3b8;border-top:1px dashed #e2e8f0;padding-top:8px;}
  @media print{body{padding:0;}@page{size:A4 landscape;margin:10mm;}th{-webkit-print-color-adjust:exact;print-color-adjust:exact;}}
</style>
</head>
<body>

<div class="page-header">
  <div class="logo-box">🏫</div>
  <div class="school-info">
    <div class="school-name">مدرسة الأمير عبدالمجيد المتوسطة الأولى</div>
    <div class="report-title">تقرير أعذار غياب الطلاب</div>
    <div class="report-date">تاريخ الطباعة: ${new Date().toLocaleDateString("ar-SA")} | إجمالي السجلات: ${excusesList.length}</div>
  </div>
</div>

<div class="stats">
  <div class="stat" style="border-color:#7c3aed;background:#faf5ff">
    <div style="font-size:24px;font-weight:900;color:#7c3aed">${counts.total}</div>
    <div style="font-size:11px;color:#64748b">إجمالي الأعذار</div>
  </div>
  <div class="stat" style="border-color:#d97706;background:#fffbeb">
    <div style="font-size:24px;font-weight:900;color:#d97706">${counts.pending}</div>
    <div style="font-size:11px;color:#64748b">قيد المراجعة</div>
  </div>
  <div class="stat" style="border-color:#059669;background:#f0fdf4">
    <div style="font-size:24px;font-weight:900;color:#059669">${counts.accepted}</div>
    <div style="font-size:11px;color:#64748b">مقبول</div>
  </div>
  <div class="stat" style="border-color:#dc2626;background:#fef2f2">
    <div style="font-size:24px;font-weight:900;color:#dc2626">${counts.rejected}</div>
    <div style="font-size:11px;color:#64748b">مرفوض</div>
  </div>
</div>

<div style="margin-bottom:10px">
  <div style="font-size:12px;font-weight:900;color:#0d3b6e;margin-bottom:6px">📊 توزيع أسباب الغياب:</div>
  <div class="dist">
    ${Object.entries(reasonDist).sort((a,b)=>b[1]-a[1]).map(([r,c])=>
      `<span class="dist-item">${r}: ${c} عذر</span>`
    ).join("")}
  </div>
</div>

<table>
  <thead>
    <tr>
      <th style="width:28px;text-align:center">م</th>
      <th>اسم الطالب</th>
      <th style="width:70px;text-align:center">الصف</th>
      <th style="width:110px">سبب الغياب</th>
      <th style="width:120px">يوم / التاريخ</th>
      <th>ولي الأمر</th>
      <th style="width:90px">الجوال</th>
      <th style="width:90px;text-align:center">الحالة</th>
      <th style="width:80px;text-align:center">تاريخ الإرسال</th>
    </tr>
  </thead>
  <tbody>${rows}</tbody>
</table>

<div class="sigs">
  <div class="sig">
    <div style="font-size:11px;color:#64748b;margin-bottom:4px">المشرف التربوي</div>
    <div style="height:30px"></div>
    <div style="font-size:10px;color:#94a3b8">الاسم والتوقيع</div>
  </div>
  <div class="sig">
    <div style="font-size:11px;color:#64748b;margin-bottom:4px">مدير المدرسة</div>
    <div style="font-size:13px;font-weight:900;color:#0d3b6e;margin:6px 0">فازع القرني</div>
    <div style="font-size:10px;color:#94a3b8">الاسم والتوقيع</div>
  </div>
  <div class="sig">
    <div style="font-size:11px;color:#64748b;margin-bottom:4px">التاريخ</div>
    <div style="font-size:13px;font-weight:900;color:#0d3b6e;margin:6px 0">${new Date().toLocaleDateString("ar-SA")}</div>
    <div style="font-size:10px;color:#94a3b8">هـ / م</div>
  </div>
</div>

<div class="footer">مدرسة الأمير عبدالمجيد المتوسطة الأولى — تقرير أعذار الطلاب</div>
<script>window.onload=()=>{window.print();}<\/script>
</body></html>`);
  win.document.close();
}

function StudentExcusePortal({ onBack, siteFont, isAdmin = false }) {
  const YEAR_KEY = new Date().getFullYear();
  const SITE_URL = window.location.origin + window.location.pathname;
  const EXCUSE_URL = SITE_URL + "#excuses";

  const [view,        setView]        = useState("login");
  const [student,     setStudent]     = useState(null);
  const [nationalId,  setNationalId]  = useState("");
  const [idError,     setIdError]     = useState("");
  const [excuses,     setExcuses]     = useState([]);
  const [students,    setStudents]    = useState([]);
  const [loading,     setLoading]     = useState(false);
  const [saving,      setSaving]      = useState(false);
  const [adminFilter, setAdminFilter] = useState("all");
  const [adminSearch, setAdminSearch] = useState("");
  const [page,        setPage]        = useState(1);
  const [archiveYear, setArchiveYear] = useState(null);
  const [archiveData, setArchiveData] = useState([]);
  const [copied,      setCopied]      = useState(false);
  const PER_PAGE = 20;
  const xlsRef = useRef();
  // ── إدارة الطلاب ──
  const [showStudentsPanel, setShowStudentsPanel] = useState(false);
  const [showAddStudent,    setShowAddStudent]    = useState(false);
  const [newStudentName,    setNewStudentName]    = useState("");
  const [newStudentId,      setNewStudentId]      = useState("");
  const [newStudentClass,   setNewStudentClass]   = useState("");
  const [studentSearch,     setStudentSearch]     = useState("");
  const [studentClassFilter,setStudentClassFilter]= useState("all");

  // ── نموذج العذر ──
  const [excuseType,    setExcuseType]    = useState("text");
  const [absenceDay,    setAbsenceDay]    = useState("");  // اليوم
  const [absenceDateH,  setAbsenceDateH]  = useState("");  // هجري
  const [absenceDateM,  setAbsenceDateM]  = useState("");  // ميلادي
  const [reason,        setReason]        = useState("");
  const [reasonCat,     setReasonCat]     = useState("مرض");
  const [fileData,      setFileData]      = useState(null);
  const [fileName,      setFileName]      = useState("");
  const [fileSize,      setFileSize]      = useState(0);
  const [parentName,    setParentName]    = useState("");
  const [parentPhone,   setParentPhone]   = useState("");
  const [parentRelation,setParentRelation]= useState("ولي الأمر");

  const REASON_CATS   = ["مرض","ظرف عائلي","سفر","حادث أو إصابة","موعد طبي","وفاة في العائلة","أخرى"];
  const RELATIONS     = ["ولي الأمر","الأب","الأم","الأخ","الأخت","العم","الخال","جهة رسمية","أخرى"];
  const WEEK_DAYS_AR  = ["الأحد","الاثنين","الثلاثاء","الأربعاء","الخميس","الجمعة","السبت"];
  const YEAR_KEYS     = [YEAR_KEY, YEAR_KEY - 1, YEAR_KEY - 2];

  // ── إعداد اليوم الحالي ──
  useEffect(() => {
    const today = new Date();
    const dayName = WEEK_DAYS_AR[today.getDay()];
    setAbsenceDay(dayName);
    // تاريخ ميلادي
    const dd = String(today.getDate()).padStart(2,"0");
    const mm = String(today.getMonth()+1).padStart(2,"0");
    const yyyy = today.getFullYear();
    setAbsenceDateM(`${dd}/${mm}/${yyyy}`);
    // تاريخ هجري تقريبي
    try {
      const h = gregorianToHijri(today.getFullYear(), today.getMonth()+1, today.getDate());
      setAbsenceDateH(`${String(h.d).padStart(2,"0")}/${String(h.m).padStart(2,"0")}/${h.y}`);
    } catch {}
  }, []);

  // ── تحميل البيانات ──
  useEffect(() => {
    // الأسماء من الكشوف المشتركة (غياب الحصة الثانية / التأخر الصباحي) — تتحدث تلقائياً
    maGet(MA_ROSTER).then(ros => {
      const arr = [];
      Object.entries(ros && typeof ros === "object" ? ros : {}).forEach(([ck, r]) => maArr(r && r.students).forEach(st => { if (st && st.name) arr.push({ id: st.id, name: st.name, className: maClassName(ck), ck, nh: st.nh || "", nationalId: st.n4 ? "***" + st.n4 : "" }); }));
      if (arr.length) setStudents(arr);
      else DB.get("school-excuse-students", []).then(d => { if (Array.isArray(d)) setStudents(d); });
    });
    if (isAdmin) {
      loadExcuses(YEAR_KEY);
      setView("admin");
    }
  }, []);

  const loadExcuses = async (year) => {
    setLoading(true);
    const data = await DB.get(`school-excuses-${year}`, {});
    const arr = Object.values(data || {}).sort((a, b) => b.id - a.id);
    if (year === YEAR_KEY) { setExcuses(arr); setArchiveYear(null); }
    else { setArchiveData(arr); setArchiveYear(year); }
    setLoading(false);
  };

  // ── البحث بالهوية ──
  const handleLogin = async () => {
    setIdError("");
    if (!nationalId.trim()) { setIdError("أدخل رقم هوية الطالب"); return; }
    const nn = licNormId(nationalId);
    if (nn.length >= 9) { const h = await stuHash(nn); const f = students.find(s => s.nh && s.nh === h); if (f) { setStudent({ ...f, nationalId: "***" + nn.slice(-4) }); setView("form"); return; } }
    const query = nationalId.trim().toLowerCase();
    const found = students.find(s =>
      (s.nationalId?.toString().trim().toLowerCase() === query) ||
      (s.id?.toString().trim().toLowerCase() === query)
    );
    if (!found) { setIdError("رقم الهوية غير موجود — تواصل مع إدارة المدرسة"); return; }
    setStudent(found);
    setView("form");
  };

  // ── رفع وضغط الصورة ──
  const handleFile = async (e) => {
    const file = e.target.files[0]; if (!file) return;
    if (file.size > 5 * 1024 * 1024) { alert("الحد الأقصى 5 ميجابايت"); e.target.value=""; return; }
    const reader = new FileReader();
    reader.onload = async (ev) => {
      let data = ev.target.result;
      if (file.type.startsWith("image/")) {
        data = await compressImage(data, 200);
        setFileSize(Math.round(data.length * 0.75 / 1024));
      } else {
        setFileSize(Math.round(file.size / 1024));
      }
      setFileData(data);
      setFileName(file.name);
    };
    reader.readAsDataURL(file);
    e.target.value = "";
  };

  // ── حفظ العذر ──
  const handleSubmit = async () => {
    if (!absenceDay) { alert("اختر يوم الغياب"); return; }
    if (!absenceDateM) { alert("أدخل تاريخ الغياب"); return; }
    if (!parentName.trim()) { alert("أدخل اسم المُرسِل"); return; }
    if (excuseType === "text" && !reason.trim()) { alert("أدخل نص العذر"); return; }
    if (excuseType !== "text" && !fileData) { alert("يرجى إرفاق الملف"); return; }
    setSaving(true);
    const id = Date.now();
    const rec = {
      id,
      studentId:     student.id || student.nationalId,
      studentName:   student.name,
      nationalId:    student.nationalId || student.id,
      className:     student.className || "",
      absenceDay,
      absenceDateH,
      absenceDateM,
      reasonCat,
      reason:        excuseType === "text" ? reason : "",
      excuseType,
      fileName:      excuseType !== "text" ? fileName : "",
      fileData:      excuseType !== "text" ? fileData : "",
      fileSizeKB:    fileSize,
      parentName,
      parentPhone,
      parentRelation,
      status:        "قيد المراجعة",
      submittedAt:   new Date().toLocaleDateString("ar-SA"),
      year:          YEAR_KEY,
    };
    const key = `school-excuses-${YEAR_KEY}`;
    const existing = await DB.get(key, {});
    await DB.set(key, { ...existing, [id]: rec });
    setExcuses(prev => [rec, ...prev]);
    setSaving(false);
    setView("success");
  };

  const [adminReplyDraft, setAdminReplyDraft] = useState({}); // { [excuseId]: "نص الرد" }
  const [replyOpen,       setReplyOpen]       = useState({}); // { [excuseId]: bool }

  // ── طباعة عذر فردي ──
  const printExcuse = (ex) => {
    const sc = statusColor(ex.status);
    printWindow(`<!DOCTYPE html><html dir="rtl"><head><meta charset="utf-8">
    <title>عذر ${ex.studentName}</title>
    <style>
      *{margin:0;padding:0;box-sizing:border-box}
      body{font-family:'Noto Sans Arabic',Arial,sans-serif;direction:rtl;background:#fff;color:#111;padding:32px}
      .school{text-align:center;font-size:12px;color:#555;margin-bottom:4px}
      h1{text-align:center;font-size:20px;font-weight:900;color:#1e3a5f;margin-bottom:18px;border-bottom:3px solid #1d4ed8;padding-bottom:10px}
      .grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:16px}
      .field{background:#f8fafc;border-radius:8px;padding:10px 14px;border:1px solid #e2e8f0}
      .label{font-size:10px;font-weight:700;color:#64748b;margin-bottom:4px}
      .val{font-size:14px;font-weight:800;color:#1e293b}
      .reason-box{background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px;padding:14px;margin-bottom:16px}
      .status{display:inline-block;padding:4px 14px;border-radius:20px;font-size:13px;font-weight:800;
              background:${sc.bg};color:${sc.color};border:1px solid ${sc.border}}
      .admin-reply{background:#f0fdf4;border:1px solid #86efac;border-radius:8px;padding:14px;margin-bottom:16px}
      .sig{display:grid;grid-template-columns:1fr 1fr;gap:40px;margin-top:40px;text-align:center;font-size:12px;color:#374151}
      .sig-line{border-top:1.5px solid #374151;padding-top:8px;margin-top:28px;font-weight:700}
      @media print{@page{size:A4;margin:2cm}body{padding:0}}
    </style></head><body>
    <div class="school">إدارة تعليم جدة — مدرسة الأمير عبدالمجيد المتوسطة الأولى</div>
    <h1>📋 نموذج عذر طالب</h1>
    <div class="grid">
      <div class="field"><div class="label">👤 اسم الطالب</div><div class="val">${ex.studentName}</div></div>
      <div class="field"><div class="label">🪪 رقم الهوية</div><div class="val" style="font-family:monospace">${ex.nationalId}</div></div>
      <div class="field"><div class="label">🏫 الفصل</div><div class="val">${ex.className||"—"}</div></div>
      <div class="field"><div class="label">📅 يوم الغياب</div><div class="val">${ex.absenceDay}</div></div>
      <div class="field"><div class="label">🌙 التاريخ الهجري</div><div class="val">${ex.absenceDateH} هـ</div></div>
      <div class="field"><div class="label">☀️ التاريخ الميلادي</div><div class="val">${ex.absenceDateM} م</div></div>
      <div class="field"><div class="label">👤 مقدّم العذر</div><div class="val">${ex.parentRelation||"ولي الأمر"}: ${ex.parentName}</div></div>
      <div class="field"><div class="label">📱 الجوال</div><div class="val">${ex.parentPhone||"—"}</div></div>
    </div>
    <div class="reason-box">
      <div class="label" style="margin-bottom:8px">📝 سبب الغياب — ${ex.reasonCat}</div>
      <div style="font-size:14px;line-height:1.9;color:#1e3a5f">${ex.reason || "(مرفق ملف)"}</div>
    </div>
    <div style="margin-bottom:16px">
      <span class="label" style="margin-left:8px">الحالة:</span>
      <span class="status">${ex.status}</span>
      <span style="font-size:11px;color:#94a3b8;margin-right:12px">تقديم: ${ex.submittedAt}</span>
    </div>
    ${ex.adminReply ? `<div class="admin-reply">
      <div class="label" style="margin-bottom:6px;color:#065f46">📌 رد الإدارة — ${ex.adminReplyAt||""}</div>
      <div style="font-size:14px;line-height:1.9;color:#065f46;font-weight:700">${ex.adminReply}</div>
    </div>` : ""}
    <div class="sig">
      <div><div class="sig-line">توقيع ولي الأمر</div></div>
      <div><div class="sig-line">مدير المدرسة<br>فازع عبدالله حسن القرني</div></div>
    </div>
    <script>window.onload=()=>window.print()</script>
    </body></html>`);
  };

  // ── أرشفة أعذار الأسبوع ──
  const archiveWeekExcuses = async () => {
    const list = archiveYear ? archiveData : excuses;
    if (list.length === 0) { alert("لا توجد أعذار للأرشفة"); return; }
    const weekNums = [...new Set(list.map(ex => {
      const d = ex.absenceDateM?.split("/")||[];
      return d.length===3 ? `${d[2]}-W${Math.ceil(parseInt(d[0])/7)}` : "غير محدد";
    }))].join(", ");
    if (!window.confirm(`أرشفة الأعذار الحالية (${list.length} عذر) كأسبوع مؤرشف؟\nنطاق التواريخ: ${weekNums}\n\n⚠️ الأعذار لن تُحذف — ستظل موجودة.`)) return;
    const archKey = `school-excuses-archive-${Date.now()}`;
    await DB.set(archKey, { archivedAt: new Date().toLocaleDateString("ar-SA"), excuses: list });
    alert("✅ تمت أرشفة الأعذار بنجاح! يمكن استردادها من Firebase بالمفتاح:\n" + archKey);
  };

  // ── حفظ رد الإدارة ──
  const saveAdminReply = async (excuseId) => {
    const txt = (adminReplyDraft[excuseId]||"").trim();
    if (!txt) { alert("أدخل نص الرد أولاً"); return; }
    const key = `school-excuses-${archiveYear || YEAR_KEY}`;
    const existing = await DB.get(key, {});
    if (existing[excuseId]) {
      existing[excuseId].adminReply   = txt;
      existing[excuseId].adminReplyAt = new Date().toLocaleDateString("ar-SA");
      await DB.set(key, existing);
    }
    const upd = ex => ex.id === excuseId ? { ...ex, adminReply: txt, adminReplyAt: new Date().toLocaleDateString("ar-SA") } : ex;
    if (archiveYear) setArchiveData(prev => prev.map(upd));
    else setExcuses(prev => prev.map(upd));
    setReplyOpen(p => ({ ...p, [excuseId]: false }));
    setAdminReplyDraft(p => ({ ...p, [excuseId]: "" }));
    alert("✅ تم حفظ رد الإدارة");
  };

  // ── نسخ الرابط ──
  const copyLink = () => {
    navigator.clipboard.writeText(EXCUSE_URL).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 2500);
    });
  };

  // ── تحديث حالة ──
  const updateStatus = async (excuseId, newStatus) => {
    const key = `school-excuses-${archiveYear || YEAR_KEY}`;
    const existing = await DB.get(key, {});
    if (existing[excuseId]) { existing[excuseId].status = newStatus; await DB.set(key, existing); }
    const update = ex => ex.id === excuseId ? { ...ex, status: newStatus } : ex;
    if (archiveYear) setArchiveData(prev => prev.map(update));
    else setExcuses(prev => prev.map(update));
  };

  const deleteAllExcuses = async () => {
    const key = `school-excuses-${archiveYear || YEAR_KEY}`;
    const n = (archiveYear ? archiveData : excuses).length;
    if (!n) { alert("لا توجد أعذار للمسح"); return; }
    if (!window.confirm(`⚠️ مسح جميع الأعذار (${n} عذر) لعام ${archiveYear || YEAR_KEY} نهائياً؟`)) return;
    if (!window.confirm("تأكيد أخير: لا يمكن التراجع عن المسح. متابعة؟")) return;
    await DB.set(key, {});
    if (archiveYear) setArchiveData([]); else setExcuses([]);
    alert("🗑 تم مسح جميع الأعذار");
  };
  const deleteExcuse = async (excuseId) => {
    const ex0 = (archiveYear ? archiveData : excuses).find(x => x.id === excuseId);
    if (!window.confirm(`حذف عذر الطالب «${ex0?.studentName || ""}» نهائياً؟`)) return;
    const key = `school-excuses-${archiveYear || YEAR_KEY}`;
    const existing = await DB.get(key, {});
    delete existing[excuseId];
    await DB.set(key, existing);
    const filter = ex => ex.id !== excuseId;
    if (archiveYear) setArchiveData(prev => prev.filter(filter));
    else setExcuses(prev => prev.filter(filter));
  };

  const handleXLS = async (e) => {
    const file = e.target.files[0]; if (!file) return;
    try {
      await loadXLSX();
      const buf = await file.arrayBuffer();
      const wb = window.XLSX.read(buf);
      const imported = [];

      wb.SheetNames.forEach((sheetName, sheetIdx) => {
        const ws = wb.Sheets[sheetName];
        const rows = window.XLSX.utils.sheet_to_json(ws, { header:1, defval:"" });

        // ── اكتشاف تلقائي لصف الهيدر ──
        // نبحث عن صف يحتوي على "الاسم" أو "اسم" أو "name" أو نصف بيانات رقمية
        let dataStartRow = 1; // افتراضي: بداية من الصف الثاني
        let nameCol = 0, idCol = 1, classCol = 2;

        for (let i = 0; i < Math.min(rows.length, 25); i++) {
          const row = rows[i];
          const vals = row.map(v => String(v||"").trim());
          // البحث عن صف الهيدر
          const nameIdx = vals.findIndex(v => v === "الاسم" || v.toLowerCase() === "name");
          const idIdx   = vals.findIndex(v => v.includes("هوية") || v.includes("سجل") || v.includes("id") || v.toLowerCase().includes("national"));
          if (nameIdx !== -1) {
            nameCol = nameIdx;
            if (idIdx !== -1) idCol = idIdx;
            // البحث عن عمود الفصل
            const clsIdx = vals.findIndex(v => v.includes("فصل") || v.includes("class") || v.includes("شعبة"));
            if (clsIdx !== -1) classCol = clsIdx;
            dataStartRow = i + 1;
            break;
          }
        }

        // ── استخراج اسم الفصل من رأس الكشف الرسمي ──
        // في كشوف وزارة التعليم: الصف الدراسي في الصف الثاني عمود B (index 1,1)
        // رقم الفصل في الصف الثامن عمود B (index 7,1)
        const gradeLevel  = String((rows[1]||[])[1]||"").trim().replace(/nan/g,"");
        const classNumber = String((rows[7]||[])[1]||"").trim().replace(/nan/g,"");
        let detectedClass;
        if (gradeLevel && classNumber && classNumber !== "الكل") {
          detectedClass = `${gradeLevel} - ${classNumber}`;
        } else if (gradeLevel) {
          // إذا كان "الكل" نعطي رقم تسلسلي للفصل
          const sheetNum = wb.SheetNames.indexOf(sheetName) + 1;
          detectedClass = `${gradeLevel} - فصل ${sheetNum}`;
        } else {
          detectedClass = sheetName;
        }

        rows.forEach((row, i) => {
          if (i < dataStartRow) return;
          const name  = String(row[nameCol]||"").trim();
          const natId = String(row[idCol]||"").trim().replace(/[^0-9a-zA-Z]/g,"");
          // محاولة قراءة الفصل من العمود أو استخدام المكتشف
          const cls   = classCol < row.length ? String(row[classCol]||"").trim() : "";
          const finalClass = (cls && cls !== name && cls !== natId && cls.length > 0) ? cls : detectedClass;

          // تجاهل الصفوف الفارغة أو التي تحتوي على نصوص هيدر
          if (!name || name === "الاسم" || name.length < 2) return;
          // تجاهل الصفوف التي ليس فيها هوية صالحة
          if (!natId || natId.length < 4) return;

          imported.push({
            id: natId,
            name,
            nationalId: natId,
            className: finalClass
          });
        });
      });

      if (imported.length) {
        const merged = [...students];
        let added = 0;
        imported.forEach(ns => {
          if (!merged.find(s => s.nationalId === ns.nationalId)) {
            merged.push(ns);
            added++;
          }
        });
        setStudents(merged);
        await DB.set("school-excuse-students", merged);
        alert(`✅ تم استيراد ${added} طالب جديد من ${wb.SheetNames.length} شيت\nإجمالي الطلاب: ${merged.length}`);
      } else {
        alert("⚠️ لم يتم العثور على بيانات طلاب في الملف");
      }
    } catch(err) { alert("خطأ في قراءة الملف: " + err.message); }
    e.target.value = "";
  };

  // ── إضافة طالب يدوياً ──
  const addStudentManually = async () => {
    if (!newStudentName.trim()) { alert("أدخل اسم الطالب"); return; }
    if (!newStudentId.trim())   { alert("أدخل رقم الهوية"); return; }
    if (students.find(s => s.nationalId?.toString().trim() === newStudentId.trim())) {
      alert("رقم الهوية موجود مسبقاً"); return;
    }
    const ns = { id: newStudentId.trim(), name: newStudentName.trim(),
                  nationalId: newStudentId.trim(), className: newStudentClass.trim() };
    const merged = [...students, ns];
    setStudents(merged);
    await DB.set("school-excuse-students", merged);
    setNewStudentName(""); setNewStudentId(""); setNewStudentClass("");
    setShowAddStudent(false);
    alert("✅ تمت إضافة الطالب بنجاح");
  };

  // ── حذف طالب ──
  const deleteStudent = async (sid) => {
    if (students.some(s => s.ck)) { alert("الأسماء تُدار من كشوف الفصول المشتركة: «سجل التأخر الصباحي ← الفصول» — اضغط على الفصل لتعديل الطالب أو حذفه"); return; }
    if (!window.confirm("حذف هذا الطالب؟")) return;
    const merged = students.filter(s => s.id !== sid && s.nationalId !== sid);
    setStudents(merged);
    await DB.set("school-excuse-students", merged);
  };

  // ── تصدير الطلاب Excel مصنّف حسب الفصل ──
  const exportStudentsExcel = async () => {
    await loadXLSX();
    const wb = window.XLSX.utils.book_new();
    // فصل الطلاب حسب الفصل
    const classes = {};
    students.forEach(s => {
      const cls = s.className?.trim() || "غير محدد";
      if (!classes[cls]) classes[cls] = [];
      classes[cls].push(s);
    });
    // ورقة كاملة
    const allRows = [["الاسم","رقم الهوية","الفصل"]];
    students.forEach(s => allRows.push([s.name||"", s.nationalId||s.id||"", s.className||""]));
    window.XLSX.utils.book_append_sheet(wb, window.XLSX.utils.aoa_to_sheet(allRows), "كل الطلاب");
    // ورقة لكل فصل
    Object.entries(classes).forEach(([cls, arr]) => {
      const rows = [["الاسم","رقم الهوية","الفصل"]];
      arr.forEach(s => rows.push([s.name||"", s.nationalId||s.id||"", s.className||""]));
      const safeName = cls.replace(/[\/\\?*\[\]]/g,"").slice(0,31);
      window.XLSX.utils.book_append_sheet(wb, window.XLSX.utils.aoa_to_sheet(rows), safeName);
    });
    window.XLSX.writeFile(wb, `طلاب_الأعذار_${new Date().getFullYear()}.xlsx`);
  };

  const statusColor = (s) => ({
    "قيد المراجعة": { bg:"#fef3c7", color:"#92400e", border:"#fde68a" },
    "مقبول":        { bg:"#d1fae5", color:"#065f46",  border:"#6ee7b7" },
    "مرفوض":        { bg:"#fee2e2", color:"#991b1b",  border:"#fca5a5" },
  }[s] || { bg:"#f3f4f6", color:"#374151", border:"#e5e7eb" });

  const currentList = archiveYear ? archiveData : excuses;
  const filteredExcuses = currentList.filter(ex => {
    if (adminFilter === "pending")  return ex.status === "قيد المراجعة";
    if (adminFilter === "accepted") return ex.status === "مقبول";
    if (adminFilter === "rejected") return ex.status === "مرفوض";
    return true;
  }).filter(ex =>
    !adminSearch || ex.studentName?.includes(adminSearch) || ex.nationalId?.includes(adminSearch)
  );

  const totalPages = Math.ceil(filteredExcuses.length / PER_PAGE);
  const pageData   = filteredExcuses.slice((page-1)*PER_PAGE, page*PER_PAGE);
  const counts = {
    all:      currentList.length,
    pending:  currentList.filter(ex=>ex.status==="قيد المراجعة").length,
    accepted: currentList.filter(ex=>ex.status==="مقبول").length,
    rejected: currentList.filter(ex=>ex.status==="مرفوض").length,
  };
  const totalSizeKB = Math.round(currentList.reduce((s,ex)=>s+(ex.fileSizeKB||0)+1,0));

  const S = {
    page:  { minHeight:"100vh", background:"#f0f4f8", fontFamily:"'Cairo','Noto Naskh Arabic',sans-serif", direction:"rtl" },
    card:  { background:"#fff", borderRadius:16, boxShadow:"0 4px 20px rgba(0,0,0,0.07)", border:"1px solid #e2e8f0" },
    hdr:   { background:"linear-gradient(135deg,#1e3a5f 0%,#1d4ed8 60%,#0e7c7b 100%)", color:"#fff",
              padding:"14px 18px", display:"flex", alignItems:"center", gap:10, flexWrap:"wrap",
              position:"sticky", top:0, zIndex:50, boxShadow:"0 2px 12px rgba(0,0,0,0.2)" },
    btn:   { padding:"10px 20px", borderRadius:12, border:"none", fontWeight:900, fontSize:13,
              cursor:"pointer", fontFamily:"'Cairo',sans-serif", transition:"all .15s" },
    input: { width:"100%", padding:"11px 14px", border:"1.5px solid #e2e8f0", borderRadius:10,
              fontFamily:"'Cairo',sans-serif", fontSize:14, color:"#1e293b", outline:"none",
              background:"#f8fafc", direction:"rtl", boxSizing:"border-box" },
    select:{ width:"100%", padding:"11px 14px", border:"1.5px solid #e2e8f0", borderRadius:10,
              fontFamily:"'Cairo',sans-serif", fontSize:14, color:"#1e293b", outline:"none",
              background:"#f8fafc", direction:"rtl", cursor:"pointer" },
  };

  // ═══ لوحة الإدارة ═══
  if (view === "admin") {
    return (
      <div style={S.page}>
        <div style={S.hdr}>
          {onBack && <button onClick={onBack} style={{ background:"rgba(255,255,255,0.15)", border:"none",
            borderRadius:10, color:"#fff", fontWeight:800, fontSize:12, padding:"6px 12px",
            cursor:"pointer", fontFamily:"'Cairo',sans-serif" }}>← رجوع</button>}
          <span style={{ fontSize:22 }}>📋</span>
          <div style={{ flex:1 }}>
            <div style={{ fontWeight:900, fontSize:15 }}>إدارة أعذار الطلاب</div>
            <div style={{ opacity:.7, fontSize:11 }}>
              {archiveYear ? `أرشيف ${archiveYear}` : `العام الحالي ${YEAR_KEY}`} · {totalSizeKB}KB
            </div>
          </div>
          <button onClick={()=>printAllExcuses(filteredExcuses)}
            style={{ ...S.btn, background:"rgba(255,255,255,0.2)", color:"#fff", fontSize:11, padding:"7px 12px",
                     border:"1px solid rgba(255,255,255,0.3)" }}>
            🖨️ طباعة الكل
          </button>
          <button onClick={archiveWeekExcuses}
            style={{ ...S.btn, background:"rgba(255,255,255,0.2)", color:"#fff", fontSize:11, padding:"7px 12px",
                     border:"1px solid rgba(255,255,255,0.3)" }}>
            🗂️ أرشفة الأسبوع
          </button>
          {/* زر نسخ الرابط */}
          <button onClick={copyLink}
            style={{ ...S.btn, background: copied ? "rgba(110,231,183,0.3)" : "rgba(255,255,255,0.15)",
                     color:"#fff", fontSize:11, padding:"7px 12px",
                     border:"1px solid rgba(255,255,255,0.3)" }}>
            {copied ? "✅ تم النسخ" : "🔗 نسخ رابط الأعذار"}
          </button>
          <select value={archiveYear || YEAR_KEY} onChange={e => loadExcuses(Number(e.target.value))}
            style={{ padding:"6px 10px", borderRadius:8, border:"1px solid rgba(255,255,255,0.3)",
                     background:"rgba(255,255,255,0.15)", color:"#fff",
                     fontFamily:"'Cairo',sans-serif", fontSize:12, cursor:"pointer" }}>
            {YEAR_KEYS.map(y => <option key={y} value={y} style={{ background:"#1e3a5f" }}>
              {y === YEAR_KEY ? `${y} (الحالي)` : `${y} (أرشيف)`}
            </option>)}
          </select>
          <span style={{ ...S.btn, background:"rgba(16,185,129,0.25)", color:"#fff", fontSize:11, padding:"7px 12px", cursor:"default" }} title="الأسماء تُحدَّث تلقائياً من كشوف الفصول المشتركة">
            🔄 الأسماء من كشوف الفصول
          </span>
          <button onClick={deleteAllExcuses}
            style={{ ...S.btn, background:"rgba(239,68,68,0.3)", color:"#fff", fontSize:11, padding:"7px 12px", border:"1px solid rgba(254,202,202,0.6)" }}>
            🗑 مسح جميع الأعذار
          </button>
          {/* أيقونة عرض الطلاب */}
          <button onClick={()=>{ setShowStudentsPanel(v=>!v); setShowAddStudent(false); }}
            style={{ ...S.btn, background: showStudentsPanel ? "rgba(110,231,183,0.35)" : "rgba(255,255,255,0.2)",
                     color:"#fff", fontSize:11, padding:"7px 12px",
                     border: showStudentsPanel ? "1.5px solid #6ee7b7" : "1px solid rgba(255,255,255,0.3)" }}>
            👥 الطلاب ({students.length})
          </button>
          {/* أيقونة إضافة طالب */}
          <button onClick={()=>{ if (students.some(s => s.ck)) { alert("لإضافة طالب: «سجل التأخر الصباحي ← الفصول» ← اضغط على الفصل ← إضافة — يظهر هنا تلقائياً"); return; } setShowAddStudent(v=>!v); setShowStudentsPanel(false); }}
            style={{ ...S.btn, background: showAddStudent ? "rgba(253,224,71,0.35)" : "rgba(255,255,255,0.2)",
                     color:"#fff", fontSize:11, padding:"7px 12px",
                     border: showAddStudent ? "1.5px solid #fde047" : "1px solid rgba(255,255,255,0.3)" }}>
            ➕ إضافة طالب
          </button>
          <input ref={xlsRef} type="file" accept=".xlsx,.xls,.csv" style={{ display:"none" }} onChange={handleXLS} />
        </div>

        <div style={{ maxWidth:1000, margin:"0 auto", padding:"14px 12px 60px" }}>

          {/* ─── لوحة عرض الطلاب ─── */}
          {showStudentsPanel && (() => {
            const classes = [...new Set(students.map(s => s.className?.trim()||"غير محدد"))].sort();
            const filtered = students.filter(s => {
              const matchClass = studentClassFilter === "all" || (s.className?.trim()||"غير محدد") === studentClassFilter;
              const matchSearch = !studentSearch || s.name?.includes(studentSearch) || (s.nationalId||s.id)?.includes(studentSearch);
              return matchClass && matchSearch;
            });
            return (
              <div style={{ ...S.card, marginBottom:14, overflow:"hidden" }}>
                <div style={{ background:"linear-gradient(135deg,#1e3a5f,#0e7c7b)", padding:"12px 16px",
                  display:"flex", alignItems:"center", gap:10, flexWrap:"wrap" }}>
                  <span style={{ fontSize:20 }}>👥</span>
                  <div style={{ flex:1, color:"#fff", fontWeight:900, fontSize:14 }}>
                    قائمة الطلاب — {students.length} طالب
                  </div>
                  <button onClick={exportStudentsExcel}
                    style={{ ...S.btn, background:"rgba(255,255,255,0.2)", color:"#fff", fontSize:11, padding:"6px 12px" }}>
                    📊 تصدير Excel مصنّف
                  </button>
                  <button onClick={()=>setShowStudentsPanel(false)}
                    style={{ background:"rgba(255,255,255,0.15)", border:"none", borderRadius:8,
                             color:"#fff", fontSize:16, width:28, height:28, cursor:"pointer",
                             display:"flex", alignItems:"center", justifyContent:"center" }}>✕</button>
                </div>
                <div style={{ padding:"12px 14px" }}>
                  <div style={{ display:"flex", gap:8, flexWrap:"wrap", marginBottom:10 }}>
                    <input value={studentSearch} onChange={e=>setStudentSearch(e.target.value)}
                      placeholder="🔍 بحث بالاسم أو الهوية"
                      style={{ ...S.input, flex:"1 1 160px", fontSize:12 }} />
                    <select value={studentClassFilter} onChange={e=>setStudentClassFilter(e.target.value)}
                      style={{ ...S.select, flex:"0 0 120px", fontSize:12 }}>
                      <option value="all">كل الفصول ({students.length})</option>
                      {classes.map(c => <option key={c} value={c}>{c} ({students.filter(s=>(s.className?.trim()||"غير محدد")===c).length})</option>)}
                    </select>
                  </div>
                  {filtered.length === 0 ? (
                    <div style={{ textAlign:"center", padding:"24px", color:"#94a3b8", fontSize:13 }}>لا يوجد طلاب</div>
                  ) : (
                    <div style={{ maxHeight:320, overflowY:"auto" }}>
                      <table style={{ width:"100%", borderCollapse:"collapse", fontSize:12.5 }}>
                        <thead>
                          <tr style={{ background:"#f1f5f9", borderBottom:"2px solid #e2e8f0" }}>
                            <th style={{ padding:"8px 10px", textAlign:"right", fontWeight:800, color:"#475569" }}>#</th>
                            <th style={{ padding:"8px 10px", textAlign:"right", fontWeight:800, color:"#475569" }}>الاسم</th>
                            <th style={{ padding:"8px 10px", textAlign:"right", fontWeight:800, color:"#475569" }}>🪪 رقم الهوية</th>
                            <th style={{ padding:"8px 10px", textAlign:"right", fontWeight:800, color:"#475569" }}>🏫 الفصل</th>
                            <th style={{ padding:"8px 10px", textAlign:"center", fontWeight:800, color:"#475569" }}>حذف</th>
                          </tr>
                        </thead>
                        <tbody>
                          {filtered.map((s,i) => (
                            <tr key={s.nationalId||s.id} style={{ borderBottom:"1px solid #f1f5f9",
                              background: i%2===0 ? "#fff" : "#f8fafc" }}>
                              <td style={{ padding:"7px 10px", color:"#94a3b8", fontWeight:700 }}>{i+1}</td>
                              <td style={{ padding:"7px 10px", fontWeight:700, color:"#1e293b" }}>{s.name}</td>
                              <td style={{ padding:"7px 10px", fontFamily:"monospace", color:"#1d4ed8",
                                fontWeight:700, letterSpacing:1 }}>{s.nationalId||s.id}</td>
                              <td style={{ padding:"7px 10px" }}>
                                <span style={{ background:"#eff6ff", color:"#1d4ed8", padding:"2px 10px",
                                  borderRadius:20, fontWeight:700, fontSize:11 }}>
                                  {s.className||"—"}
                                </span>
                              </td>
                              <td style={{ padding:"7px 10px", textAlign:"center" }}>
                                <button onClick={()=>deleteStudent(s.nationalId||s.id)}
                                  style={{ background:"#fee2e2", border:"none", borderRadius:6, color:"#991b1b",
                                    fontSize:12, padding:"3px 8px", cursor:"pointer" }}>🗑️</button>
                              </td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  )}
                </div>
              </div>
            );
          })()}

          {/* ─── فورم إضافة طالب ─── */}
          {showAddStudent && (
            <div style={{ ...S.card, marginBottom:14, overflow:"hidden" }}>
              <div style={{ background:"linear-gradient(135deg,#065f46,#0d9488)", padding:"12px 16px",
                display:"flex", alignItems:"center", gap:10 }}>
                <span style={{ fontSize:20 }}>➕</span>
                <div style={{ flex:1, color:"#fff", fontWeight:900, fontSize:14 }}>إضافة طالب جديد</div>
                <button onClick={()=>setShowAddStudent(false)}
                  style={{ background:"rgba(255,255,255,0.15)", border:"none", borderRadius:8,
                           color:"#fff", fontSize:16, width:28, height:28, cursor:"pointer",
                           display:"flex", alignItems:"center", justifyContent:"center" }}>✕</button>
              </div>
              <div style={{ padding:"16px 14px" }}>
                <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 1fr", gap:10, marginBottom:12 }}>
                  <div>
                    <label style={{ fontSize:11.5, fontWeight:700, color:"#64748b", display:"block", marginBottom:5 }}>
                      👤 اسم الطالب *
                    </label>
                    <input value={newStudentName} onChange={e=>setNewStudentName(e.target.value)}
                      placeholder="اسم الطالب الكامل"
                      style={{ ...S.input, fontSize:13 }} />
                  </div>
                  <div>
                    <label style={{ fontSize:11.5, fontWeight:700, color:"#64748b", display:"block", marginBottom:5 }}>
                      🪪 رقم الهوية *
                    </label>
                    <input value={newStudentId} onChange={e=>setNewStudentId(e.target.value)}
                      placeholder="رقم الهوية الوطنية"
                      style={{ ...S.input, fontSize:13, fontFamily:"monospace", letterSpacing:1 }} />
                  </div>
                  <div>
                    <label style={{ fontSize:11.5, fontWeight:700, color:"#64748b", display:"block", marginBottom:5 }}>
                      🏫 الفصل
                    </label>
                    <input value={newStudentClass} onChange={e=>setNewStudentClass(e.target.value)}
                      placeholder="مثال: 1أ / 2ب"
                      style={{ ...S.input, fontSize:13 }} />
                  </div>
                </div>
                <button onClick={addStudentManually}
                  style={{ ...S.btn, background:"linear-gradient(135deg,#065f46,#0d9488)",
                           color:"#fff", fontSize:13, padding:"10px 24px" }}>
                  ✅ إضافة الطالب
                </button>
              </div>
            </div>
          )}

          {/* رابط مستمر */}
          <div style={{ ...S.card, padding:"12px 16px", marginBottom:14,
            background:"linear-gradient(135deg,#eff6ff,#f0fdf4)",
            border:"1.5px solid #93c5fd", display:"flex", alignItems:"center", gap:10, flexWrap:"wrap" }}>
            <span style={{ fontSize:18 }}>🔗</span>
            <div style={{ flex:1 }}>
              <div style={{ fontWeight:900, fontSize:12.5, color:"#1e3a5f", marginBottom:3 }}>
                الرابط المباشر لبوابة الأعذار — أرسله لأولياء الأمور
              </div>
              <code style={{ fontSize:11.5, color:"#1d4ed8", background:"#dbeafe",
                padding:"3px 8px", borderRadius:6, userSelect:"all" }}>{EXCUSE_URL}</code>
            </div>
            <button onClick={copyLink}
              style={{ ...S.btn, background: copied ? "#d1fae5" : "#1d4ed8",
                       color: copied ? "#065f46" : "#fff", fontSize:12, padding:"8px 16px" }}>
              {copied ? "✅ تم النسخ" : "نسخ الرابط 📋"}
            </button>
          </div>

          {/* إحصائيات */}
          <div style={{ display:"grid", gridTemplateColumns:"repeat(4,1fr)", gap:8, marginBottom:14 }}>
            {[
              { label:"الكل",         n:counts.all,      color:"#1d4ed8", bg:"#eff6ff" },
              { label:"قيد المراجعة", n:counts.pending,  color:"#92400e", bg:"#fef3c7" },
              { label:"مقبول",        n:counts.accepted, color:"#065f46", bg:"#d1fae5" },
              { label:"مرفوض",        n:counts.rejected, color:"#991b1b", bg:"#fee2e2" },
            ].map(s=>(
              <div key={s.label} style={{ ...S.card, padding:"12px 10px", textAlign:"center",
                background:s.bg, border:`1.5px solid ${s.color}33` }}>
                <div style={{ fontSize:26, fontWeight:900, color:s.color }}>{s.n}</div>
                <div style={{ fontSize:10.5, fontWeight:700, color:s.color, marginTop:2 }}>{s.label}</div>
              </div>
            ))}
          </div>

          {/* شريط البحث */}
          <div style={{ ...S.card, padding:"10px 12px", marginBottom:12,
            display:"flex", gap:8, flexWrap:"wrap", alignItems:"center" }}>
            <input value={adminSearch} onChange={e=>{setAdminSearch(e.target.value);setPage(1);}}
              placeholder="🔍 بحث باسم الطالب أو الهوية..."
              style={{ ...S.input, flex:"1 1 180px", fontSize:13 }} />
            <div style={{ display:"flex", gap:5, flexWrap:"wrap" }}>
              {[["all","الكل"],["pending","مراجعة"],["accepted","مقبول"],["rejected","مرفوض"]].map(([v,l])=>(
                <button key={v} onClick={()=>{setAdminFilter(v);setPage(1);}}
                  style={{ padding:"6px 12px", borderRadius:20, fontSize:11.5, fontWeight:700,
                           cursor:"pointer", border:"1.5px solid",
                           borderColor: adminFilter===v?"#1d4ed8":"#e2e8f0",
                           background:  adminFilter===v?"#1d4ed8":"#f8fafc",
                           color:       adminFilter===v?"#fff":"#64748b",
                           fontFamily:"'Cairo',sans-serif" }}>{l}</button>
              ))}
            </div>
          </div>

          {/* تنسيق Excel */}
          <div style={{ background:"#eff6ff", border:"1px solid #bfdbfe", borderRadius:10,
            padding:"8px 14px", marginBottom:12, fontSize:11.5, color:"#1e40af", fontWeight:600 }}>
            📌 يدعم ملفات كشوف الأسماء الرسمية (متعددة الشيتات) · أو تنسيق بسيط: <strong>عمود أ</strong> الاسم | <strong>عمود ب</strong> رقم الهوية | <strong>عمود ج</strong> الفصل
          </div>

          {/* القائمة */}
          {loading ? (
            <div style={{ textAlign:"center", padding:"40px", color:"#64748b" }}>
              <div style={{ fontSize:30, marginBottom:8 }}>⏳</div><div style={{ fontWeight:700 }}>جارٍ التحميل...</div>
            </div>
          ) : filteredExcuses.length === 0 ? (
            <div style={{ textAlign:"center", padding:"40px", color:"#94a3b8" }}>
              <div style={{ fontSize:38, marginBottom:8 }}>📭</div>
              <div style={{ fontWeight:700, fontSize:13 }}>لا توجد أعذار</div>
            </div>
          ) : (
            <>
              <div style={{ display:"flex", flexDirection:"column", gap:10, marginBottom:14 }}>
                {pageData.map(ex => {
                  const sc = statusColor(ex.status);
                  return (
                    <div key={ex.id} style={{ ...S.card, padding:"14px", borderRight:`4px solid ${sc.border}` }}>
                      <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", flexWrap:"wrap", gap:8 }}>
                        <div style={{ display:"flex", alignItems:"center", gap:10 }}>
                          <div style={{ width:42, height:42, borderRadius:12, flexShrink:0,
                            background:"linear-gradient(135deg,#1e3a5f,#1d4ed8)",
                            display:"flex", alignItems:"center", justifyContent:"center",
                            color:"#fff", fontWeight:900, fontSize:18 }}>
                            {ex.studentName?.charAt(0)||"؟"}
                          </div>
                          <div>
                            <div style={{ fontWeight:900, fontSize:13.5, color:"#1e293b" }}>{ex.studentName}</div>
                            <div style={{ fontSize:11, color:"#64748b", marginTop:1 }}>
                              🪪 {ex.nationalId} · 🏫 {ex.className||"—"} · 📅 {ex.submittedAt}
                            </div>
                          </div>
                        </div>
                        <div style={{ display:"flex", gap:5, flexWrap:"wrap", alignItems:"center" }}>
                          <span style={{ padding:"3px 10px", borderRadius:20, fontSize:11.5, fontWeight:700,
                            background:sc.bg, color:sc.color, border:`1px solid ${sc.border}` }}>
                            {ex.status}
                          </span>
                          {ex.status === "قيد المراجعة" && (<>
                            <button onClick={()=>updateStatus(ex.id,"مقبول")}
                              style={{ padding:"4px 10px", borderRadius:8, border:"none",
                                       background:"#d1fae5", color:"#065f46", fontWeight:800,
                                       fontSize:11.5, cursor:"pointer", fontFamily:"'Cairo',sans-serif" }}>✅ قبول</button>
                            <button onClick={()=>updateStatus(ex.id,"مرفوض")}
                              style={{ padding:"4px 10px", borderRadius:8, border:"none",
                                       background:"#fee2e2", color:"#991b1b", fontWeight:800,
                                       fontSize:11.5, cursor:"pointer", fontFamily:"'Cairo',sans-serif" }}>❌ رفض</button>
                          </>)}
                          <button onClick={()=>printExcuse(ex)}
                            style={{ padding:"4px 10px", borderRadius:8, border:"1px solid #e2e8f0",
                                     background:"#f8fafc", color:"#7c3aed", fontWeight:800,
                                     fontSize:11.5, cursor:"pointer", fontFamily:"'Cairo',sans-serif" }}>🖨️ طباعة</button>
                          <button onClick={()=>setReplyOpen(p=>({...p,[ex.id]:!p[ex.id]}))}
                            style={{ padding:"4px 10px", borderRadius:8, border:"1px solid #bfdbfe",
                                     background: replyOpen[ex.id]?"#dbeafe":"#eff6ff", color:"#1d4ed8",
                                     fontWeight:800, fontSize:11.5, cursor:"pointer", fontFamily:"'Cairo',sans-serif" }}>
                            {ex.adminReply ? "✏️ تعديل الرد" : "💬 رد الإدارة"}
                          </button>
                          <button onClick={()=>deleteExcuse(ex.id)}
                            style={{ padding:"4px 8px", borderRadius:8, border:"1px solid #e2e8f0",
                                     background:"#f8fafc", color:"#94a3b8", fontSize:11.5, cursor:"pointer" }}>🗑️</button>
                        </div>
                      </div>
                      <div style={{ marginTop:10, padding:"10px 12px", background:"#f8fafc",
                        borderRadius:10, border:"1px solid #e2e8f0", fontSize:12 }}>
                        {/* معلومات اليوم والتاريخ */}
                        <div style={{ display:"flex", gap:12, flexWrap:"wrap", marginBottom:6,
                          background:"#eff6ff", padding:"6px 10px", borderRadius:8 }}>
                          {ex.absenceDay && <span>📅 <strong>اليوم:</strong> {ex.absenceDay}</span>}
                          {ex.absenceDateH && <span>🌙 {ex.absenceDateH} هـ</span>}
                          {ex.absenceDateM && <span>☀️ {ex.absenceDateM} م</span>}
                        </div>
                        <div style={{ display:"flex", gap:12, flexWrap:"wrap", marginBottom:6 }}>
                          <span><strong>السبب:</strong> {ex.reasonCat}</span>
                          {ex.parentName && <span>👤 <strong>{ex.parentRelation||"ولي الأمر"}:</strong> {ex.parentName}</span>}
                          {ex.parentPhone && <span>📱 {ex.parentPhone}</span>}
                          {ex.fileSizeKB > 0 && <span style={{ color:"#94a3b8" }}>({ex.fileSizeKB}KB)</span>}
                        </div>
                        {ex.excuseType === "text" && ex.reason && (
                          <div style={{ color:"#374151", lineHeight:1.8 }}>{ex.reason}</div>
                        )}
                        {ex.excuseType === "image" && ex.fileData && (
                          <img src={ex.fileData} alt="عذر"
                            style={{ maxWidth:"100%", maxHeight:180, borderRadius:8,
                                     border:"1px solid #e2e8f0", cursor:"pointer", marginTop:6 }}
                            onClick={()=>window.open(ex.fileData)} />
                        )}
                        {ex.excuseType === "pdf" && ex.fileData && (
                          <a href={ex.fileData} download={ex.fileName}
                            style={{ display:"inline-flex", alignItems:"center", gap:6, marginTop:6,
                                     padding:"6px 14px", borderRadius:8, background:"#fee2e2",
                                     color:"#991b1b", fontWeight:700, fontSize:12, textDecoration:"none" }}>
                            📄 تنزيل {ex.fileName}
                          </a>
                        )}
                        {/* رد الإدارة الموجود */}
                        {ex.adminReply && (
                          <div style={{ marginTop:10, background:"#f0fdf4", border:"1px solid #86efac",
                            borderRadius:8, padding:"10px 12px" }}>
                            <div style={{ fontSize:11, fontWeight:800, color:"#065f46", marginBottom:4 }}>
                              📌 رد الإدارة — {ex.adminReplyAt}
                            </div>
                            <div style={{ fontSize:13, color:"#065f46", lineHeight:1.8, fontWeight:700 }}>
                              {ex.adminReply}
                            </div>
                          </div>
                        )}
                        {/* نموذج الرد */}
                        {replyOpen[ex.id] && (
                          <div style={{ marginTop:10, background:"#eff6ff", border:"1.5px solid #93c5fd",
                            borderRadius:10, padding:"12px" }}>
                            <div style={{ fontSize:11.5, fontWeight:800, color:"#1d4ed8", marginBottom:8 }}>
                              💬 رد الإدارة على هذا العذر
                            </div>
                            <textarea
                              value={adminReplyDraft[ex.id]||ex.adminReply||""}
                              onChange={e=>setAdminReplyDraft(p=>({...p,[ex.id]:e.target.value}))}
                              placeholder="اكتب رد الإدارة هنا (سيظهر للطالب عند الطباعة)..."
                              rows={3}
                              style={{ width:"100%", padding:"9px 12px", borderRadius:8, border:"1.5px solid #bfdbfe",
                                fontFamily:"'Cairo',sans-serif", fontSize:13, resize:"vertical",
                                outline:"none", boxSizing:"border-box", marginBottom:8 }}
                            />
                            <div style={{ display:"flex", gap:8 }}>
                              <button onClick={()=>saveAdminReply(ex.id)}
                                style={{ padding:"7px 18px", borderRadius:8, border:"none",
                                  background:"#1d4ed8", color:"#fff", fontWeight:800,
                                  fontSize:12, cursor:"pointer", fontFamily:"'Cairo',sans-serif" }}>
                                💾 حفظ الرد
                              </button>
                              <button onClick={()=>setReplyOpen(p=>({...p,[ex.id]:false}))}
                                style={{ padding:"7px 14px", borderRadius:8, border:"1px solid #e2e8f0",
                                  background:"#fff", color:"#64748b", fontWeight:700,
                                  fontSize:12, cursor:"pointer", fontFamily:"'Cairo',sans-serif" }}>
                                إلغاء
                              </button>
                            </div>
                          </div>
                        )}
                      </div>
                    </div>
                  );
                })}
              </div>
              {totalPages > 1 && (
                <div style={{ display:"flex", justifyContent:"center", gap:8, alignItems:"center" }}>
                  <button onClick={()=>setPage(p=>Math.max(1,p-1))} disabled={page===1}
                    style={{ ...S.btn, background:page===1?"#f1f5f9":"#1d4ed8",
                             color:page===1?"#94a3b8":"#fff", padding:"8px 16px", fontSize:12 }}>
                    ← السابق
                  </button>
                  <span style={{ fontSize:12, fontWeight:700, color:"#64748b" }}>
                    {page} / {totalPages} · {filteredExcuses.length} عذر
                  </span>
                  <button onClick={()=>setPage(p=>Math.min(totalPages,p+1))} disabled={page===totalPages}
                    style={{ ...S.btn, background:page===totalPages?"#f1f5f9":"#1d4ed8",
                             color:page===totalPages?"#94a3b8":"#fff", padding:"8px 16px", fontSize:12 }}>
                    التالي →
                  </button>
                </div>
              )}
            </>
          )}
        </div>
      </div>
    );
  }

  // ═══ شاشة النجاح ═══
  if (view === "success") {
    return (
      <div style={{ ...S.page, display:"flex", alignItems:"center", justifyContent:"center", padding:"20px" }}>
        <div style={{ ...S.card, padding:"36px 28px", maxWidth:420, width:"100%", textAlign:"center" }}>
          <div style={{ fontSize:54, marginBottom:12 }}>✅</div>
          <div style={{ fontWeight:900, fontSize:19, color:"#065f46", marginBottom:8 }}>تم تقديم العذر بنجاح</div>
          <div style={{ fontSize:13, color:"#64748b", lineHeight:1.8, marginBottom:20 }}>
            سيتم مراجعته من قِبَل الإدارة في أقرب وقت
          </div>
          {/* ملخص العذر */}
          <div style={{ background:"#f0fdf4", borderRadius:12, padding:"14px",
            border:"1px solid #6ee7b7", textAlign:"right", marginBottom:20 }}>
            <div style={{ fontWeight:900, color:"#1e293b", marginBottom:8 }}>{student?.name}</div>
            <div style={{ fontSize:12, color:"#64748b", lineHeight:2 }}>
              <div>📅 {absenceDay} — {absenceDateH} هـ / {absenceDateM} م</div>
              <div>📌 {reasonCat}</div>
              <div>👤 {parentRelation}: {parentName}</div>
              {parentPhone && <div>📱 {parentPhone}</div>}
            </div>
          </div>
          <button onClick={()=>{ setView("login"); setNationalId(""); setStudent(null);
            setReason(""); setFileData(null); setFileName(""); }}
            style={{ ...S.btn, background:"linear-gradient(135deg,#1e3a5f,#1d4ed8)", color:"#fff", width:"100%" }}>
            ← تقديم عذر آخر
          </button>
          {onBack && <button onClick={onBack}
            style={{ ...S.btn, background:"#f1f5f9", color:"#64748b", width:"100%", marginTop:8, fontSize:12 }}>
            العودة للرئيسية
          </button>}
        </div>
      </div>
    );
  }

  // ═══ نموذج العذر ═══
  if (view === "form" && student) {
    return (
      <div style={S.page}>
        <div style={S.hdr}>
          <button onClick={()=>setView("login")}
            style={{ background:"rgba(255,255,255,0.15)", border:"none", borderRadius:10,
                     color:"#fff", fontWeight:800, fontSize:12, padding:"6px 12px",
                     cursor:"pointer", fontFamily:"'Cairo',sans-serif" }}>← رجوع</button>
          <span style={{ fontSize:22 }}>📋</span>
          <div style={{ flex:1 }}>
            <div style={{ fontWeight:900, fontSize:14 }}>نموذج تقديم العذر</div>
            <div style={{ opacity:.7, fontSize:11 }}>مدرسة الأمير عبدالمجيد المتوسطة الأولى</div>
          </div>
        </div>
        <div style={{ maxWidth:600, margin:"0 auto", padding:"14px 12px 60px" }}>

          {/* بيانات الطالب */}
          <div style={{ ...S.card, padding:"13px 16px", marginBottom:12,
            background:"linear-gradient(135deg,#eff6ff,#f0fdf4)", border:"1.5px solid #bfdbfe" }}>
            <div style={{ display:"flex", alignItems:"center", gap:12 }}>
              <div style={{ width:46, height:46, borderRadius:14, flexShrink:0,
                background:"linear-gradient(135deg,#1e3a5f,#1d4ed8)",
                display:"flex", alignItems:"center", justifyContent:"center",
                color:"#fff", fontWeight:900, fontSize:20 }}>{student.name.charAt(0)}</div>
              <div>
                <div style={{ fontWeight:900, fontSize:14.5, color:"#1e293b" }}>{student.name}</div>
                <div style={{ fontSize:11.5, color:"#64748b" }}>
                  🪪 {student.nationalId||student.id}
                  {student.className ? ` | 🏫 ${student.className}` : ""}
                </div>
              </div>
            </div>
          </div>

          {/* ── اليوم والتاريخ ── */}
          <div style={{ ...S.card, padding:"16px", marginBottom:12 }}>
            <div style={{ fontWeight:900, color:"#1e3a5f", fontSize:13.5, marginBottom:12,
              display:"flex", alignItems:"center", gap:8 }}>📅 يوم وتاريخ الغياب</div>

            {/* اليوم */}
            <div style={{ marginBottom:12 }}>
              <label style={{ fontSize:12, fontWeight:700, color:"#64748b", display:"block", marginBottom:5 }}>
                يوم الغياب *
              </label>
              <div style={{ display:"flex", flexWrap:"wrap", gap:6 }}>
                {WEEK_DAYS_AR.filter(d=>!["الجمعة","السبت"].includes(d)).map(d=>(
                  <button key={d} onClick={()=>setAbsenceDay(d)}
                    style={{ padding:"7px 14px", borderRadius:20, fontSize:12.5, fontWeight:700,
                             cursor:"pointer", border:"1.5px solid",
                             borderColor: absenceDay===d?"#1d4ed8":"#e2e8f0",
                             background:  absenceDay===d?"#1d4ed8":"#f8fafc",
                             color:       absenceDay===d?"#fff":"#374151",
                             fontFamily:"'Cairo',sans-serif" }}>{d}</button>
                ))}
              </div>
            </div>

            {/* التاريخ */}
            <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:10 }}>
              <div>
                <label style={{ fontSize:12, fontWeight:700, color:"#64748b", display:"block", marginBottom:5 }}>
                  🌙 التاريخ الهجري
                </label>
                <input value={absenceDateH} onChange={e=>setAbsenceDateH(e.target.value)}
                  placeholder="مثال: 14/10/1447"
                  style={{ ...S.input, fontSize:13 }} />
              </div>
              <div>
                <label style={{ fontSize:12, fontWeight:700, color:"#64748b", display:"block", marginBottom:5 }}>
                  ☀️ التاريخ الميلادي
                </label>
                <input value={absenceDateM} onChange={e=>setAbsenceDateM(e.target.value)}
                  placeholder="مثال: 13/04/2026"
                  style={{ ...S.input, fontSize:13 }} />
              </div>
            </div>
          </div>

          {/* ── سبب الغياب ── */}
          <div style={{ ...S.card, padding:"16px", marginBottom:12 }}>
            <div style={{ fontWeight:900, color:"#1e3a5f", fontSize:13.5, marginBottom:12,
              display:"flex", alignItems:"center", gap:8 }}>📌 سبب الغياب</div>
            <div style={{ display:"flex", flexWrap:"wrap", gap:6, marginBottom:14 }}>
              {REASON_CATS.map(r => (
                <button key={r} onClick={()=>setReasonCat(r)}
                  style={{ padding:"6px 13px", borderRadius:20, fontSize:12, fontWeight:700,
                           cursor:"pointer", border:"1.5px solid",
                           borderColor: reasonCat===r?"#1d4ed8":"#e2e8f0",
                           background:  reasonCat===r?"#1d4ed8":"#f8fafc",
                           color:       reasonCat===r?"#fff":"#374151",
                           fontFamily:"'Cairo',sans-serif" }}>{r}</button>
              ))}
            </div>
          </div>

          {/* ── إرفاق العذر ── */}
          <div style={{ ...S.card, padding:"16px", marginBottom:12 }}>
            <div style={{ fontWeight:900, color:"#1e3a5f", fontSize:13.5, marginBottom:12,
              display:"flex", alignItems:"center", gap:8 }}>📎 إرفاق العذر</div>
            <div style={{ display:"flex", gap:7, marginBottom:12 }}>
              {[["text","📝 نص"],["image","🖼️ صورة"],["pdf","📄 PDF"]].map(([v,l])=>(
                <button key={v} onClick={()=>{setExcuseType(v);setFileData(null);setFileName("");}}
                  style={{ flex:1, padding:"9px 6px", borderRadius:11, fontSize:12, fontWeight:700,
                           cursor:"pointer", border:"1.5px solid",
                           borderColor: excuseType===v?"#1d4ed8":"#e2e8f0",
                           background:  excuseType===v?"#eff6ff":"#f8fafc",
                           color:       excuseType===v?"#1d4ed8":"#64748b",
                           fontFamily:"'Cairo',sans-serif" }}>{l}</button>
              ))}
            </div>
            {excuseType === "text" && (
              <textarea value={reason} onChange={e=>setReason(e.target.value)}
                placeholder="اكتب تفاصيل سبب الغياب..." rows={4}
                style={{ ...S.input, resize:"vertical", minHeight:95 }} />
            )}
            {(excuseType === "image" || excuseType === "pdf") && (
              !fileData ? (
                <label style={{ display:"flex", flexDirection:"column", alignItems:"center",
                  gap:7, padding:"22px 14px", border:"2px dashed #93c5fd",
                  borderRadius:12, background:"#eff6ff", cursor:"pointer", textAlign:"center" }}>
                  <span style={{ fontSize:34 }}>{excuseType==="image"?"🖼️":"📄"}</span>
                  <span style={{ fontWeight:700, color:"#1d4ed8", fontSize:13 }}>
                    اضغط لاختيار {excuseType==="image"?"صورة":"ملف PDF"}
                  </span>
                  <span style={{ fontSize:11, color:"#94a3b8" }}>الحد الأقصى 5MB · الصور تُضغط تلقائياً</span>
                  <input type="file" accept={excuseType==="image"?"image/*":".pdf"}
                    onChange={handleFile} style={{ display:"none" }} />
                </label>
              ) : (
                <div style={{ border:"1.5px solid #6ee7b7", borderRadius:12, padding:12, background:"#f0fdf4" }}>
                  <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:8 }}>
                    <span style={{ fontSize:12.5, fontWeight:700, color:"#065f46" }}>
                      {excuseType==="image"?"🖼️":"📄"} {fileName} ({fileSize}KB)
                    </span>
                    <button onClick={()=>{setFileData(null);setFileName("");}}
                      style={{ background:"#fee2e2", border:"none", borderRadius:8, color:"#991b1b",
                               fontWeight:700, fontSize:11.5, padding:"3px 9px", cursor:"pointer" }}>✕</button>
                  </div>
                  {excuseType==="image" && (
                    <img src={fileData} alt="معاينة"
                      style={{ maxWidth:"100%", maxHeight:150, borderRadius:8, border:"1px solid #e2e8f0" }} />
                  )}
                </div>
              )
            )}
          </div>

          {/* ── بيانات المُرسِل ── */}
          <div style={{ ...S.card, padding:"16px", marginBottom:16 }}>
            <div style={{ fontWeight:900, color:"#1e3a5f", fontSize:13.5, marginBottom:12,
              display:"flex", alignItems:"center", gap:8 }}>👤 بيانات المُرسِل</div>

            {/* العلاقة بالطالب */}
            <div style={{ marginBottom:12 }}>
              <label style={{ fontSize:12, fontWeight:700, color:"#64748b", display:"block", marginBottom:5 }}>
                صفة المُرسِل وعلاقته بالطالب *
              </label>
              <div style={{ display:"flex", flexWrap:"wrap", gap:6, marginBottom:10 }}>
                {RELATIONS.map(r => (
                  <button key={r} onClick={()=>setParentRelation(r)}
                    style={{ padding:"6px 12px", borderRadius:20, fontSize:11.5, fontWeight:700,
                             cursor:"pointer", border:"1.5px solid",
                             borderColor: parentRelation===r?"#0e7c7b":"#e2e8f0",
                             background:  parentRelation===r?"#0e7c7b":"#f8fafc",
                             color:       parentRelation===r?"#fff":"#374151",
                             fontFamily:"'Cairo',sans-serif" }}>{r}</button>
                ))}
              </div>
            </div>

            <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:10 }}>
              <div>
                <label style={{ fontSize:11.5, fontWeight:700, color:"#64748b", display:"block", marginBottom:4 }}>
                  اسم {parentRelation} *
                </label>
                <input value={parentName} onChange={e=>setParentName(e.target.value)}
                  placeholder={`اسم ${parentRelation}`} style={S.input} />
              </div>
              <div>
                <label style={{ fontSize:11.5, fontWeight:700, color:"#64748b", display:"block", marginBottom:4 }}>
                  رقم الجوال
                </label>
                <input value={parentPhone} onChange={e=>setParentPhone(e.target.value)}
                  placeholder="05xxxxxxxx" style={{ ...S.input, direction:"ltr", textAlign:"right" }} />
              </div>
            </div>
          </div>

          <button onClick={handleSubmit} disabled={saving}
            style={{ ...S.btn, width:"100%", fontSize:15, padding:"13px",
                     background: saving ? "#e2e8f0" : "linear-gradient(135deg,#1e3a5f,#1d4ed8)",
                     color: saving ? "#94a3b8" : "#fff",
                     boxShadow: saving ? "none" : "0 4px 16px rgba(29,78,216,0.3)" }}>
            {saving ? "⏳ جارٍ الإرسال..." : "📤 تقديم العذر"}
          </button>
        </div>
      </div>
    );
  }

  // ═══ شاشة الدخول بالهوية ═══
  return (
    <div style={{ ...S.page, display:"flex", flexDirection:"column",
      alignItems:"center", justifyContent:"center", padding:"20px", minHeight:"100vh" }}>
      <div style={{ ...S.card, padding:"34px 26px", maxWidth:420, width:"100%", textAlign:"center" }}>
        {/* شعار وعنوان */}
        <div style={{ background:"linear-gradient(135deg,#1e3a5f,#1d4ed8)", borderRadius:"50%",
          width:72, height:72, display:"flex", alignItems:"center", justifyContent:"center",
          fontSize:32, margin:"0 auto 14px" }}>📋</div>
        <h1 style={{ fontSize:19, fontWeight:900, color:"#1e293b", marginBottom:4 }}>بوابة أعذار الطلاب</h1>
        <p style={{ fontSize:12.5, color:"#64748b", marginBottom:6, lineHeight:1.8 }}>
          مدرسة الأمير عبدالمجيد المتوسطة الأولى
        </p>
        <p style={{ fontSize:11.5, color:"#94a3b8", marginBottom:22 }}>
          أدخل رقم هوية الطالب لتقديم عذر الغياب
        </p>

        {students.length === 0 && (
          <div style={{ background:"#fef3c7", border:"1px solid #fde68a", borderRadius:10,
            padding:"9px 14px", marginBottom:14, fontSize:12, color:"#92400e", fontWeight:600 }}>
            ⚠️ لم تُضَف قائمة الطلاب بعد — تواصل مع إدارة المدرسة
          </div>
        )}

        <div style={{ marginBottom:16, textAlign:"right" }}>
          <label style={{ fontSize:12, fontWeight:700, color:"#64748b", display:"block", marginBottom:6 }}>
            🪪 رقم هوية الطالب
          </label>
          <input value={nationalId} onChange={e=>{setNationalId(e.target.value);setIdError("");}}
            onKeyDown={e=>e.key==="Enter"&&handleLogin()}
            placeholder="أدخل رقم الهوية"
            style={{ ...S.input, fontSize:18, textAlign:"center", letterSpacing:3,
                     fontWeight:700, color:"#1e3a5f", padding:"13px 14px" }} />
          {idError && <div style={{ color:"#dc2626", fontSize:12, fontWeight:700, marginTop:6,
            background:"#fee2e2", padding:"6px 10px", borderRadius:8 }}>{idError}</div>}
        </div>

        <button onClick={handleLogin}
          style={{ ...S.btn, width:"100%", background:"linear-gradient(135deg,#1e3a5f,#1d4ed8)",
                   color:"#fff", fontSize:15, padding:"13px",
                   boxShadow:"0 4px 16px rgba(29,78,216,0.28)", marginBottom:10 }}>
          دخول ← تقديم عذر
        </button>

        {onBack && <button onClick={onBack}
          style={{ ...S.btn, width:"100%", background:"#f1f5f9", color:"#64748b", fontSize:12 }}>
          ← العودة للرئيسية
        </button>}

        {/* شريط الرابط */}
        <div style={{ marginTop:20, padding:"10px 12px", background:"#f8fafc",
          borderRadius:10, border:"1px solid #e2e8f0" }}>
          <div style={{ fontSize:10.5, color:"#94a3b8", marginBottom:5 }}>
            رابط هذه الصفحة — يمكن مشاركته مع أولياء الأمور
          </div>
          <div style={{ display:"flex", gap:8, alignItems:"center" }}>
            <code style={{ fontSize:10, color:"#1d4ed8", flex:1, wordBreak:"break-all",
              textAlign:"right", background:"#eff6ff", padding:"4px 8px", borderRadius:6 }}>
              {EXCUSE_URL}
            </code>
            <button onClick={copyLink}
              style={{ ...S.btn, padding:"5px 10px", fontSize:11,
                       background: copied ? "#d1fae5" : "#1d4ed8",
                       color: copied ? "#065f46" : "#fff", flexShrink:0 }}>
              {copied ? "✅" : "📋"}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

function ParentPortal({ classList, setClassList, saveClass, messages, setMessages, saveMessages, surveys, setSurveys, saveSurveys, siteFont, onBack, onSuggestions, initialStudentId }) {
  const [nationalId, setNationalId] = useState(initialStudentId || "");
  const [result, setResult] = useState(null);
  const [error, setError] = useState("");
  const [searched, setSearched] = useState(false);
  const [tab, setTab] = useState("notes"); // notes | grades | messages | surveys
  const [replyTexts, setReplyTexts] = useState({});
  const [replying, setReplying] = useState({});
  const [editingPhone, setEditingPhone] = useState(false);
  const [phoneInput, setPhoneInput] = useState("");
  const [portalLightbox, setPortalLightbox] = useState(null); // {src,name}

  const saveParentPhone = (phone) => {
    if (!result || !setClassList) return;
    const updated = classList.map(cls =>
      cls.id === result.cls.id
        ? { ...cls, students: cls.students.map(s => s.id === result.student.id ? { ...s, parentPhone: phone } : s) }
        : cls
    );
    setClassList(updated);
    if (saveClass) saveClass({ ...result.cls, students: result.cls.students.map(s => s.id === result.student.id ? { ...s, parentPhone: phone } : s) });
    setResult(prev => ({ ...prev, student: { ...prev.student, parentPhone: phone } }));
    setEditingPhone(false);
  };

  const handleSearch = (idOverride) => {
    const id = (idOverride !== undefined ? idOverride : nationalId).trim();
    if (!id) { setError("أدخل رقم الهوية"); return; }
    setSearched(true);
    setError("");
    for (const cls of classList) {
      const student = cls.students?.find(s => s.nationalId && s.nationalId.trim() === id);
      if (student) {
        setResult({ student, cls });
        const hasUnread = messages.some(m => m.type === "teacher_note" && m.studentId === student.nationalId && !m.read);
        setTab(hasUnread ? "notes" : "grades");
        return;
      }
    }
    setResult(null);
    setError("لم يتم العثور على طالب بهذا الرقم. تأكد من صحة رقم الهوية.");
  };

  // بحث تلقائي إذا وصل ولي الأمر عبر رابط مخصص
  useEffect(() => {
    if (initialStudentId && classList.length > 0) {
      handleSearch(initialStudentId);
    }
  }, [classList.length]);

  const gradeCount = result ? Object.values(result.student.grades || {}).reduce((acc, g) => { if (g) acc[g] = (acc[g] || 0) + 1; return acc; }, {}) : {};
  const totalGraded = Object.values(gradeCount).reduce((a, b) => a + b, 0);
  const excellentCount = (gradeCount.excel || 0) + (gradeCount.vgood || 0);
  const weakCount = (gradeCount.weak || 0);

  return (
    <div dir="rtl" className="min-h-screen flex flex-col" style={{ fontFamily: siteFont, background: "linear-gradient(135deg, #1B3A6B 0%, #2E6DA4 60%, #1a8fe3 100%)" }}>
      <style>{`@import url('https://fonts.googleapis.com/css2?family=Tajawal:wght@400;700;800&display=swap');`}</style>
      {/* رأس الصفحة */}
      <div className="text-center text-white pt-10 pb-6 px-4">
        <div className="text-5xl mb-3">🏫</div>
        <h1 className="text-2xl font-black mb-1">مدرسة الأمير عبدالمجيد المتوسطة الأولى</h1>
        <p className="opacity-80 text-sm">بوابة أولياء الأمور — متابعة مستوى الطالب</p>
        <button onClick={onSuggestions}
          className="mt-3 inline-flex items-center gap-2 px-5 py-2.5 rounded-2xl font-black text-sm shadow-lg"
          style={{background:"rgba(255,255,255,0.15)",border:"1px solid rgba(255,255,255,0.3)"}}>
          💬 آراء ومقترحات
        </button>
      </div>

      <div className="w-full px-2 pb-10 flex-1">
        {/* بطاقة البحث */}
        <div className="bg-white rounded-3xl shadow-2xl p-6 mb-4">
          <h2 className="font-black text-gray-800 text-center mb-4">🔍 أدخل رقم هوية الطالب</h2>
          <div className="flex gap-2">
            <input type="text" value={nationalId} onChange={e => { setNationalId(e.target.value); setError(""); setSearched(false); setResult(null); }}
              onKeyDown={e => e.key === "Enter" && handleSearch()}
              placeholder="رقم الهوية الوطنية للطالب"
              className="flex-1 px-4 py-3 rounded-xl border-2 border-gray-200 focus:border-blue-400 focus:outline-none text-sm text-center tracking-widest font-bold" />
            <button onClick={handleSearch}
              className="bg-blue-600 text-white px-5 py-3 rounded-xl font-bold hover:bg-blue-700 text-sm">بحث</button>
          </div>
          {error && (
            <div className="mt-3 bg-red-50 text-red-600 text-xs font-bold p-3 rounded-xl text-center">{error}</div>
          )}
        </div>

        {/* نتيجة البحث */}
        {result && (
          <div className="space-y-4">
            {/* بيانات الطالب */}
            <div className={cx.cardXl}>
              <div className="p-5 text-white text-center" style={{ background: "linear-gradient(135deg, #1B3A6B, #2E6DA4)" }}>
                <div className="w-16 h-16 rounded-full bg-white bg-opacity-20 flex items-center justify-center text-3xl mx-auto mb-3">👨‍🎓</div>
                <h3 className="text-xl font-black">{result.student.name}</h3>
                <p className="opacity-80 text-sm mt-1">{result.cls.level} / شعبة {result.cls.section}</p>
              </div>
              <div className="grid grid-cols-2 gap-px bg-gray-100">
                <div className="bg-white p-3 text-center">
                  <div className="text-xs text-gray-400 font-bold">الفصل الدراسي</div>
                  <div className="font-black text-gray-800 text-sm mt-1">الفصل {result.cls.semester || "—"}</div>
                </div>
                <div className="bg-white p-3 text-center">
                  <div className="text-xs text-gray-400 font-bold">المعلم</div>
                  <div className="font-black text-gray-800 text-sm mt-1">{result.cls.teacher || "—"}</div>
                </div>
              </div>

              {/* ===== جوال ولي الأمر ===== */}
              <div className="px-4 py-3 border-t border-gray-100">
                <div className="text-xs font-bold text-gray-500 mb-2">📱 جوال ولي الأمر (لاستقبال إشعارات واتساب)</div>
                {result.student.parentPhone && !editingPhone ? (
                  <div className="flex items-center gap-2">
                    <span className="flex-1 bg-green-50 border border-green-200 text-green-800 text-sm font-bold px-3 py-2 rounded-xl text-center tracking-wide">
                      {result.student.parentPhone}
                    </span>
                    <button onClick={() => { setPhoneInput(result.student.parentPhone); setEditingPhone(true); }}
                      className="text-xs bg-gray-100 hover:bg-gray-200 text-gray-600 px-3 py-2 rounded-xl font-bold transition-all">
                      تعديل
                    </button>
                  </div>
                ) : editingPhone ? (
                  <div className="flex gap-2">
                    <input type="tel" value={phoneInput} onChange={e => setPhoneInput(e.target.value)}
                      placeholder="05XXXXXXXX"
                      className="flex-1 px-3 py-2 rounded-xl border-2 border-green-300 focus:border-green-500 focus:outline-none text-sm text-center font-bold tracking-wide"
                      style={{fontFamily:"inherit"}}
                      onKeyDown={e => e.key === "Enter" && phoneInput.trim() && saveParentPhone(phoneInput.trim())}
                    />
                    <button onClick={() => phoneInput.trim() && saveParentPhone(phoneInput.trim())}
                      className="bg-green-600 hover:bg-green-700 text-white text-xs font-bold px-4 py-2 rounded-xl transition-all">
                      حفظ
                    </button>
                    <button onClick={() => setEditingPhone(false)}
                      className="bg-gray-100 text-gray-500 text-xs font-bold px-3 py-2 rounded-xl">
                      إلغاء
                    </button>
                  </div>
                ) : (
                  <div className="space-y-2">
                    <div className="flex gap-2">
                      <input type="tel" value={phoneInput} onChange={e => setPhoneInput(e.target.value)}
                        placeholder="05XXXXXXXX — أدخل جوالك لاستقبال الإشعارات"
                        className="flex-1 px-3 py-2 rounded-xl border-2 border-dashed border-green-300 focus:border-green-500 focus:outline-none text-sm text-center font-bold"
                        style={{fontFamily:"inherit"}}
                        onKeyDown={e => e.key === "Enter" && phoneInput.trim() && saveParentPhone(phoneInput.trim())}
                      />
                      <button onClick={() => phoneInput.trim() && saveParentPhone(phoneInput.trim())}
                        className="bg-green-600 hover:bg-green-700 text-white text-xs font-bold px-4 py-2 rounded-xl transition-all">
                        💾 حفظ
                      </button>
                    </div>
                    <p className="text-xs text-gray-400 text-center">
                      📲 سيتمكن المعلم من إرسال إشعار واتساب مباشرة عند وجود ملاحظة
                    </p>
                  </div>
                )}
              </div>
            </div>

            {/* تبويبات ولي الأمر */}
            {(() => {
              const studentNotes = messages.filter(m => m.type === "teacher_note" && m.studentId === result.student.nationalId);
              const unreadNotes = studentNotes.filter(m => !m.read).length;
              const tabs = [
                { id: "notes",    label: "ملاحظات المعلم", icon: "🔔", badge: unreadNotes },
                { id: "grades",   label: "التقييمات",       icon: "📊" },
                { id: "messages", label: "رسالة",           icon: "✉️" },
              ];
              return (
                <div className="flex gap-1 bg-white rounded-2xl p-1.5 shadow-sm">
                  {tabs.map(t => (
                    <button key={t.id} onClick={() => setTab(t.id)}
                      className={`flex-1 py-2 rounded-xl text-xs font-black transition-all relative ${tab === t.id ? "bg-blue-600 text-white shadow" : "text-gray-500 hover:bg-gray-50"}`}>
                      {t.icon} <span className="hidden sm:inline">{t.label}</span>
                      {t.badge > 0 && (
                        <span className="absolute -top-1.5 -right-1.5 w-4 h-4 bg-red-500 text-white text-xs font-black rounded-full flex items-center justify-center leading-none animate-pulse">{t.badge}</span>
                      )}
                    </button>
                  ))}
                </div>
              );
            })()}

            {/* ===== تبويب ملاحظات المعلم ===== */}
            {tab === "notes" && (() => {
              const studentNotes = messages.filter(m => m.type === "teacher_note" && m.studentId === result.student.nationalId);

              const markRead = (id) => {
                const updated = messages.map(m => m.id === id ? { ...m, read: true } : m);
                setMessages(updated); saveMessages(updated);
              };
              const submitReply = (id) => {
                const txt = (replyTexts[id] || "").trim();
                if (!txt) return;
                const updated = messages.map(m => m.id === id ? { ...m, reply: txt, repliedAt: new Date().toLocaleDateString("ar-SA"), read: true } : m);
                setMessages(updated); saveMessages(updated);
                setReplyTexts(p => ({ ...p, [id]: "" }));
                setReplying(p => ({ ...p, [id]: false }));
              };

              if (studentNotes.length === 0) return (
                <div className="bg-white rounded-2xl shadow-xl p-8 text-center">
                  <div className="text-4xl mb-3">🔔</div>
                  <div className="font-black text-gray-700 mb-1">لا توجد ملاحظات من المعلم</div>
                  <div className="text-sm text-gray-400">ستظهر هنا أي ملاحظات يرسلها المعلم لك</div>
                </div>
              );

              return (
                <div className="space-y-3">
                  <div className={cx.cardXl}>
                    <div className="px-4 py-3 font-black text-white text-sm flex items-center gap-2" style={{ background: "linear-gradient(135deg,#b45309,#f59e0b)" }}>
                      <span className="text-lg">📨</span>
                      <span>ملاحظات المعلم ({studentNotes.length})</span>
                      {studentNotes.filter(m => !m.read).length > 0 && (
                        <span className="mr-auto bg-white text-amber-700 text-xs font-black px-2 py-0.5 rounded-full animate-pulse">
                          {studentNotes.filter(m => !m.read).length} جديد
                        </span>
                      )}
                    </div>
                    <div className="divide-y divide-gray-100">
                      {studentNotes.map(note => {
                        if (!note.read) markRead(note.id);
                        return (
                          <div key={note.id} className={`p-4 ${!note.read ? "bg-amber-50" : ""}`}>
                            {/* رأس الملاحظة */}
                            <div className="flex items-start justify-between gap-2 mb-3">
                              <div className="flex items-center gap-2">
                                <div className="w-9 h-9 rounded-full bg-amber-100 flex items-center justify-center text-xl shrink-0">👨‍🏫</div>
                                <div>
                                  <div className="font-black text-gray-800 text-sm">المعلم</div>
                                  <div className="text-xs text-gray-400">{note.date} · {note.time}</div>
                                </div>
                              </div>
                              {!note.read && <span className="shrink-0 text-xs bg-amber-500 text-white px-2 py-0.5 rounded-full font-bold">جديد</span>}
                            </div>
                            {/* نص الملاحظة */}
                            <div className="bg-amber-50 border border-amber-200 rounded-xl px-4 py-3 text-sm text-gray-800 leading-relaxed mb-3">
                              {note.text}
                            </div>
                            {/* مرفقات الملاحظة */}
                            {note.attachments && note.attachments.length > 0 && (
                              <div className="mb-3 space-y-2">
                                {note.attachments.map((att, i) => (
                                  att.type && att.type.startsWith("image") ? (
                                    <div key={i} className="relative cursor-zoom-in group" onClick={()=>setPortalLightbox({src:att.data,name:att.name})}>
                                      <img src={att.data} alt={att.name} className="max-w-full rounded-xl border border-amber-200 shadow-sm hover:shadow-lg transition-all" style={{maxHeight:220,objectFit:"contain"}} />
                                      <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-all">
                                        <span className="bg-black bg-opacity-50 text-white text-xs font-black px-3 py-1.5 rounded-full">🔍 اضغط للتكبير</span>
                                      </div>
                                    </div>
                                  ) : (
                                    <a key={i} href={att.data} download={att.name} target="_blank" rel="noreferrer"
                                      className="flex items-center gap-2 bg-red-50 border border-red-200 rounded-xl px-3 py-2 text-sm font-bold text-red-700 hover:bg-red-100 transition-all">
                                      <span>📄 {att.name}</span>
                                      <span className="mr-auto text-xs bg-red-200 px-2 py-0.5 rounded-full">تحميل PDF</span>
                                    </a>
                                  )
                                ))}
                              </div>
                            )}
                            {/* الرد */}
                            {note.reply ? (
                              <div className="flex gap-2 items-start">
                                <div className="w-7 h-7 rounded-full bg-blue-100 flex items-center justify-center text-base shrink-0">👨‍👦</div>
                                <div className="flex-1 bg-blue-50 border border-blue-200 rounded-xl px-3 py-2">
                                  <div className="text-xs font-black text-blue-700 mb-1">ردّك — {note.repliedAt}</div>
                                  <div className="text-sm text-gray-800">{note.reply}</div>
                                </div>
                              </div>
                            ) : (
                              <div>
                                {replying[note.id] ? (
                                  <div className="space-y-2">
                                    <textarea
                                      value={replyTexts[note.id] || ""}
                                      onChange={e => setReplyTexts(p => ({ ...p, [note.id]: e.target.value }))}
                                      rows={2}
                                      placeholder="اكتب ردّك هنا..."
                                      className="w-full px-3 py-2 rounded-xl border-2 border-blue-200 focus:border-blue-400 focus:outline-none text-sm resize-none"
                                      style={{ fontFamily: "inherit" }}
                                    />
                                    <div className="flex gap-2">
                                      <button onClick={() => submitReply(note.id)}
                                        className="flex-1 py-2 rounded-xl bg-blue-600 text-white text-xs font-black hover:bg-blue-700 transition-all">
                                        📤 إرسال الرد
                                      </button>
                                      <button onClick={() => setReplying(p => ({ ...p, [note.id]: false }))}
                                        className="px-4 py-2 rounded-xl bg-gray-100 text-gray-600 text-xs font-bold hover:bg-gray-200">
                                        إلغاء
                                      </button>
                                    </div>
                                  </div>
                                ) : (
                                  <button onClick={() => setReplying(p => ({ ...p, [note.id]: true }))}
                                    className="w-full py-2 rounded-xl border-2 border-dashed border-blue-300 text-blue-600 text-xs font-black hover:bg-blue-50 transition-all">
                                    💬 ردّ على الملاحظة
                                  </button>
                                )}
                              </div>
                            )}
                          </div>
                        );
                      })}
                    </div>
                  </div>
                </div>
              );
            })()}

            {/* التقييمات الأسبوعية */}
            {tab === "grades" && (() => {
              const evals = result.student.evals || [];
              const LMAP = GRADE_MAP;
              const CATS = [{ key:"behavior", label:"السلوك", icon:"🌿" }, { key:"homework", label:"الواجبات", icon:"📝" }, { key:"participation", label:"المشاركة", icon:"🙋" }, { key:"discipline", label:"الانضباط", icon:"⚖️" }];

              if (evals.length === 0) return (
                <div className="bg-white rounded-2xl shadow-xl p-5 text-center">
                  <div className="text-3xl mb-2">📋</div>
                  <div className="text-sm text-gray-400 font-bold">لا توجد تقييمات أسبوعية بعد</div>
                </div>
              );

              const lastEval = evals[evals.length - 1];
              const lastLv = LMAP[lastEval?.level];

              const studentPhotos = result.student.photos || [];
              const studentPdfs  = result.student.pdfs  || [];

              return (
                <>
                  {/* صور الطالب — قابلة للتكبير */}
                  {studentPhotos.length > 0 && (
                    <div className={cx.cardXl}>
                      <div className="px-4 py-3 font-black text-white text-sm" style={{ background: "linear-gradient(135deg,#7c3aed,#4f46e5)" }}>🖼️ صور الطالب</div>
                      <div className="p-4 flex gap-3 flex-wrap">
                        {studentPhotos.map((ph,i) => (
                          <div key={i} className="relative cursor-zoom-in group" onClick={()=>setPortalLightbox({src:ph.data,name:ph.name})}>
                            <img src={ph.data} alt={ph.name}
                              className="w-28 h-28 object-cover rounded-2xl border-2 border-purple-200 shadow-md hover:shadow-xl hover:border-purple-400 transition-all"
                            />
                            <div className="absolute inset-0 rounded-2xl flex items-center justify-center bg-black bg-opacity-0 group-hover:bg-opacity-30 transition-all">
                              <span className="text-white text-2xl opacity-0 group-hover:opacity-100 transition-all drop-shadow-lg">🔍</span>
                            </div>
                          </div>
                        ))}
                      </div>
                      {studentPdfs.length > 0 && (
                        <div className="px-4 pb-4 space-y-2">
                          {studentPdfs.map((pdf,i)=>(
                            <a key={i} href={pdf.data} download={pdf.name} target="_blank" rel="noreferrer"
                              className="flex items-center gap-2 bg-red-50 border border-red-200 rounded-xl px-3 py-2.5 text-sm font-bold text-red-700 hover:bg-red-100 transition-all">
                              📄 {pdf.name}
                              <span className="mr-auto text-xs bg-red-200 px-2 py-0.5 rounded-full">⬇️ تحميل</span>
                            </a>
                          ))}
                        </div>
                      )}
                    </div>
                  )}

                  {lastLv && (
                    <div className={cx.cardXl}>
                      <div className="px-4 py-3 font-black text-white text-sm" style={{ background: "#1B3A6B" }}>⭐ آخر تقييم أسبوعي</div>
                      <div className="p-4">
                        <div className="flex items-center justify-between mb-3">
                          <div className="text-xs text-gray-400">{lastEval.day} {lastEval.dateH}</div>
                          <span className="px-4 py-2 rounded-full font-black text-sm" style={{ background: lastLv.bg, color: lastLv.c }}>{lastLv.label}</span>
                        </div>
                        {/* ملخص المواد — آخر مستوى لكل مادة */}
                        {evals.some(e=>e.subject) && (
                          <div className="mb-3">
                            <div className="text-xs font-black text-gray-500 mb-2">📊 آخر مستوى لكل مادة</div>
                            <div className="grid grid-cols-3 gap-1.5">
                              {SUBJECTS.map(subj => {
                                const last = [...evals].reverse().find(e=>e.subject===subj.key);
                                if (!last) return null;
                                const lv = LMAP[last.level];
                                return (
                                  <div key={subj.key} className="rounded-xl overflow-hidden border" style={{borderColor:subj.color+"44"}}>
                                    <div className="flex items-center gap-1 px-2 py-1" style={{background:subj.bg}}>
                                      <span className="text-xs">{subj.icon}</span>
                                      <span className="text-xs font-black truncate" style={{color:subj.color}}>{subj.label}</span>
                                    </div>
                                    <div className="text-center font-black text-xs py-1.5" style={{background:lv?.bg||"#f5f5f5",color:lv?.c||"#333"}}>
                                      {lv?.label||"—"}
                                    </div>
                                  </div>
                                );
                              })}
                            </div>
                          </div>
                        )}
                        {CATS.map(cat => {
                          const d = lastEval.categories?.[cat.key];
                          if (!d?.text && !d?.face) return null;
                          return (
                            <div key={cat.key} className="flex items-start gap-2 rounded-xl px-3 py-2 mb-2"
                              style={{ background: d.color || "#f9fafb", border: "1px solid #e5e7eb" }}>
                              <span className="text-lg flex-shrink-0">{cat.icon}</span>
                              <div className="flex-1">
                                <div className="text-xs font-black text-gray-600">{cat.label}</div>
                                <div className="text-sm text-gray-700 mt-0.5">{d.text}</div>
                              </div>
                              {d.face && <span className="text-xl">{d.face}</span>}
                            </div>
                          );
                        })}
                        {/* مرفقات التقييم */}
                        {lastEval.attachments && lastEval.attachments.length > 0 && (
                          <div className="mt-2 space-y-2">
                            <div className="text-xs font-black text-gray-500">📎 مرفقات التقييم</div>
                            {lastEval.attachments.map((att, i) => (
                              att.type && att.type.startsWith("image") ? (
                                <div key={i} className="relative cursor-zoom-in group" onClick={()=>setPortalLightbox({src:att.data,name:att.name})}>
                                  <img src={att.data} alt={att.name} className="max-w-full rounded-xl border border-gray-200 shadow-sm hover:shadow-lg transition-all" style={{maxHeight:200,objectFit:"contain"}} />
                                  <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-all">
                                    <span className="bg-black bg-opacity-50 text-white text-xs font-black px-3 py-1.5 rounded-full">🔍 اضغط للتكبير</span>
                                  </div>
                                </div>
                              ) : (
                                <a key={i} href={att.data} download={att.name} target="_blank" rel="noreferrer"
                                  className="flex items-center gap-2 bg-red-50 border border-red-200 rounded-xl px-3 py-2 text-xs font-bold text-red-700">
                                  📄 {att.name}
                                </a>
                              )
                            ))}
                          </div>
                        )}
                      </div>
                    </div>
                  )}
                  {evals.length > 1 && (
                    <div className={cx.cardXl}>
                      <div className="px-4 py-3 font-black text-white text-sm" style={{ background: "#1B3A6B" }}>📅 سجل التقييمات ({evals.length})</div>
                      <div className="divide-y divide-gray-100">
                        {[...evals].reverse().map(ev => {
                          const lv = LMAP[ev.level];
                          return (
                            <div key={ev.id} className="flex items-center justify-between px-4 py-3">
                              <div>
                                <div className="text-xs font-black text-gray-600">{ev.day} {ev.dateH}</div>
                                <div className="text-xs text-gray-400 mt-0.5">
                                  {CATS.filter(c => ev.categories?.[c.key]?.text).map(c => c.icon + " " + c.label).join(" · ")}
                                </div>
                              </div>
                              {lv ? <span className="px-3 py-1 rounded-full text-xs font-black" style={{ background: lv.bg, color: lv.c }}>{lv.label}</span>
                                : <span className="text-xs text-gray-300">—</span>}
                            </div>
                          );
                        })}
                      </div>
                    </div>
                  )}
                </>
              );
            })()}

            {/* تبويب الرسائل */}
            {tab === "messages" && (
              <div className={cx.cardXl}>
                <MessagesPage
                  messages={messages}
                  setMessages={setMessages}
                  saveMessages={saveMessages}
                  isParent={true}
                  parentName={result.student.name}
                />
              </div>
            )}

          </div>
        )}

        {/* زر العودة */}
        <div className="mt-6 text-center">
          <button onClick={onBack} className="text-white opacity-70 hover:opacity-100 text-sm font-bold underline">← العودة إلى صفحة الدخول</button>
        </div>
      </div>
      {/* Lightbox مكبّر الصور — ولي الأمر */}
      {portalLightbox && <ImageLightbox src={portalLightbox.src} name={portalLightbox.name} onClose={()=>setPortalLightbox(null)} />}
    </div>
  );
}

// ===== بوابة المعلم =====

// ===== صفحة الاستراتيجيات التدريسية =====
function StrategiesPage() {
  const [strategies, setStrategies] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showAdd, setShowAdd] = useState(false);
  const [form, setForm] = useState({ title:"", category:"", description:"", pdfBase64:"", pdfName:"", bookBase64:"", bookName:"" });
  const [saving, setSaving] = useState(false);
  const [search, setSearch] = useState("");
  const [activeCategory, setActiveCategory] = useState("الكل");
  const fileRef = useRef(null);
  const bookRef = useRef(null);

  const CATEGORIES = ["الكل","التعلم النشط","التعلم التعاوني","التفكير الناقد","الذكاء الاصطناعي","التقنية","التقييم","التحفيز","أخرى"];

  useEffect(() => {
    DB.get("school-strategies", []).then(d => { setStrategies(Array.isArray(d) ? d : []); setLoading(false); });
  }, []);

  const saveToDB = async (list) => { await DB.set("school-strategies", list); };

  const toB64 = (file) => new Promise((res, rej) => {
    readFileAsync(file, "dataurl").then(res).catch(rej);
  });

  const handleFileUpload = async (e, type) => {
    const file = e.target.files?.[0]; if (!file) return;
    if (!file.type.includes("pdf")) { alert("يُقبل ملفات PDF فقط"); return; }
    if (file.size > 5 * 1024 * 1024) { alert("الحجم الأقصى 5 ميغابايت"); return; }
    const b64 = await toB64(file);
    if (type === "pdf") setForm(f => ({ ...f, pdfBase64: b64, pdfName: file.name }));
    else setForm(f => ({ ...f, bookBase64: b64, bookName: file.name }));
    e.target.value = "";
  };

  const handleSave = async () => {
    if (!form.title.trim()) { alert("أدخل عنوان الاستراتيجية"); return; }
    setSaving(true);
    const newItem = { id: Date.now(), ...form, createdAt: new Date().toLocaleDateString("ar-SA") };
    const updated = [newItem, ...strategies];
    setStrategies(updated);
    await saveToDB(updated);
    setForm({ title:"", category:"", description:"", pdfBase64:"", pdfName:"", bookBase64:"", bookName:"" });
    setShowAdd(false); setSaving(false);
  };

  const handleDelete = async (id) => {
    if (!confirm("حذف هذه الاستراتيجية؟")) return;
    const updated = strategies.filter(s => s.id !== id);
    setStrategies(updated); await saveToDB(updated);
  };

  const filtered = strategies.filter(s =>
    (activeCategory === "الكل" || s.category === activeCategory) &&
    (s.title.includes(search) || s.description.includes(search))
  );

  const CAT_COLORS = {
    "التعلم النشط":"bg-teal-100 text-teal-800","التعلم التعاوني":"bg-blue-100 text-blue-800",
    "التفكير الناقد":"bg-purple-100 text-purple-800","الذكاء الاصطناعي":"bg-pink-100 text-pink-800",
    "التقنية":"bg-indigo-100 text-indigo-800","التقييم":"bg-amber-100 text-amber-800",
    "التحفيز":"bg-green-100 text-green-800","أخرى":"bg-gray-100 text-gray-700"
  };

  if (loading) return <div className="flex items-center justify-center h-64"><div className="text-4xl animate-spin">📚</div></div>;

  return (
    <div className="space-y-5">
      <div className="page-header-bar" style={{background:"linear-gradient(135deg,#7c3aed,#4f46e5)"}}>
        <div className={cx.row}>
          <div>
            <h2 className="text-2xl font-black">📚 استراتيجيات التدريس</h2>
            <p className="opacity-80 text-sm mt-1">مكتبة الاستراتيجيات والنماذج والكتب المرجعية</p>
          </div>
          <button onClick={() => setShowAdd(true)} className="px-5 py-2.5 bg-white text-purple-700 font-black rounded-2xl hover:shadow-lg transition-all">
            + إضافة استراتيجية
          </button>
        </div>
      </div>

      {/* بحث وفلتر */}
      <div className="bg-white rounded-2xl p-4 shadow-sm border border-purple-100 space-y-3">
        <input value={search} onChange={e => setSearch(e.target.value)} placeholder="🔍 ابحث في الاستراتيجيات…"
          className="w-full px-4 py-2.5 rounded-xl border-2 border-gray-200 focus:border-purple-400 focus:outline-none text-sm" />
        <div className="flex flex-wrap gap-2">
          {CATEGORIES.map(c => (
            <button key={c} onClick={() => setActiveCategory(c)}
              className={`px-3 py-1.5 rounded-full text-xs font-bold transition-all ${activeCategory === c ? "bg-purple-600 text-white" : "bg-gray-100 text-gray-600 hover:bg-purple-50"}`}>
              {c}
            </button>
          ))}
        </div>
      </div>

      {/* نموذج الإضافة */}
      {showAdd && (
        <div className="bg-white rounded-2xl p-5 shadow-sm border-2 border-purple-200 space-y-4">
          <h3 className="font-black text-purple-800 text-lg">إضافة استراتيجية جديدة</h3>
          <div className="grid gap-3 sm:grid-cols-2">
            <div>
              <label className={cx.label}>عنوان الاستراتيجية *</label>
              <input value={form.title} onChange={e => setForm(f => ({...f,title:e.target.value}))}
                placeholder="مثال: التعلم بالمشروع"
                className="w-full px-3 py-2 rounded-xl border-2 border-gray-200 focus:border-purple-400 focus:outline-none text-sm" />
            </div>
            <div>
              <label className={cx.label}>التصنيف</label>
              <select value={form.category} onChange={e => setForm(f => ({...f,category:e.target.value}))}
                className="w-full px-3 py-2 rounded-xl border-2 border-gray-200 focus:border-purple-400 focus:outline-none text-sm bg-white">
                <option value="">اختر التصنيف</option>
                {CATEGORIES.slice(1).map(c => <option key={c} value={c}>{c}</option>)}
              </select>
            </div>
          </div>
          <div>
            <label className={cx.label}>الوصف والخطوات</label>
            <textarea value={form.description} onChange={e => setForm(f => ({...f,description:e.target.value}))}
              placeholder="اشرح خطوات الاستراتيجية وطريقة تطبيقها…"
              rows={4} className="w-full px-3 py-2 rounded-xl border-2 border-gray-200 focus:border-purple-400 focus:outline-none text-sm resize-none" />
          </div>
          <div className="grid gap-3 sm:grid-cols-2">
            <div className="border-2 border-dashed border-purple-200 rounded-xl p-4 text-center hover:border-purple-400 transition-all">
              <div className="text-3xl mb-2">📄</div>
              <p className="text-xs text-gray-500 font-bold mb-2">نموذج / ورقة عمل PDF</p>
              {form.pdfName ? (
                <div className="flex items-center gap-2 justify-center">
                  <span className="text-xs text-green-600 font-bold">✅ {form.pdfName}</span>
                  <button onClick={() => setForm(f => ({...f,pdfBase64:"",pdfName:""}))} className="text-red-400 text-xs">✕</button>
                </div>
              ) : (
                <button onClick={() => fileRef.current?.click()} className="px-3 py-1.5 bg-purple-600 text-white text-xs font-bold rounded-lg hover:bg-purple-700">
                  رفع PDF
                </button>
              )}
              <input ref={fileRef} type="file" accept=".pdf" onChange={e => handleFileUpload(e,"pdf")} className="hidden" />
            </div>
            <div className="border-2 border-dashed border-blue-200 rounded-xl p-4 text-center hover:border-blue-400 transition-all">
              <div className="text-3xl mb-2">📘</div>
              <p className="text-xs text-gray-500 font-bold mb-2">كتاب / مرجع PDF</p>
              {form.bookName ? (
                <div className="flex items-center gap-2 justify-center">
                  <span className="text-xs text-green-600 font-bold">✅ {form.bookName}</span>
                  <button onClick={() => setForm(f => ({...f,bookBase64:"",bookName:""}))} className="text-red-400 text-xs">✕</button>
                </div>
              ) : (
                <button onClick={() => bookRef.current?.click()} className="px-3 py-1.5 bg-blue-600 text-white text-xs font-bold rounded-lg hover:bg-blue-700">
                  رفع كتاب PDF
                </button>
              )}
              <input ref={bookRef} type="file" accept=".pdf" onChange={e => handleFileUpload(e,"book")} className="hidden" />
            </div>
          </div>
          <div className="flex gap-3">
            <button onClick={handleSave} disabled={saving} className="px-6 py-2.5 bg-purple-600 text-white font-black rounded-xl hover:bg-purple-700 disabled:opacity-50">
              {saving ? "جاري الحفظ…" : "💾 حفظ الاستراتيجية"}
            </button>
            <button onClick={() => setShowAdd(false)} className="px-6 py-2.5 bg-gray-100 text-gray-700 font-bold rounded-xl hover:bg-gray-200">
              إلغاء
            </button>
          </div>
        </div>
      )}

      {/* قائمة الاستراتيجيات */}
      {filtered.length === 0 ? (
        <div className="bg-white rounded-2xl p-12 text-center shadow-sm">
          <div className="text-5xl mb-3">📚</div>
          <p className="font-black text-gray-600">لا توجد استراتيجيات بعد</p>
          <p className="text-sm text-gray-400 mt-1">ابدأ بإضافة أول استراتيجية تدريسية</p>
        </div>
      ) : (
        <div className="grid gap-4 sm:grid-cols-2">
          {filtered.map(s => (
            <div key={s.id} className="bg-white rounded-2xl p-5 shadow-sm border border-gray-100 hover:shadow-md transition-all">
              <div className="flex items-start justify-between gap-2 mb-3">
                <div>
                  <h4 className="font-black text-gray-800">{s.title}</h4>
                  <p className="text-xs text-gray-400 mt-0.5">{s.createdAt}</p>
                </div>
                <div className="flex items-center gap-2 flex-shrink-0">
                  {s.category && <span className={`px-2 py-0.5 rounded-full text-xs font-bold ${CAT_COLORS[s.category] || "bg-gray-100 text-gray-700"}`}>{s.category}</span>}
                  <button onClick={() => handleDelete(s.id)} className="text-red-400 hover:text-red-600 text-sm">🗑</button>
                </div>
              </div>
              {s.description && <p className="text-sm text-gray-600 leading-relaxed mb-3 line-clamp-3">{s.description}</p>}
              <div className="flex flex-wrap gap-2">
                {s.pdfBase64 && (
                  <a href={s.pdfBase64} download={s.pdfName || "نموذج.pdf"}
                    className="flex items-center gap-1.5 px-3 py-1.5 bg-purple-50 text-purple-700 font-bold text-xs rounded-lg hover:bg-purple-100 transition-all">
                    <span>📄</span> {s.pdfName || "نموذج PDF"}
                  </a>
                )}
                {s.bookBase64 && (
                  <a href={s.bookBase64} download={s.bookName || "كتاب.pdf"}
                    className="flex items-center gap-1.5 px-3 py-1.5 bg-blue-50 text-blue-700 font-bold text-xs rounded-lg hover:bg-blue-100 transition-all">
                    <span>📘</span> {s.bookName || "كتاب PDF"}
                  </a>
                )}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// ===== صفحة التقويم المدرسي =====
function GalleryPage() {
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showAdd, setShowAdd] = useState(false);
  const [form, setForm] = useState({ title:"", description:"", imageBase64:"" });
  const [saving, setSaving] = useState(false);
  const [preview, setPreview] = useState(null);
  const fileRef = useRef(null);

  useEffect(() => {
    DB.get("school-gallery", []).then(d => { setItems(Array.isArray(d) ? d : []); setLoading(false); });
  }, []);

  const handleImage = async (e) => {
    const file = e.target.files?.[0]; if (!file) return;
    if (!file.type.startsWith("image/")) { alert("صور فقط"); return; }
    if (file.size > 3 * 1024 * 1024) { alert("الحجم الأقصى 3 ميغابايت"); return; }
    const b64 = await readFileAsync(file, "dataurl");
    setForm(f => ({ ...f, imageBase64: b64 }));
    e.target.value = "";
  };

  const handleSave = async () => {
    if (!form.title.trim() || !form.imageBase64) { alert("أدخل العنوان والصورة"); return; }
    setSaving(true);
    const updated = [{ id: Date.now(), ...form, createdAt: new Date().toLocaleDateString("ar-SA") }, ...items];
    setItems(updated); await DB.set("school-gallery", updated);
    setForm({ title:"", description:"", imageBase64:"" });
    setShowAdd(false); setSaving(false);
  };

  const handleDelete = async (id) => {
    if (!confirm("حذف هذه الصورة؟")) return;
    const updated = items.filter(i => i.id !== id);
    setItems(updated); await DB.set("school-gallery", updated);
  };

  if (loading) return <div className="flex items-center justify-center h-64"><div className="text-4xl animate-bounce">🖼</div></div>;

  return (
    <div className="space-y-5">
      {preview && (
        <div className="fixed inset-0 z-50 bg-black bg-opacity-80 flex items-center justify-center p-4" onClick={() => setPreview(null)}>
          <div className="max-w-2xl w-full bg-white rounded-2xl overflow-hidden" onClick={e => e.stopPropagation()}>
            <img src={preview.imageBase64} alt={preview.title} className="w-full max-h-96 object-contain bg-gray-100" />
            <div className="p-4">
              <h3 className="font-black text-gray-800">{preview.title}</h3>
              {preview.description && <p className="text-sm text-gray-500 mt-1">{preview.description}</p>}
              <p className="text-xs text-gray-400 mt-2">{preview.createdAt}</p>
            </div>
          </div>
        </div>
      )}

      <div className="page-header-bar" style={{background:"linear-gradient(135deg,#db2777,#7c3aed)"}}>
        <div className={cx.row}>
          <div>
            <h2 className="text-2xl font-black">🖼 معرض الأنشطة</h2>
            <p className="opacity-80 text-sm mt-1">أبرز الفعاليات والأنشطة المدرسية</p>
          </div>
          <button onClick={() => setShowAdd(!showAdd)} className="px-5 py-2.5 bg-white text-pink-700 font-black rounded-2xl hover:shadow-lg">
            {showAdd ? "إلغاء" : "+ إضافة صورة"}
          </button>
        </div>
      </div>

      {showAdd && (
        <div className="bg-white rounded-2xl p-5 shadow-sm border-2 border-pink-200 space-y-3">
          <h3 className="font-black text-pink-800">إضافة صورة للمعرض</h3>
          <div className="grid gap-3 sm:grid-cols-2">
            <div>
              <label className={cx.label}>العنوان *</label>
              <input value={form.title} onChange={e => setForm(f => ({...f,title:e.target.value}))}
                placeholder="مثال: بطولة كرة القدم الداخلية"
                className="w-full px-3 py-2 rounded-xl border-2 border-gray-200 focus:border-pink-400 focus:outline-none text-sm" />
            </div>
            <div>
              <label className={cx.label}>الوصف</label>
              <input value={form.description} onChange={e => setForm(f => ({...f,description:e.target.value}))}
                placeholder="وصف مختصر…"
                className="w-full px-3 py-2 rounded-xl border-2 border-gray-200 focus:border-pink-400 focus:outline-none text-sm" />
            </div>
          </div>
          <div className="border-2 border-dashed border-pink-200 rounded-xl p-6 text-center hover:border-pink-400 transition-all">
            {form.imageBase64 ? (
              <div className="relative inline-block">
                <img src={form.imageBase64} alt="preview" className="max-h-40 rounded-lg mx-auto" />
                <button onClick={() => setForm(f => ({...f,imageBase64:""}))} className="absolute -top-2 -right-2 w-6 h-6 bg-red-500 text-white rounded-full text-xs font-bold">✕</button>
              </div>
            ) : (
              <div>
                <div className="text-4xl mb-2">🖼</div>
                <button onClick={() => fileRef.current?.click()} className="px-4 py-2 bg-pink-600 text-white text-sm font-bold rounded-xl hover:bg-pink-700">
                  اختر صورة
                </button>
                <p className="text-xs text-gray-400 mt-2">JPG, PNG, WEBP — الحجم الأقصى 3 ميغابايت</p>
              </div>
            )}
            <input ref={fileRef} type="file" accept="image/*" onChange={handleImage} className="hidden" />
          </div>
          <button onClick={handleSave} disabled={saving} className="px-6 py-2.5 bg-pink-600 text-white font-black rounded-xl hover:bg-pink-700 disabled:opacity-50">
            {saving ? "حفظ…" : "💾 إضافة للمعرض"}
          </button>
        </div>
      )}

      {items.length === 0 ? (
        <div className="bg-white rounded-2xl p-12 text-center shadow-sm">
          <div className="text-5xl mb-3">🖼</div>
          <p className="font-black text-gray-600">المعرض فارغ</p>
        </div>
      ) : (
        <div className="grid grid-cols-2 sm:grid-cols-3 gap-4">
          {items.map(item => (
            <div key={item.id} className="bg-white rounded-2xl overflow-hidden shadow-sm border border-gray-100 group hover:shadow-md transition-all cursor-pointer" onClick={() => setPreview(item)}>
              <div className="relative aspect-video overflow-hidden bg-gray-100">
                <img src={item.imageBase64} alt={item.title} className="w-full h-full object-cover group-hover:scale-105 transition-transform" />
                <button onClick={e => { e.stopPropagation(); handleDelete(item.id); }}
                  className="absolute top-2 left-2 w-7 h-7 bg-red-500 text-white rounded-full text-xs opacity-0 group-hover:opacity-100 transition-opacity font-bold">
                  ✕
                </button>
              </div>
              <div className="p-3">
                <p className="font-black text-gray-800 text-sm line-clamp-1">{item.title}</p>
                {item.description && <p className="text-xs text-gray-400 mt-0.5 line-clamp-1">{item.description}</p>}
                <p className="text-xs text-gray-300 mt-1">{item.createdAt}</p>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// ===== صفحة الشهادات الرقمية =====
function CertificatesPage({ teachers, attendance, week, classList }) {
  const [certs, setCerts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showAdd, setShowAdd] = useState(false);
  const [form, setForm] = useState({ name:"", type:"تقدير", reason:"", date:new Date().toLocaleDateString("ar-SA") });
  const [saving, setSaving] = useState(false);

  const CERT_TYPES = ["تقدير","إنجاز","تميّز","مشاركة","قيادة","إبداع"];
  const TYPE_COLORS = {
    "تقدير":"#0d9488","إنجاز":"#7c3aed","تميّز":"#d97706","مشاركة":"#0284c7","قيادة":"#dc2626","إبداع":"#db2777"
  };

  useEffect(() => {
    DB.get("school-certificates", []).then(d => { setCerts(Array.isArray(d) ? d : []); setLoading(false); });
  }, []);

  const handleSave = async () => {
    if (!form.name.trim() || !form.reason.trim()) { alert("أدخل الاسم والسبب"); return; }
    setSaving(true);
    const newCert = { id: Date.now(), ...form };
    const updated = [newCert, ...certs];
    setCerts(updated); await DB.set("school-certificates", updated);
    setForm({ name:"", type:"تقدير", reason:"", date: new Date().toLocaleDateString("ar-SA") });
    setShowAdd(false); setSaving(false);
  };

  const printCert = (cert) => {
    const color = TYPE_COLORS[cert.type] || "#0d9488";
    printWindow(`<!DOCTYPE html><html dir="rtl"><head><meta charset="utf-8">
    <title>شهادة ${cert.type}</title>
    <style>
      *{margin:0;padding:0;box-sizing:border-box}
      body{font-family:'Amiri',serif;background:#fffbf0;display:flex;align-items:center;justify-content:center;min-height:100vh;padding:20px}
      .cert{width:700px;background:white;border:8px double ${color};border-radius:16px;padding:40px;text-align:center;position:relative;box-shadow:0 4px 40px rgba(0,0,0,.1)}
      .corner{position:absolute;width:60px;height:60px;border:3px solid ${color};opacity:.3}
      .tl{top:10px;left:10px;border-right:none;border-bottom:none;border-radius:8px 0 0 0}
      .tr{top:10px;right:10px;border-left:none;border-bottom:none;border-radius:0 8px 0 0}
      .bl{bottom:10px;left:10px;border-right:none;border-top:none;border-radius:0 0 0 8px}
      .br{bottom:10px;right:10px;border-left:none;border-top:none;border-radius:0 0 8px 0}
      .star{font-size:36px;margin-bottom:10px}
      .school{font-size:14px;color:#555;margin-bottom:8px;font-weight:bold}
      .type-title{font-size:30px;font-weight:900;color:${color};margin:10px 0;letter-spacing:2px}
      .divider{width:200px;height:3px;background:linear-gradient(to right,transparent,${color},transparent);margin:16px auto}
      .present{font-size:16px;color:#777;margin-bottom:10px}
      .name{font-size:28px;font-weight:900;color:#1a1a1a;margin:10px 0;border-bottom:2px solid ${color};display:inline-block;padding-bottom:6px}
      .reason{font-size:15px;color:#444;margin:16px auto;max-width:500px;line-height:1.8}
      .date{font-size:13px;color:#999;margin-top:24px}
      .seal{font-size:50px;margin-top:20px}
      @media print{body{background:white}@page{size:A4 landscape;margin:1cm}}
    </style></head><body>
    <div class="cert">
      <div class="corner tl"></div><div class="corner tr"></div>
      <div class="corner bl"></div><div class="corner br"></div>
      <div class="star">⭐</div>
      <div class="school">مدرسة الأمير عبدالمجيد المتوسطة الأولى — الإدارة العامة للتعليم بجدة</div>
      <div class="type-title">شهادة ${cert.type}</div>
      <div class="divider"></div>
      <div class="present">يُشرِّف إدارة المدرسة أن تُقدِّم هذه الشهادة إلى</div>
      <div class="name">${cert.name}</div>
      <div class="reason">${cert.reason}</div>
      <div class="date">بتاريخ: ${cert.date}</div>
      <div class="seal">🏅</div>
    </div>
    <script>window.onload=()=>window.print()</script>
    </body></html>`);
  };

  const handleDelete = async (id) => {
    const updated = certs.filter(c => c.id !== id);
    setCerts(updated); await DB.set("school-certificates", updated);
  };

  if (loading) return <div className="flex items-center justify-center h-64"><div className="text-4xl animate-bounce">🏅</div></div>;

  return (
    <div className="space-y-5">
      <div className="page-header-bar" style={{background:"linear-gradient(135deg,#d97706,#b45309)"}}>
        <div className={cx.row}>
          <div>
            <h2 className="text-2xl font-black">🏅 الشهادات الرقمية</h2>
            <p className="opacity-80 text-sm mt-1">إصدار وطباعة شهادات احترافية للمعلمين والطلاب</p>
          </div>
          <button onClick={() => setShowAdd(!showAdd)} className="px-5 py-2.5 bg-white text-amber-700 font-black rounded-2xl hover:shadow-lg">
            {showAdd ? "إلغاء" : "🏅 إصدار شهادة"}
          </button>
        </div>
      </div>

      {showAdd && (
        <div className="bg-white rounded-2xl p-5 shadow-sm border-2 border-amber-200 space-y-3">
          <h3 className="font-black text-amber-800">إصدار شهادة جديدة</h3>
          <div className="grid gap-3 sm:grid-cols-2">
            <div>
              <label className={cx.label}>اسم المستحق *</label>
              <input value={form.name} onChange={e => setForm(f => ({...f,name:e.target.value}))}
                placeholder="اسم المعلم أو الطالب"
                className="w-full px-3 py-2 rounded-xl border-2 border-gray-200 focus:border-amber-400 focus:outline-none text-sm" />
            </div>
            <div>
              <label className={cx.label}>نوع الشهادة</label>
              <select value={form.type} onChange={e => setForm(f => ({...f,type:e.target.value}))}
                className="w-full px-3 py-2 rounded-xl border-2 border-gray-200 focus:border-amber-400 focus:outline-none text-sm bg-white">
                {CERT_TYPES.map(t => <option key={t}>{t}</option>)}
              </select>
            </div>
            <div className="sm:col-span-2">
              <label className={cx.label}>سبب الشهادة *</label>
              <input value={form.reason} onChange={e => setForm(f => ({...f,reason:e.target.value}))}
                placeholder="مثال: تميّزه في التعليم عن بُعد وتطوير مهارات طلابه الرقمية"
                className="w-full px-3 py-2 rounded-xl border-2 border-gray-200 focus:border-amber-400 focus:outline-none text-sm" />
            </div>
            <div>
              <label className={cx.label}>التاريخ</label>
              <input value={form.date} onChange={e => setForm(f => ({...f,date:e.target.value}))}
                className="w-full px-3 py-2 rounded-xl border-2 border-gray-200 focus:border-amber-400 focus:outline-none text-sm" />
            </div>
          </div>
          <button onClick={handleSave} disabled={saving} className="px-6 py-2.5 bg-amber-600 text-white font-black rounded-xl hover:bg-amber-700 disabled:opacity-50">
            {saving ? "حفظ…" : "💾 إصدار وحفظ"}
          </button>
        </div>
      )}

      {certs.length === 0 ? (
        <div className="bg-white rounded-2xl p-12 text-center shadow-sm">
          <div className="text-5xl mb-3">🏅</div>
          <p className="font-black text-gray-600">لا توجد شهادات</p>
        </div>
      ) : (
        <div className="grid gap-3 sm:grid-cols-2">
          {certs.map(cert => (
            <div key={cert.id} className="bg-white rounded-2xl p-4 shadow-sm border border-amber-100 flex items-center gap-4">
              <div className="w-14 h-14 rounded-2xl flex items-center justify-center text-2xl flex-shrink-0" style={{background:(TYPE_COLORS[cert.type] || "#0d9488")+"22"}}>🏅</div>
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2 flex-wrap">
                  <span className="font-black text-gray-800">{cert.name}</span>
                  <span className="px-2 py-0.5 rounded-full text-xs font-bold text-white" style={{background: TYPE_COLORS[cert.type] || "#0d9488"}}>{cert.type}</span>
                </div>
                <p className="text-xs text-gray-500 mt-0.5 line-clamp-1">{cert.reason}</p>
                <p className="text-xs text-gray-300 mt-0.5">{cert.date}</p>
              </div>
              <div className="flex flex-col gap-2 flex-shrink-0">
                <button onClick={() => printCert(cert)} className="px-3 py-1.5 bg-amber-100 text-amber-800 text-xs font-bold rounded-lg hover:bg-amber-200">🖨 طباعة</button>
                <button onClick={() => handleDelete(cert.id)} className="px-3 py-1.5 bg-red-50 text-red-500 text-xs font-bold rounded-lg hover:bg-red-100">حذف</button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// ===== صفحة تميّز المعلم =====
function PollPage({ teachers }) {
  const [votes, setVotes] = useState({});
  const [loading, setLoading] = useState(true);
  const [myVote, setMyVote] = useState(null);
  const [week, setWeek] = useState(() => {
    const now = new Date(); const startOfWeek = new Date(now);
    startOfWeek.setDate(now.getDate() - now.getDay());
    return startOfWeek.toISOString().split("T")[0];
  });
  const [winners, setWinners] = useState([]);

  useEffect(() => {
    const key = `school-poll-${week}`;
    DB.get(key, {}).then(d => {
      setVotes(d && typeof d === "object" ? d : {});
      setLoading(false);
    });
    DB.get("school-poll-winners", []).then(d => setWinners(Array.isArray(d) ? d : []));
    const saved = localStorage.getItem(`poll-vote-${week}`);
    if (saved) setMyVote(saved);
  }, [week]);

  const handleVote = async (name) => {
    if (myVote) return;
    const key = `school-poll-${week}`;
    const updated = { ...votes, [name]: (votes[name] || 0) + 1 };
    setVotes(updated); setMyVote(name);
    localStorage.setItem(`poll-vote-${week}`, name);
    await DB.set(key, updated);
  };

  const totalVotes = Object.values(votes).reduce((s, v) => s + v, 0);
  const sorted = [...(teachers || [])].sort((a,b) => (votes[b]||0) - (votes[a]||0));
  const topTeacher = sorted[0] && votes[sorted[0]] > 0 ? sorted[0] : null;

  const announceWinner = async () => {
    if (!topTeacher) return;
    const w = { name: topTeacher, votes: votes[topTeacher], week };
    const updated = [w, ...winners.slice(0, 9)];
    setWinners(updated); await DB.set("school-poll-winners", updated);
    alert(`✅ تم إعلان ${topTeacher} معلماً متميزاً للأسبوع!`);
  };

  if (loading) return <div className="flex items-center justify-center h-64"><div className="text-4xl animate-bounce">🏆</div></div>;

  return (
    <div className="space-y-5">
      <div className="page-header-bar" style={{background:"linear-gradient(135deg,#0d9488,#065f46)"}}>
        <div className={cx.row}>
          <div>
            <h2 className="text-2xl font-black">🏆 تميّز المعلم</h2>
            <p className="opacity-80 text-sm mt-1">تصويت أسبوعي لاختيار المعلم المتميز</p>
          </div>
          {topTeacher && (
            <button onClick={announceWinner} className="px-5 py-2.5 bg-white text-teal-700 font-black rounded-2xl hover:shadow-lg text-sm">
              🎖 إعلان المتميز
            </button>
          )}
        </div>
      </div>

      {myVote && (
        <div className="bg-teal-50 border border-teal-200 rounded-2xl p-4 text-center">
          <span className="font-black text-teal-700">✅ صوّتت لـ {myVote} — شكراً على مشاركتك</span>
        </div>
      )}

      <div className={cx.card}>
        <div className="flex items-center justify-between mb-4">
          <h3 className="font-black text-gray-800">نتائج التصويت</h3>
          <span className="text-sm text-gray-400">{totalVotes} صوت</span>
        </div>
        <div className="space-y-3 max-h-96 overflow-y-auto">
          {sorted.slice(0, 15).map((name, i) => {
            const v = votes[name] || 0;
            const pct = totalVotes > 0 ? Math.round(v / totalVotes * 100) : 0;
            return (
              <div key={name} className="flex items-center gap-3">
                <div className="w-7 h-7 rounded-full flex items-center justify-center text-xs font-black flex-shrink-0"
                  style={{ background: i === 0 ? "#fbbf24" : i === 1 ? "#9ca3af" : i === 2 ? "#cd7f32" : "#f3f4f6", color: i <= 2 ? "white" : "#6b7280" }}>
                  {i+1}
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center justify-between mb-1">
                    <span className="text-sm font-bold text-gray-800 truncate">{name}</span>
                    <span className="text-xs text-gray-400 flex-shrink-0 ml-2">{v} ({pct}%)</span>
                  </div>
                  <div className="h-2 bg-gray-100 rounded-full overflow-hidden">
                    <div className="h-full rounded-full transition-all" style={{ width: pct+"%", background: i === 0 ? "#fbbf24" : "#0d9488" }} />
                  </div>
                </div>
                {!myVote && (
                  <button onClick={() => handleVote(name)} className="px-3 py-1.5 bg-teal-600 text-white text-xs font-bold rounded-lg hover:bg-teal-700 flex-shrink-0">
                    صوّت
                  </button>
                )}
              </div>
            );
          })}
        </div>
      </div>

      {winners.length > 0 && (
        <div className="bg-white rounded-2xl p-5 shadow-sm border border-amber-100">
          <h3 className="font-black text-amber-700 mb-4">🏆 المعلمون المتميزون</h3>
          <div className="space-y-2">
            {winners.map((w, i) => (
              <div key={i} className="flex items-center gap-3 py-2 border-b border-gray-50 last:border-0">
                <span className="text-xl">{i === 0 ? "🥇" : i === 1 ? "🥈" : i === 2 ? "🥉" : "🏅"}</span>
                <span className="font-bold text-gray-800 flex-1">{w.name}</span>
                <span className="text-xs text-gray-400">{w.votes} صوت</span>
                <span className="text-xs text-gray-300">{w.week}</span>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

// ===== بوابة الطلاب — تسجيل السحب (عامة بدون دخول) =====
function StudentRafflePortal({ siteFont, onBack }) {
  const CARRIERS = ["STC","موبايلي","زين"];
  const [form, setForm] = useState({ name:"", class:"", carrier:"STC" });
  const [entries, setEntries] = useState([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [done, setDone] = useState(false);
  const [totalCount, setTotalCount] = useState(0);

  useEffect(() => {
    DB.get("school-raffle-entries", []).then(d => {
      const list = Array.isArray(d) ? d : [];
      setEntries(list);
      setTotalCount(list.length);
      setLoading(false);
    });
  }, []);

  const handleRegister = async () => {
    if (!form.name.trim()) { alert("أدخل اسمك الكامل"); return; }
    if (!form.class.trim()) { alert("أدخل فصلك الدراسي"); return; }
    const dup = entries.find(e => e.name.trim() === form.name.trim() && e.class.trim() === form.class.trim());
    if (dup) { alert("تم تسجيلك مسبقاً في هذا السحب!"); return; }
    setSaving(true);
    const newEntry = { id: Date.now(), ...form, registeredAt: new Date().toLocaleString("ar-SA") };
    const updated = [...entries, newEntry];
    setEntries(updated);
    setTotalCount(updated.length);
    await DB.set("school-raffle-entries", updated);
    setSaving(false);
    setDone(true);
  };

  if (loading) return (
    <div className="min-h-screen flex items-center justify-center" style={{fontFamily:siteFont, background:"linear-gradient(135deg,#7c3aed,#db2777,#f59e0b)"}}>
      <div className="text-white text-center"><div className="text-6xl animate-bounce mb-4">🎰</div><p className="font-black">جاري التحميل…</p></div>
    </div>
  );

  return (
    <div dir="rtl" className="min-h-screen flex flex-col items-center justify-center p-4"
      style={{ fontFamily: siteFont, background: "linear-gradient(135deg,#7c3aed 0%,#db2777 50%,#f59e0b 100%)" }}>
      <style>{`
        @keyframes float { 0%,100%{transform:translateY(0)} 50%{transform:translateY(-10px)} }
        .float-ico { animation: float 2.5s ease-in-out infinite; }
        @keyframes prize-in { 0%{transform:scale(0);opacity:0} 70%{transform:scale(1.1)} 100%{transform:scale(1);opacity:1} }
        .prize-in { animation: prize-in .5s cubic-bezier(.34,1.56,.64,1) forwards; }
      `}</style>

      <div className="w-full max-w-md">
        <div className="text-center text-white mb-6">
          <div className="text-7xl float-ico mb-3">🎰</div>
          <h1 className="text-2xl font-black mb-1">سحب الجوائز</h1>
          <p className="opacity-80 text-sm">مدرسة الأمير عبدالمجيد المتوسطة الأولى</p>
        </div>

        <div className="grid grid-cols-3 gap-2 mb-5">
          {[{emoji:"🥇",val:"50 ريال"},{emoji:"🥈",val:"30 ريال"},{emoji:"🥉",val:"20 ريال"}].map((p,i) => (
            <div key={i} className="prize-in bg-white bg-opacity-20 rounded-2xl p-3 text-center text-white border border-white border-opacity-30" style={{animationDelay:(i*0.15)+"s"}}>
              <div className="text-2xl">{p.emoji}</div>
              <div className="font-black text-sm mt-1">{p.val}</div>
              <div className="text-xs opacity-70">بطاقة شحن</div>
            </div>
          ))}
        </div>

        {done ? (
          <div className="bg-white rounded-3xl p-8 text-center shadow-2xl">
            <div className="text-6xl mb-4">🎉</div>
            <h2 className="text-2xl font-black text-gray-800 mb-2">تم تسجيلك!</h2>
            <p className="text-gray-500 mb-1">بالتوفيق يا <span className="font-black text-purple-700">{form.name}</span> 🍀</p>
            <p className="text-gray-400 text-sm mb-4">أنت المشترك رقم <span className="font-black text-pink-600 text-xl">{totalCount}</span></p>
            <div className="flex gap-2 justify-center mb-5 flex-wrap">
              <span className={`px-3 py-1.5 rounded-full text-sm font-bold ${form.carrier==="STC"?"bg-purple-100 text-purple-700":form.carrier==="موبايلي"?"bg-green-100 text-green-700":"bg-yellow-100 text-yellow-700"}`}>
                {form.carrier==="STC"?"🟣":form.carrier==="موبايلي"?"🟢":"🟡"} {form.carrier}
              </span>
              <span className="px-3 py-1.5 rounded-full text-sm font-bold bg-blue-100 text-blue-700">📚 {form.class}</span>
            </div>
            <p className="text-xs text-gray-400 mb-5">سيُعلَن عن الفائزين من قِبل الإدارة</p>
            <button onClick={() => { setDone(false); setForm({ name:"", class:"", carrier:"STC" }); }}
              className="w-full py-3 rounded-2xl font-black text-white mb-2" style={{background:"linear-gradient(135deg,#7c3aed,#db2777)"}}>
              🎟 تسجيل طالب آخر
            </button>
            <button onClick={onBack} className="w-full py-2.5 rounded-2xl text-gray-500 font-bold text-sm bg-gray-50 hover:bg-gray-100">
              ← العودة للرئيسية
            </button>
          </div>
        ) : (
          <div className="bg-white rounded-3xl p-6 shadow-2xl space-y-4">
            <div className="text-center mb-1">
              <h2 className="text-xl font-black text-gray-800">🎟 اشترك في السحب</h2>
              <p className="text-xs text-gray-400 mt-1">{totalCount} مشترك حتى الآن</p>
            </div>
            <div>
              <label className={cx.labelX}>👤 اسمك الكامل</label>
              <input value={form.name} onChange={e => setForm(f=>({...f,name:e.target.value}))}
                placeholder="أدخل اسمك الثلاثي"
                className="w-full px-4 py-3.5 rounded-2xl border-2 border-gray-200 focus:border-purple-400 focus:outline-none text-sm font-bold" />
            </div>
            <div>
              <label className={cx.labelX}>📚 الفصل الدراسي</label>
              <input value={form.class} onChange={e => setForm(f=>({...f,class:e.target.value}))}
                placeholder="مثال: أول أ — ثاني ب — ثالث ج"
                className="w-full px-4 py-3.5 rounded-2xl border-2 border-gray-200 focus:border-purple-400 focus:outline-none text-sm font-bold" />
            </div>
            <div>
              <label className={cx.labelX}>📱 نوع الشريحة</label>
              <div className="grid grid-cols-3 gap-2">
                {CARRIERS.map(c => (
                  <button key={c} onClick={() => setForm(f=>({...f,carrier:c}))}
                    className={`py-3.5 rounded-2xl font-black text-sm border-2 transition-all ${form.carrier===c
                      ? c==="STC"?"bg-purple-600 text-white border-purple-600 shadow-md"
                        : c==="موبايلي"?"bg-green-600 text-white border-green-600 shadow-md"
                        : "bg-yellow-500 text-white border-yellow-500 shadow-md"
                      : "bg-gray-50 text-gray-600 border-gray-200"}`}>
                    {c==="STC"?"🟣 STC":c==="موبايلي"?"🟢 موبايلي":"🟡 زين"}
                  </button>
                ))}
              </div>
            </div>
            <button onClick={handleRegister} disabled={saving}
              className="w-full py-4 rounded-2xl font-black text-white text-base disabled:opacity-60"
              style={{background:"linear-gradient(135deg,#7c3aed,#db2777)"}}>
              {saving ? "⏳ جاري التسجيل…" : "🎰 اشترك الآن"}
            </button>
            <button onClick={onBack} className="w-full py-2.5 rounded-2xl text-sm text-gray-400 font-bold">← العودة</button>
          </div>
        )}
      </div>
    </div>
  );
}

// ===== صفحة سحب الطلاب 🎰 =====
function RafflePage() {
  const PRIZES = [
    { label: "بطاقة شحن 50 ريال",  value: 50, emoji: "🥇", color: "#f59e0b", bg: "#fffbeb", border: "#fde68a" },
    { label: "بطاقة شحن 30 ريال",  value: 30, emoji: "🥈", color: "#6366f1", bg: "#eef2ff", border: "#c7d2fe" },
    { label: "بطاقة شحن 20 ريال",  value: 20, emoji: "🥉", color: "#0d9488", bg: "#f0fdfa", border: "#99f6e4" },
  ];
  const CARRIERS = ["STC","موبايلي","زين"];

  const [tab, setTab] = useState("register"); // register | admin | draw | winners
  const [form, setForm] = useState({ name:"", class:"", carrier:"STC" });
  const [entries, setEntries] = useState([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [registered, setRegistered] = useState(false);
  const [winners, setWinners] = useState([]);
  const [drawing, setDrawing] = useState(false);
  const [drawStep, setDrawStep] = useState(-1); // which prize is being drawn
  const [spinName, setSpinName] = useState("");
  const [adminPin, setAdminPin] = useState("");
  const [pinOk, setPinOk] = useState(false);
  const [pinErr, setPinErr] = useState(false);
  const ADMIN_PIN = import.meta.env.VITE_RAFFLE_PIN || "1234";

  useEffect(() => {
    Promise.all([
      DB.get("school-raffle-entries", []),
      DB.get("school-raffle-winners", []),
    ]).then(([e, w]) => {
      setEntries(Array.isArray(e) ? e : []);
      setWinners(Array.isArray(w) ? w : []);
      setLoading(false);
    });
  }, []);

  // تسجيل طالب
  const handleRegister = async () => {
    if (!form.name.trim()) { alert("أدخل اسمك"); return; }
    if (!form.class.trim()) { alert("أدخل فصلك"); return; }
    const dup = entries.find(e => e.name.trim() === form.name.trim() && e.class === form.class);
    if (dup) { alert("تم تسجيلك مسبقاً!"); return; }
    setSaving(true);
    const newEntry = { id: Date.now(), ...form, registeredAt: new Date().toLocaleString("ar-SA") };
    const updated = [...entries, newEntry];
    setEntries(updated);
    await DB.set("school-raffle-entries", updated);
    setRegistered(true); setSaving(false);
  };

  // السحب الآلي
  const runDraw = async () => {
    if (entries.length < PRIZES.length) { alert(`يجب أن يكون هناك على الأقل ${PRIZES.length} مشتركين`); return; }
    setDrawing(true);
    const pool = [...entries];
    const drawn = [];

    for (let i = 0; i < PRIZES.length; i++) {
      setDrawStep(i);
      // تأثير دوران الأسماء
      await new Promise(res => {
        let count = 0;
        const total = 30 + i * 10;
        const interval = setInterval(() => {
          const rand = pool[Math.floor(Math.random() * pool.length)];
          setSpinName(rand.name);
          count++;
          if (count >= total) {
            clearInterval(interval);
            // اختيار الفائز الحقيقي
            const winIdx = Math.floor(Math.random() * pool.length);
            const winner = pool.splice(winIdx, 1)[0];
            setSpinName(winner.name);
            drawn.push({ ...winner, prize: PRIZES[i] });
            setTimeout(res, 1200);
          }
        }, 80 - i * 10);
      });
      await new Promise(res => setTimeout(res, 800));
    }

    setWinners(drawn);
    await DB.set("school-raffle-winners", drawn);
    setDrawing(false);
    setDrawStep(-1);
    setTab("winners");
  };

  const resetAll = async () => {
    if (!confirm("⚠️ هل تريد إعادة ضبط السحب وحذف جميع المشتركين والفائزين؟")) return;
    setEntries([]); setWinners([]); setRegistered(false);
    await DB.set("school-raffle-entries", []);
    await DB.set("school-raffle-winners", []);
  };

  if (loading) return (
    <div className="flex items-center justify-center h-64">
      <div className="text-5xl animate-bounce">🎰</div>
    </div>
  );

  return (
    <div className="space-y-5" dir="rtl">
      <style>{`
        @keyframes spin-name { 0%{transform:scale(.9);opacity:.6} 50%{transform:scale(1.05);opacity:1} 100%{transform:scale(.9);opacity:.6} }
        .spin-name { animation: spin-name .16s ease-in-out infinite; }
        @keyframes winner-pop { 0%{transform:scale(0) rotate(-10deg);opacity:0} 70%{transform:scale(1.1) rotate(2deg)} 100%{transform:scale(1) rotate(0);opacity:1} }
        .winner-pop { animation: winner-pop .6s cubic-bezier(.34,1.56,.64,1) forwards; }
        @keyframes confetti-fall { 0%{transform:translateY(-20px) rotate(0deg);opacity:1} 100%{transform:translateY(60px) rotate(360deg);opacity:0} }
        .conf { animation: confetti-fall 1.5s ease-in forwards; position:absolute; pointer-events:none; }
      `}</style>

      {/* Header */}
      <div className="page-header-bar relative overflow-hidden" style={{background:"linear-gradient(135deg,#7c3aed,#db2777,#f59e0b)"}}>
        <div className="relative z-10 flex items-center justify-between flex-wrap gap-3">
          <div>
            <h2 className="text-2xl font-black">🎰 سحب الجوائز</h2>
            <p className="opacity-80 text-sm mt-1">بطاقات شحن 20 · 30 · 50 ريال</p>
          </div>
          <div className="flex items-center gap-2 text-sm">
            <span className="bg-white bg-opacity-20 rounded-xl px-3 py-1.5 font-black">{entries.length} مشترك</span>
          </div>
        </div>
      </div>

      {/* تبويبات */}
      <div className="flex gap-2">
        {[
          { id:"register", label:"🎟 تسجيل" },
          { id:"admin",    label:"⚙️ الإدارة" },
          { id:"winners",  label:"🏆 الفائزون" },
        ].map(t => (
          <button key={t.id} onClick={() => setTab(t.id)}
            className={`flex-1 py-2.5 rounded-2xl font-black text-sm transition-all ${tab === t.id ? "bg-purple-600 text-white shadow-md" : "bg-white text-gray-600 hover:bg-purple-50 border border-gray-200"}`}>
            {t.label}
          </button>
        ))}
      </div>

      {/* ===== تسجيل الطالب ===== */}
      {tab === "register" && (
        <div className="space-y-4">
          {/* الجوائز */}
          <div className="grid grid-cols-3 gap-3">
            {PRIZES.map(p => (
              <div key={p.value} className="rounded-2xl p-4 text-center border-2" style={{background:p.bg, borderColor:p.border}}>
                <div className="text-3xl">{p.emoji}</div>
                <div className="font-black mt-1 text-sm" style={{color:p.color}}>{p.value} ريال</div>
                <div className="text-xs text-gray-500 mt-0.5">بطاقة شحن</div>
              </div>
            ))}
          </div>

          {registered ? (
            <div className="bg-green-50 border-2 border-green-300 rounded-3xl p-8 text-center">
              <div className="text-5xl mb-3">✅</div>
              <h3 className="text-xl font-black text-green-700">تم تسجيلك بنجاح!</h3>
              <p className="text-green-600 mt-2">اسمك في القرعة — بالتوفيق 🍀</p>
              <p className="text-sm text-gray-400 mt-3">{form.name} — {form.class} — {form.carrier}</p>
              <button onClick={() => { setRegistered(false); setForm({ name:"", class:"", carrier:"STC" }); }}
                className="mt-4 px-6 py-2 bg-green-600 text-white font-bold rounded-xl hover:bg-green-700 text-sm">
                تسجيل طالب آخر
              </button>
            </div>
          ) : (
            <div className="bg-white rounded-3xl p-6 shadow-sm border border-purple-100 space-y-4">
              <h3 className="font-black text-purple-800 text-lg text-center">🎟 سجّل الآن</h3>

              <div>
                <label className={cx.labelX}>اسمك الكامل</label>
                <input value={form.name} onChange={e => setForm(f => ({...f,name:e.target.value}))}
                  placeholder="أدخل اسمك الثلاثي"
                  className="w-full px-4 py-3 rounded-2xl border-2 border-gray-200 focus:border-purple-400 focus:outline-none text-sm font-bold" />
              </div>

              <div>
                <label className={cx.labelX}>الفصل الدراسي</label>
                <input value={form.class} onChange={e => setForm(f => ({...f,class:e.target.value}))}
                  placeholder="مثال: أول أ — ثاني ب"
                  className="w-full px-4 py-3 rounded-2xl border-2 border-gray-200 focus:border-purple-400 focus:outline-none text-sm font-bold" />
              </div>

              <div>
                <label className={cx.labelX}>نوع الشريحة</label>
                <div className="grid grid-cols-3 gap-2">
                  {CARRIERS.map(c => (
                    <button key={c} onClick={() => setForm(f => ({...f,carrier:c}))}
                      className={`py-3 rounded-2xl font-black text-sm border-2 transition-all ${form.carrier === c
                        ? c === "STC" ? "bg-purple-600 text-white border-purple-600"
                          : c === "موبايلي" ? "bg-green-600 text-white border-green-600"
                          : "bg-yellow-500 text-white border-yellow-500"
                        : "bg-gray-50 text-gray-600 border-gray-200"}`}>
                      {c === "STC" ? "🟣 STC" : c === "موبايلي" ? "🟢 موبايلي" : "🟡 زين"}
                    </button>
                  ))}
                </div>
              </div>

              <button onClick={handleRegister} disabled={saving}
                className="w-full py-4 rounded-2xl font-black text-white text-base hover:shadow-lg transition-all disabled:opacity-50"
                style={{background:"linear-gradient(135deg,#7c3aed,#db2777)"}}>
                {saving ? "جاري التسجيل…" : "🎟 اشترك في السحب"}
              </button>
            </div>
          )}

          {entries.length > 0 && (
            <div className="bg-white rounded-2xl p-4 border border-gray-100 text-center">
              <p className="text-sm text-gray-500">عدد المشتركين: <span className="font-black text-purple-700 text-lg">{entries.length}</span></p>
            </div>
          )}
        </div>
      )}

      {/* ===== لوحة الإدارة ===== */}
      {tab === "admin" && (
        <div className="space-y-4">
          {!pinOk ? (
            <div className="bg-white rounded-3xl p-8 shadow-sm border border-gray-100 max-w-sm mx-auto text-center">
              <div className="text-4xl mb-3">🔐</div>
              <h3 className="font-black text-gray-800 mb-4">كود الإدارة</h3>
              <input type="password" value={adminPin} onChange={e => { setAdminPin(e.target.value); setPinErr(false); }}
                placeholder="أدخل الكود"
                className={`w-full px-4 py-3 rounded-2xl border-2 text-center text-xl font-black tracking-widest focus:outline-none ${pinErr ? "border-red-400 bg-red-50" : "border-gray-200 focus:border-purple-400"}`} />
              {pinErr && <p className="text-red-500 text-xs font-bold mt-2">كود خاطئ</p>}
              <button onClick={() => { if (adminPin === ADMIN_PIN) { setPinOk(true); } else { setPinErr(true); } }}
                className="mt-4 w-full py-3 bg-purple-600 text-white font-black rounded-2xl hover:bg-purple-700">
                دخول
              </button>

            </div>
          ) : (
            <div className="space-y-4">
              {/* زر السحب الكبير */}
              <div className="bg-gradient-to-br from-purple-600 via-pink-600 to-amber-500 rounded-b-2xl p-8 text-center text-white shadow-xl">
                <div className="text-5xl mb-3">🎰</div>
                <h3 className="text-2xl font-black mb-2">بدء السحب الآلي</h3>
                <p className="opacity-80 text-sm mb-6">{entries.length} مشترك · 3 فائزين</p>
                <button onClick={runDraw} disabled={drawing || entries.length < 3}
                  className="px-10 py-4 bg-white text-purple-700 font-black text-xl rounded-2xl hover:shadow-xl transition-all disabled:opacity-50 disabled:cursor-not-allowed">
                  {drawing ? "جاري السحب…" : "🎲 ابدأ السحب"}
                </button>
                {entries.length < 3 && <p className="text-xs opacity-70 mt-3">يجب تسجيل 3 مشتركين على الأقل</p>}
              </div>

              {/* تأثير السحب */}
              {drawing && (
                <div className="bg-white rounded-3xl p-8 text-center shadow-xl border-2 border-purple-200">
                  <div className="text-4xl mb-2">{PRIZES[drawStep]?.emoji || "🎰"}</div>
                  <p className="text-sm text-gray-500 font-bold mb-3">{PRIZES[drawStep]?.label || "جاري السحب"}</p>
                  <div className="spin-name text-3xl font-black text-purple-700 min-h-12 flex items-center justify-center">
                    {spinName || "…"}
                  </div>
                  <div className="flex gap-2 justify-center mt-4">
                    {PRIZES.map((p,i) => (
                      <div key={i} className={`w-3 h-3 rounded-full transition-all ${i === drawStep ? "scale-125" : "opacity-30"}`}
                        style={{background:p.color}} />
                    ))}
                  </div>
                </div>
              )}

              {/* قائمة المشتركين */}
              <div className={cx.cardSm}>
                <div className="p-4 border-b border-gray-100 flex items-center justify-between">
                  <span className="font-black text-gray-800">قائمة المشتركين ({entries.length})</span>
                  <button onClick={resetAll} className="text-xs text-red-500 font-bold px-3 py-1.5 rounded-lg bg-red-50 hover:bg-red-100">
                    🗑 إعادة ضبط
                  </button>
                </div>
                <div className="max-h-80 overflow-y-auto divide-y divide-gray-50">
                  {entries.length === 0 ? (
                    <p className="p-6 text-center text-gray-400 text-sm">لا يوجد مشتركون بعد</p>
                  ) : entries.map((e, i) => (
                    <div key={e.id} className="flex items-center gap-3 px-4 py-3">
                      <span className="w-6 h-6 rounded-full bg-gray-100 text-gray-500 text-xs font-black flex items-center justify-center">{i+1}</span>
                      <div className="flex-1">
                        <span className="font-bold text-gray-800 text-sm">{e.name}</span>
                        <span className="text-xs text-gray-400 mr-2">— {e.class}</span>
                      </div>
                      <span className={`text-xs font-bold px-2 py-0.5 rounded-full ${e.carrier === "STC" ? "bg-purple-100 text-purple-700" : e.carrier === "موبايلي" ? "bg-green-100 text-green-700" : "bg-yellow-100 text-yellow-700"}`}>
                        {e.carrier}
                      </span>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          )}
        </div>
      )}

      {/* ===== الفائزون ===== */}
      {tab === "winners" && (
        <div className="space-y-4">
          {winners.length === 0 ? (
            <div className="bg-white rounded-3xl p-12 text-center shadow-sm">
              <div className="text-5xl mb-3">🏆</div>
              <p className="font-black text-gray-600">لم يُجرَ السحب بعد</p>
              <p className="text-sm text-gray-400 mt-1">اذهب للإدارة وابدأ السحب</p>
            </div>
          ) : (
            <>
              <div className="bg-gradient-to-br from-amber-400 via-yellow-300 to-amber-500 rounded-3xl p-6 text-center shadow-xl">
                <div className="text-4xl mb-2">🎊</div>
                <h3 className="text-2xl font-black text-amber-900">الفائزون بالسحب!</h3>
                <p className="text-amber-800 text-sm mt-1">مبروك للفائزين 🎉</p>
              </div>
              <div className="space-y-4">
                {winners.map((w, i) => (
                  <div key={i} className="winner-pop rounded-3xl p-6 border-2 shadow-lg text-center" style={{background:w.prize.bg, borderColor:w.prize.border, animationDelay:(i*0.2)+"s"}}>
                    <div className="text-5xl mb-2">{w.prize.emoji}</div>
                    <div className="text-3xl font-black mb-1" style={{color:w.prize.color}}>{w.name}</div>
                    <div className="text-sm text-gray-500 mb-3">{w.class}</div>
                    <div className="flex items-center justify-center gap-3">
                      <span className={`px-3 py-1 rounded-full text-sm font-black ${w.carrier === "STC" ? "bg-purple-200 text-purple-800" : w.carrier === "موبايلي" ? "bg-green-200 text-green-800" : "bg-yellow-200 text-yellow-800"}`}>
                        {w.carrier === "STC" ? "🟣" : w.carrier === "موبايلي" ? "🟢" : "🟡"} {w.carrier}
                      </span>
                      <span className="px-3 py-1 rounded-full text-sm font-black text-white" style={{background:w.prize.color}}>
                        {w.prize.label}
                      </span>
                    </div>
                  </div>
                ))}
              </div>
              <button onClick={() => window.print()}
                className="w-full py-3 rounded-2xl bg-gray-800 text-white font-black hover:bg-gray-900">
                🖨 طباعة النتائج
              </button>
            </>
          )}
        </div>
      )}
    </div>
  );
}

// ===== سجل حضور المعلم — قراءة فقط مع الأسباب =====
function TeacherAttendanceView({ currentTeacher, teachers, attendance, week, absenceReasons, saveAbsenceReason, savingReason, savedMsg }) {
  const ti = teachers ? teachers.findIndex(t => t === currentTeacher.name) : -1;
  const weekDays = week?.days || [];

  // فرز السجلات
  const allRecords = weekDays.map((day, di) => {
    const r = (attendance && ti >= 0) ? (attendance[ti]?.[di] || {}) : {};
    return { day, di, status: r.status || "حاضر", lateType: r.lateType || "صباحي", lateMinutes: r.lateMinutes || 0, latePeriods: r.latePeriods || [], absType: r.absType || "اضطراري", notes: r.notes || "" };
  });

  const morningLateRecs = allRecords.filter(r => r.status === "متأخر" && (r.lateType === "صباحي" || !r.lateType));
  const periodLateRecs  = allRecords.filter(r => r.status === "متأخر" && r.lateType === "حصص");
  const absRecs         = allRecords.filter(r => r.status === "غائب");

  const morningMins = morningLateRecs.reduce((s, r) => s + (parseInt(r.lateMinutes) || 0), 0);
  const periodMins  = periodLateRecs.reduce((s, r) => s + (parseInt(r.lateMinutes) || 0), 0);

  // بطاقة واحدة لكل سجل
  const RecordCard = ({ rec, color, icon }) => {
    const key = `${currentTeacher.name}__${rec.di}__${rec.day.dateH}`;
    const saved = absenceReasons[key] || {};
    const [localReason, setLocalReason] = React.useState(saved.reason || "");
    const [localFaresDate, setLocalFaresDate] = React.useState(saved.faresDate || "");
    React.useEffect(() => {
      setLocalReason(saved.reason || "");
      setLocalFaresDate(saved.faresDate || "");
    }, [key, absenceReasons]);

    const borderColor = color === "red" ? "border-red-300" : color === "orange" ? "border-orange-300" : "border-amber-300";
    const tagBg      = color === "red" ? "bg-red-100 text-red-800" : color === "orange" ? "bg-orange-100 text-orange-800" : "bg-amber-100 text-amber-800";

    return (
      <div className={`bg-white rounded-2xl border-2 ${borderColor} p-4 shadow-sm`}>
        <div className="flex flex-wrap items-start justify-between gap-2 mb-3">
          <div>
            <div className="font-black text-gray-800 text-sm">{rec.day.name}</div>
            <div className="text-xs text-gray-400 mt-0.5">{rec.day.dateH} هـ — {rec.day.dateM} م</div>
          </div>
          <div className="flex flex-wrap gap-1">
            <span className={`px-3 py-1 rounded-full text-xs font-black ${tagBg}`}>
              {icon} {rec.status === "غائب"
                ? `غياب — ${rec.absType}`
                : `تأخر ${rec.lateType === "صباحي" ? "صباحي" : "عن حصص"} — ${parseInt(rec.lateMinutes) || "?"} دقيقة`}
            </span>
            {rec.status === "متأخر" && rec.lateType === "حصص" && rec.latePeriods.length > 0 && (
              <span className="px-2 py-1 rounded-full text-xs font-bold bg-yellow-100 text-yellow-800">
                حصة: {rec.latePeriods.join("، ")}
              </span>
            )}
          </div>
        </div>
        {rec.notes && <div className="text-xs text-gray-500 mb-3 bg-gray-50 rounded-lg px-3 py-1.5">📝 ملاحظة الإدارة: {rec.notes}</div>}
        <div className="grid gap-2 sm:grid-cols-2">
          <div>
            <label className={cx.label}>سبب الغياب / التأخر</label>
            <input type="text" value={localReason} onChange={e => setLocalReason(e.target.value)}
              placeholder="أدخل السبب…"
              className={cx.inputT} />
          </div>
          <div>
            <label className={cx.label}>تاريخ الإدخال في فارس</label>
            <input type="text" value={localFaresDate} onChange={e => setLocalFaresDate(e.target.value)}
              placeholder="مثال: ١٠/٠٩/١٤٤٧ هـ"
              className={cx.inputT} />
          </div>
        </div>
        <div className="flex items-center justify-between mt-3">
          <span className="text-xs text-gray-400">{saved.savedAt ? `آخر تحديث: ${saved.savedAt}` : ""}</span>
          <button onClick={() => saveAbsenceReason(key, localReason, localFaresDate)}
            disabled={savingReason === key}
            className="px-4 py-2 rounded-xl bg-teal-600 text-white text-xs font-black hover:bg-teal-700 transition-all disabled:opacity-50">
            {savingReason === key ? "جاري الحفظ…" : "💾 حفظ"}
          </button>
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-6" dir="rtl">
      {/* تنبيه */}
      <div className="bg-blue-50 border border-blue-200 rounded-2xl p-3 text-center text-xs text-blue-700 font-bold">
        📌 هذه البيانات للاطلاع فقط — لا يمكن تعديلها. يمكنك فقط إضافة السبب وتاريخ الإدخال في فارس.
      </div>

      {/* ===== ملخص الأرقام ===== */}
      <div className="grid grid-cols-2 sm:grid-cols-5 gap-3">
        <div className="bg-red-50 border border-red-200 rounded-2xl p-3 text-center">
          <div className="text-3xl font-black text-red-700">{absRecs.length}</div>
          <div className="text-xs text-red-500 font-bold mt-1">❌ مرات الغياب</div>
        </div>
        <div className="bg-amber-50 border border-amber-200 rounded-2xl p-3 text-center">
          <div className="text-3xl font-black text-amber-700">{morningLateRecs.length}</div>
          <div className="text-xs text-amber-600 font-bold mt-1">🌅 تأخر صباحي</div>
        </div>
        <div className="bg-orange-50 border border-orange-200 rounded-2xl p-3 text-center">
          <div className="text-3xl font-black text-orange-700">{morningMins}</div>
          <div className="text-xs text-orange-500 font-bold mt-1">⏱ دقائق صباحي</div>
        </div>
        <div className="bg-yellow-50 border border-yellow-200 rounded-2xl p-3 text-center">
          <div className="text-3xl font-black text-yellow-700">{periodLateRecs.length}</div>
          <div className="text-xs text-yellow-600 font-bold mt-1">📚 تأخر عن حصص</div>
        </div>
        <div className="bg-lime-50 border border-lime-200 rounded-2xl p-3 text-center">
          <div className="text-3xl font-black text-lime-700">{periodMins}</div>
          <div className="text-xs text-lime-600 font-bold mt-1">⏱ دقائق حصص</div>
        </div>
      </div>

      {/* ===== قسم الغياب ===== */}
      <div>
        <div className="flex items-center gap-2 mb-3">
          <div className="w-4 h-4 rounded-full bg-red-500"></div>
          <h3 className="font-black text-red-700 text-base">سجل الغياب</h3>
          <span className="bg-red-100 text-red-700 text-xs font-black px-2 py-0.5 rounded-full">{absRecs.length}</span>
        </div>
        {absRecs.length === 0 ? (
          <div className="bg-green-50 border border-green-100 rounded-2xl p-5 text-center text-green-700 font-bold text-sm">✅ لا يوجد غياب مسجل هذا الأسبوع</div>
        ) : (
          <div className="space-y-3">
            {absRecs.map(rec => <RecordCard key={rec.di} rec={rec} color="red" icon="❌" />)}
          </div>
        )}
      </div>

      {/* ===== قسم التأخر الصباحي ===== */}
      <div>
        <div className="flex items-center gap-2 mb-3">
          <div className="w-4 h-4 rounded-full bg-amber-500"></div>
          <h3 className="font-black text-amber-700 text-base">سجل التأخر الصباحي</h3>
          <span className="bg-amber-100 text-amber-700 text-xs font-black px-2 py-0.5 rounded-full">{morningLateRecs.length} مرة — {morningMins} دقيقة</span>
        </div>
        {morningLateRecs.length === 0 ? (
          <div className="bg-green-50 border border-green-100 rounded-2xl p-5 text-center text-green-700 font-bold text-sm">✅ لا يوجد تأخر صباحي مسجل</div>
        ) : (
          <div className="space-y-3">
            {morningLateRecs.map(rec => <RecordCard key={rec.di} rec={rec} color="amber" icon="🌅" />)}
          </div>
        )}
      </div>

      {/* ===== قسم التأخر عن الحصص ===== */}
      <div>
        <div className="flex items-center gap-2 mb-3">
          <div className="w-4 h-4 rounded-full bg-orange-500"></div>
          <h3 className="font-black text-orange-700 text-base">سجل التأخر عن الحصص</h3>
          <span className="bg-orange-100 text-orange-700 text-xs font-black px-2 py-0.5 rounded-full">{periodLateRecs.length} مرة — {periodMins} دقيقة</span>
        </div>
        {periodLateRecs.length === 0 ? (
          <div className="bg-green-50 border border-green-100 rounded-2xl p-5 text-center text-green-700 font-bold text-sm">✅ لا يوجد تأخر عن حصص مسجل</div>
        ) : (
          <div className="space-y-3">
            {periodLateRecs.map(rec => <RecordCard key={rec.di} rec={rec} color="orange" icon="📚" />)}
          </div>
        )}
      </div>

      {savedMsg && (
        <div className="fixed bottom-6 left-1/2 -translate-x-1/2 bg-teal-600 text-white px-6 py-3 rounded-2xl font-black shadow-xl z-50 text-sm">{savedMsg}</div>
      )}
    </div>
  );
}

// ═══════════════════════════════════════════
// 🎯 مكوّن التقييم الذاتي من بوابة المعلم
// ═══════════════════════════════════════════
function TeacherSelfEval({ teacherInfo, onDone }) {
  const LS_KEY = "teacher_eval_records_v2";
  const loadLS = () => { try { const v = localStorage.getItem(LS_KEY); return v ? JSON.parse(v) : []; } catch { return []; } };
  const saveLS = (d) => {
    try { localStorage.setItem(LS_KEY, JSON.stringify(d)); } catch {}
    DB.set("school-teacher-eval", d); // Firebase backup
  };

  const OPT4    = ["دائماً","غالباً","أحياناً","لا"];
  const OPT_YN  = ["نعم","لا"];
  const OPT4_VAL= { "دائماً":4,"غالباً":3,"أحياناً":2,"لا":1 };
  const DEGREES = ["دبلوم","بكالوريوس","ماجستير","دكتوراه","أخرى"];
  const SPEC_YEARS = ["أقل من سنة","1-3 سنوات","4-7 سنوات","8-15 سنة","أكثر من 15 سنة"];
  const SUBJECTS_LIST = ["رياضيات","علوم","عربي","إنجليزي","تربية إسلامية","اجتماعيات","حاسب","تربية بدنية","فنون","أخرى"];
  const SCHOOL_LEVELS = ["ابتدائي","متوسط","ثانوي"];

  const SECTIONS = [
    { id:"identity", icon:"👤", title:"الهوية المهنية", color:"#0d9488", bg:"#f0fdfa", fields:[
      { id:"subject",    label:"المادة الدراسية",               type:"select", options:SUBJECTS_LIST },
      { id:"schoolLevel",label:"المرحلة",                       type:"select", options:SCHOOL_LEVELS },
      { id:"degree",     label:"آخر مؤهل علمي",                type:"select", options:DEGREES },
      { id:"degreeSpec", label:"تخصص المؤهل",                   type:"text",   placeholder:"مثال: رياضيات تطبيقية" },
      { id:"totalExp",   label:"سنوات الخبرة الكلية",           type:"select", options:SPEC_YEARS },
      { id:"schoolExp",  label:"سنوات الخدمة بالمدرسة الحالية",type:"select", options:SPEC_YEARS },
      { id:"pdCourses",  label:"الدورات التدريبية (آخر 3 سنوات)",type:"select",options:["لم أحضر أي دورة","1-2 دورة","3-5 دورات","أكثر من 5 دورات"] },
    ]},
    { id:"motivation", icon:"🔥", title:"الدافعية والطموح", color:"#d97706", bg:"#fffbeb", fields:[
      { id:"m1", label:"أشعر بالحماس عند الذهاب إلى المدرسة",               type:"opt4" },
      { id:"m2", label:"لديّ رغبة في إحداث فرق إيجابي في حياة طلابي",       type:"opt4" },
      { id:"m3", label:"أسعى إلى تطوير نفسي مهنياً بشكل مستمر",             type:"opt4" },
      { id:"m4", label:"أشعر بالرضا الوظيفي عن مهنة التدريس",               type:"opt4" },
      { id:"m5", label:"أرى التدريس مهنة مقدسة وليست مجرد وظيفة",           type:"opt4" },
      { id:"m6", label:"لديّ أهداف مهنية واضحة أسعى لتحقيقها",              type:"opt4" },
      { id:"m7", label:"أفكر في التقاعد المبكر أو تغيير المهنة",             type:"opt4" },
      { id:"m8", label:"لديّ طموح لتولي مناصب قيادية مستقبلاً",              type:"opt4" },
      { id:"m9", label:"هل سبق وتقدّمت لفرص قيادية أو تدريبية؟",            type:"opyn" },
      { id:"m10",label:"أسعى لنشر تجاربي التعليمية مع زملائي",               type:"opt4" },
    ]},
    { id:"frustration", icon:"😔", title:"الإحباط الوظيفي وأسبابه", color:"#dc2626", bg:"#fef2f2", fields:[
      { id:"f1",  label:"أشعر بإحباط وظيفي بشكل عام",                        type:"opt4" },
      { id:"f2",  label:"ضعف مستوى الطلاب وسلوكهم يؤثر سلباً عليّ",         type:"opt4", cause:true },
      { id:"f3",  label:"البيئة المدرسية (المرافق، التجهيزات) غير ملائمة",   type:"opt4", cause:true },
      { id:"f4",  label:"الأنظمة والتعليمات الجديدة تشكّل ضغطاً عليّ",      type:"opt4", cause:true },
      { id:"f5",  label:"العلاقة مع إدارة المدرسة تؤثر على أدائي",           type:"opt4", cause:true },
      { id:"f6",  label:"أعباء العمل الإداري والأوراق تستنزفني",              type:"opt4", cause:true },
      { id:"f7",  label:"ظروف اجتماعية وأسرية خاصة تؤثر على أدائي",         type:"opt4", cause:true },
      { id:"f8",  label:"وضع صحي يؤثر على قدرتي على العطاء",                 type:"opt4", cause:true },
      { id:"f9",  label:"غياب التقدير والحوافز الكافية",                      type:"opt4", cause:true },
      { id:"f10", label:"علاقات العمل مع الزملاء غير داعمة",                 type:"opt4", cause:true },
      { id:"f11", label:"هل سبق وطلبت الدعم أو التوجيه من المشرف أو المدير؟",type:"opyn" },
    ]},
    { id:"innovation", icon:"💡", title:"الابتكار في التدريس", color:"#7c3aed", bg:"#faf5ff", fields:[
      { id:"i1",  label:"أستخدم استراتيجيات تدريس متنوعة في حصصي",           type:"opt4" },
      { id:"i2",  label:"أُدخل التقنية والأدوات الرقمية في شرح المادة",       type:"opt4" },
      { id:"i3",  label:"أُصمّم نشاطات وألعاب تعليمية تناسب طلابي",          type:"opt4" },
      { id:"i4",  label:"أبتكر مواد ووسائل تعليمية من إعدادي الخاص",         type:"opt4" },
      { id:"i5",  label:"أُعدّ دروساً تفاعلية تجعل الطالب محور التعلم",      type:"opt4" },
      { id:"i6",  label:"أُخصّص التدريس بحسب مستويات الطلاب المختلفة",       type:"opt4" },
      { id:"i7",  label:"أُصمّم خططاً تعليمية لطلاب صعوبات التعلم",          type:"opt4" },
      { id:"i8",  label:"أستثمر نتائج التقييمات لتعديل طريقة تدريسي",         type:"opt4" },
      { id:"i9",  label:"أُنوّع في أدوات التقييم (مشاريع، عروض، تقييم الأقران)", type:"opt4" },
      { id:"i10", label:"أُدمج مهارات القرن الحادي والعشرين في حصصي",         type:"opt4" },
    ]},
    { id:"development", icon:"📈", title:"التطوير المهني", color:"#0284c7", bg:"#eff6ff", fields:[
      { id:"d1",  label:"أحضر ورش عمل ودورات تدريبية بشكل منتظم",           type:"opt4" },
      { id:"d2",  label:"أطّلع على الأبحاث والمستجدات التربوية",              type:"opt4" },
      { id:"d3",  label:"أُشارك في مجتمعات التعلم المهني مع الزملاء",        type:"opt4" },
      { id:"d4",  label:"لديّ ملف إنجاز مهني أُحدّثه باستمرار",             type:"opt4" },
      { id:"d5",  label:"أُطبّق ما أتعلمه من الدورات في حصصي الفعلية",      type:"opt4" },
      { id:"d6",  label:"لديّ خطة تطوير مهنية شخصية مكتوبة",                type:"opt4" },
      { id:"d7",  label:"أُقيّم نفسي وأطلب تغذية راجعة من زملائي",          type:"opt4" },
      { id:"d8",  label:"أطمح لاستكمال دراسات عليا مستقبلاً",               type:"opyn" },
      { id:"d9",  label:"هل تودّ المشاركة في برنامج تطوير مهني مخصص لك؟",   type:"opyn" },
    ]},
    { id:"relations", icon:"🤝", title:"بيئة العمل والعلاقات", color:"#059669", bg:"#f0fdf4", fields:[
      { id:"r1",  label:"علاقتي مع إدارة المدرسة إيجابية وداعمة",            type:"opt4" },
      { id:"r2",  label:"أتلقى دعماً ومساندة من زملائي المعلمين",            type:"opt4" },
      { id:"r3",  label:"أجد التغذية الراجعة من المشرف مفيدة وبنّاءة",       type:"opt4" },
      { id:"r4",  label:"أُشارك في اجتماعات المدرسة بفاعلية وأُسهم برأيي",  type:"opt4" },
      { id:"r5",  label:"علاقتي مع أولياء الأمور إيجابية وتعاونية",         type:"opt4" },
      { id:"r6",  label:"أشعر بأن جهودي معترف بها من الإدارة",              type:"opt4" },
      { id:"r7",  label:"أُساعد الزملاء الجدد وأتشارك معهم الخبرات",        type:"opt4" },
    ]},
  ];

  const ALL_OPT4 = SECTIONS.flatMap(s => s.fields.filter(f => f.type === "opt4"));
  const globalPct = (data) => {
    const total = ALL_OPT4.reduce((s,f) => s + (OPT4_VAL[data[f.id]] || 0), 0);
    const max   = ALL_OPT4.length * 4;
    return max > 0 ? Math.round((total/max)*100) : 0;
  };
  const levelInfo = (pct) => {
    if (pct >= 85) return { label:"ممتاز",     emoji:"🌟", color:"#059669", bg:"#d1fae5" };
    if (pct >= 70) return { label:"جيد جداً",  emoji:"👍", color:"#0d9488", bg:"#ccfbf1" };
    if (pct >= 55) return { label:"جيد",        emoji:"👌", color:"#d97706", bg:"#fef3c7" };
    if (pct >= 40) return { label:"مقبول",      emoji:"📌", color:"#f97316", bg:"#ffedd5" };
    return              { label:"يحتاج دعماً", emoji:"🆘", color:"#dc2626", bg:"#fee2e2" };
  };

  // تحقق إذا كان المعلم أرسل مسبقاً
  const existing = loadLS().find(r => r.teacherId === teacherInfo.id);

  const [step,     setStep]     = useState(0);
  const [formData, setFormData] = useState(existing?.data || {});
  const [done,     setDone]     = useState(false);
  const [savedRec, setSavedRec] = useState(null);

  const sec    = SECTIONS[step];
  const isLast = step === SECTIONS.length - 1;

  const submitEval = () => {
    const pct = globalPct(formData);
    const rec = {
      id: teacherInfo.id + "_" + Date.now(),
      teacherId:   teacherInfo.id,
      teacherName: teacherInfo.name,
      subject:     formData.subject || "—",
      date: new Date().toLocaleDateString("ar-SA-u-nu-latn",{year:"numeric",month:"2-digit",day:"2-digit"}),
      pct, data: formData,
    };
    const all = loadLS().filter(r => r.teacherId !== teacherInfo.id);
    saveLS([rec, ...all]);
    setSavedRec(rec);
    setDone(true);
  };

  /* ── شاشة شكر ── */
  if (done && savedRec) {
    const pct = savedRec.pct;
    const lvl = levelInfo(pct);
    return (
      <div dir="rtl" style={{ fontFamily:"'Cairo','Noto Naskh Arabic',sans-serif", padding:16 }}>
        <div style={{ background:`linear-gradient(135deg,${lvl.color},${lvl.color}99)`,
          borderRadius:24, padding:28, textAlign:"center", color:"#fff", marginBottom:16 }}>
          <div style={{ fontSize:60, marginBottom:12 }}>✅</div>
          <div style={{ fontWeight:900, fontSize:20, marginBottom:6 }}>تم إرسال تقييمك بنجاح!</div>
          <div style={{ opacity:.8, fontSize:13 }}>سيطّلع عليه المدير ويتواصل معك</div>
          <div style={{ fontSize:52, fontWeight:900, margin:"16px 0 4px" }}>{pct}%</div>
          <div style={{ background:"rgba(255,255,255,0.2)", borderRadius:20, padding:"4px 16px",
                        display:"inline-block", fontWeight:800, fontSize:14 }}>{lvl.emoji} {lvl.label}</div>
        </div>
        <div style={{ background:"#fff", borderRadius:16, padding:16,
          boxShadow:"0 2px 12px rgba(0,0,0,0.06)", border:"1px solid #f1f5f9" }}>
          <div style={{ fontWeight:800, fontSize:13, color:"#374151", marginBottom:10 }}>نتائجك في المحاور</div>
          {SECTIONS.map(s => {
            const scored = s.fields.filter(f=>f.type==="opt4");
            const total  = scored.reduce((x,f)=>x+(OPT4_VAL[formData[f.id]]||0),0);
            const spct   = scored.length>0?Math.round((total/(scored.length*4))*100):0;
            return (
              <div key={s.id} style={{ marginBottom:8 }}>
                <div style={{ display:"flex", justifyContent:"space-between", fontSize:12,
                              fontWeight:700, color:s.color, marginBottom:3 }}>
                  <span>{s.icon} {s.title}</span><span>{spct}%</span>
                </div>
                <div style={{ background:"#f1f5f9", borderRadius:99, height:8, overflow:"hidden" }}>
                  <div style={{ width:spct+"%", height:"100%", borderRadius:99, background:s.color }} />
                </div>
              </div>
            );
          })}
        </div>
        <button onClick={onDone}
          style={{ width:"100%", marginTop:14, padding:"13px", borderRadius:14, border:"none",
                   background:"linear-gradient(135deg,#1e3a5f,#2563eb)",
                   color:"#fff", fontWeight:900, fontSize:14, cursor:"pointer",
                   fontFamily:"'Cairo',sans-serif" }}>
          ← العودة للبوابة
        </button>
      </div>
    );
  }

  /* ── النموذج ── */
  const BtnOpt = ({ fId, opt }) => {
    const clrs = {"دائماً":"#059669","غالباً":"#0d9488","أحياناً":"#d97706","لا":"#dc2626","نعم":"#059669"};
    const active = formData[fId] === opt;
    const c = clrs[opt] || "#7c3aed";
    return (
      <button onClick={() => setFormData(p=>({...p,[fId]:opt}))} style={{
        flex:1, padding:"9px 4px", borderRadius:10, border:`2px solid ${active?c:"#e2e8f0"}`,
        background:active?c:"#f9fafb", color:active?"#fff":"#6b7280",
        fontWeight:800, fontSize:11, cursor:"pointer", fontFamily:"'Cairo',sans-serif",
        boxShadow:active?`0 3px 10px ${c}44`:"none", transition:"all .15s",
      }}>{opt}</button>
    );
  };

  return (
    <div dir="rtl" style={{ fontFamily:"'Cairo','Noto Naskh Arabic',sans-serif" }}>
      {/* رأس */}
      <div style={{ background:`linear-gradient(135deg,${sec.color},${sec.color}cc)`,
        borderRadius:20, padding:"16px 18px 12px", marginBottom:14, color:"#fff" }}>
        <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:10 }}>
          <div style={{ display:"flex", alignItems:"center", gap:10 }}>
            <div style={{ width:34, height:34, borderRadius:12, background:"rgba(255,255,255,0.2)",
              display:"flex", alignItems:"center", justifyContent:"center", fontSize:18 }}>{sec.icon}</div>
            <div>
              <div style={{ fontWeight:900, fontSize:14 }}>{sec.title}</div>
              <div style={{ opacity:.75, fontSize:10 }}>المحور {step+1} من {SECTIONS.length}</div>
            </div>
          </div>
          <div style={{ fontWeight:900, fontSize:16 }}>{Math.round(((step+1)/SECTIONS.length)*100)}%</div>
        </div>
        <div style={{ display:"flex", gap:3 }}>
          {SECTIONS.map((_,i) => (
            <div key={i} style={{ flex:1, height:5, borderRadius:99,
              background:i<=step?"rgba(255,255,255,0.9)":"rgba(255,255,255,0.25)" }} />
          ))}
        </div>
      </div>

      {/* إشعار إذا أرسل مسبقاً */}
      {existing && (
        <div style={{ background:"#fef3c7", border:"1.5px solid #fde68a", borderRadius:12,
          padding:"8px 14px", marginBottom:12, fontSize:11, fontWeight:700, color:"#92400e" }}>
          ⚠️ سبق وأرسلت تقييماً بتاريخ {existing.date} — يمكنك التعديل وإعادة الإرسال
        </div>
      )}

      {/* الأسئلة */}
      <div style={{ display:"flex", flexDirection:"column", gap:10, marginBottom:80 }}>
        {sec.fields.map(f => (
          <div key={f.id} style={{ background:"#fff", borderRadius:14, padding:"14px 14px",
            boxShadow:"0 2px 10px rgba(0,0,0,0.05)", border:"1px solid #f1f5f9" }}>
            <div style={{ fontSize:13, fontWeight:700, color:"#374151", marginBottom:10, lineHeight:1.5 }}>
              {f.cause && <span style={{ background:"#fee2e2", color:"#dc2626", fontSize:9.5,
                borderRadius:6, padding:"1px 6px", marginLeft:5, fontWeight:800 }}>سبب</span>}
              {f.label}
            </div>
            {f.type === "text" ? (
              <input type="text" value={formData[f.id]||""} placeholder={f.placeholder||""}
                onChange={e=>setFormData(p=>({...p,[f.id]:e.target.value}))}
                style={{ width:"100%", padding:"9px 12px", borderRadius:10, border:"2px solid #e2e8f0",
                         fontSize:13, fontFamily:"'Cairo',sans-serif", outline:"none", boxSizing:"border-box" }} />
            ) : f.type === "select" ? (
              <select value={formData[f.id]||""} onChange={e=>setFormData(p=>({...p,[f.id]:e.target.value}))}
                style={{ width:"100%", padding:"9px 12px", borderRadius:10, border:"2px solid #e2e8f0",
                         fontSize:13, fontFamily:"'Cairo',sans-serif", outline:"none", background:"#fff",
                         color:formData[f.id]?"#1f2937":"#9ca3af" }}>
                <option value="">— اختر —</option>
                {(f.options||[]).map(o=><option key={o} value={o}>{o}</option>)}
              </select>
            ) : f.type === "opyn" ? (
              <div style={{ display:"flex", gap:8 }}>
                {OPT_YN.map(o=><BtnOpt key={o} fId={f.id} opt={o} />)}
              </div>
            ) : (
              <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 1fr 1fr", gap:6 }}>
                {OPT4.map(o=><BtnOpt key={o} fId={f.id} opt={o} />)}
              </div>
            )}
          </div>
        ))}
      </div>

      {/* أزرار ثابتة أسفل */}
      <div style={{ position:"sticky", bottom:0, background:"#fff", borderTop:"1px solid #e2e8f0",
        padding:"10px 12px", display:"flex", gap:8, boxShadow:"0 -4px 16px rgba(0,0,0,0.08)",
        zIndex:50, fontFamily:"'Cairo',sans-serif" }}>
        {step > 0 && (
          <button onClick={() => setStep(s=>s-1)} style={{
            padding:"11px 18px", borderRadius:12, border:"1.5px solid #e2e8f0",
            background:"#f8fafc", color:"#64748b", fontWeight:700, fontSize:13, cursor:"pointer" }}>
            ← السابق
          </button>
        )}
        {!isLast ? (
          <button onClick={() => setStep(s=>s+1)} style={{
            flex:1, padding:"11px", borderRadius:12, border:"none",
            background:`linear-gradient(135deg,${sec.color},${sec.color}cc)`,
            color:"#fff", fontWeight:900, fontSize:14, cursor:"pointer",
            boxShadow:`0 4px 14px ${sec.color}44` }}>
            التالي ← {SECTIONS[step+1]?.icon}
          </button>
        ) : (
          <button onClick={submitEval} style={{
            flex:1, padding:"11px", borderRadius:12, border:"none",
            background:"linear-gradient(135deg,#7c3aed,#5b21b6)",
            color:"#fff", fontWeight:900, fontSize:14, cursor:"pointer",
            boxShadow:"0 4px 14px rgba(124,58,237,0.4)" }}>
            🎯 إرسال التقييم
          </button>
        )}
      </div>
    </div>
  );
}

