const HIJRI_MONTHS_ASS = ["محرم","صفر","ربيع الأول","ربيع الآخر","جمادى الأولى","جمادى الآخرة","رجب","شعبان","رمضان","شوال","ذو القعدة","ذو الحجة"];
const HIJRI_YEARS_ASS  = Array.from({length:7},(_,i)=>1447+i); // 1447-1453 (covers to 2031)
const GREGORIAN_MONTHS_ASS = ["يناير","فبراير","مارس","أبريل","مايو","يونيو","يوليو","أغسطس","سبتمبر","أكتوبر","نوفمبر","ديسمبر"];
const GREGORIAN_YEARS_ASS  = Array.from({length:4},(_,i)=>2025+i); // 2025-2028

const emptyForm = () => ({
  visitDate:"", subject:"", grade:"", lesson:"", period:"",
  studentCount:"", presentCount:"", absentCount:"",
  visitNum:"1", visitPurpose:"", visitType:"حضوري", isNew:"لا",
  hijriDay:"", hijriMonth:"", hijriYear:"1447",
  gregDay:"", gregMonth:"", gregYear:"2025",
  methods:[], methodsOther:"", visitGoals:[],
  principalName:"فازع عبدالله حسن القرني",
  supervisorName:"",
  scores: Object.fromEntries(
    EVAL_SECTIONS.flatMap(s => s.fields.map(f => [f, 0]))
  ),
  prevRecs:"", strengths:"", support:"", recommendations:"", benefitFrom:"",
  performanceNote:"", needs: Array(6).fill(null).map(() => ({need:"", program:""})),
});

function AssessmentPage({ teachers: appTeachers = [] }) {
  const [view,          setView]          = useState("home"); // home | form | detail
  const [selectedTeacher, setSelectedTeacher] = useState(null);
  const [form,          setForm]          = useState(emptyForm());
  const [assessments,   setAssessments]   = useState({});  // { teacherId: [rec, ...] }
  const [filter,        setFilter]        = useState("all");
  const [search,        setSearch]        = useState("");
  const [saving,        setSaving]        = useState(false);
  const [saved,         setSaved]         = useState(false);
  const [detailRec,     setDetailRec]     = useState(null);

  useEffect(() => {
    DB.get("school-assessments", {}).then(data => {
      if (data && typeof data === "object") setAssessments(data);
    });
  }, []);

  const saveAssessments = (data) => {
    setAssessments(data);
    DB.set("school-assessments", data);
  };

  const getVisitCount = (tid) => (assessments[tid] || []).length;
  const hasVisit = (tid) => getVisitCount(tid) > 0;

  const totalVisited = ASSESSMENT_TEACHERS.filter(t => hasVisit(t.id)).length;

  const setScore = (field, val) => setForm(f => ({...f, scores:{...f.scores,[field]:val}}));
  const calcSectionScore = (fields) => {
    const vals = fields.map(f => form.scores[f] || 0).filter(v => v > 0);
    return vals.length ? Math.round(vals.reduce((a,b)=>a+b,0)/vals.length*10)/10 : 0;
  };
  const totalScore = () => {
    const allFields = EVAL_SECTIONS.flatMap(s=>s.fields);
    const vals = allFields.map(f => form.scores[f]||0).filter(v=>v>0);
    return vals.length ? Math.round(vals.reduce((a,b)=>a+b,0)/vals.length*10)/10 : 0;
  };
  const scoreColor = (s) => s>=4?"#1a6b3c":s>=3?"#9a7230":s>=2?"#e67e22":"#8b1a1a";
  const scoreLabel = (s) => s>=4.5?"ممتاز":s>=3.5?"جيد جداً":s>=2.5?"جيد":s>=1.5?"مقبول":"يحتاج دعم";

  const handleSave = async () => {
    if (!selectedTeacher) return;
    setSaving(true);
    const rec = {
      id: Date.now(),
      teacherId: selectedTeacher.id,
      teacherName: selectedTeacher.name,
      teacherMobile: selectedTeacher.mobile,
      savedAt: new Date().toLocaleDateString("ar-SA"),
      ...form,
      totalScore: totalScore(),
    };
    const updated = {
      ...assessments,
      [selectedTeacher.id]: [...(assessments[selectedTeacher.id]||[]), rec]
    };
    saveAssessments(updated);
    setSaving(false); setSaved(true);
    setTimeout(() => setSaved(false), 2500);
  };

  const handlePrint = () => {
    if (!selectedTeacher) return;
    const fmtHijri = [form.hijriDay, form.hijriMonth, form.hijriYear].filter(Boolean).join(" / ") + (form.hijriYear?" هـ":"");
    const fmtGreg  = [form.gregDay, form.gregMonth, form.gregYear].filter(Boolean).join(" / ") + (form.gregYear?" م":"");

    const scoreRows = EVAL_SECTIONS.map(sec => {
      const avg = (() => {
        const vals = sec.fields.map(f=>form.scores[f]||0).filter(v=>v>0);
        return vals.length ? Math.round(vals.reduce((a,b)=>a+b,0)/vals.length*10)/10 : 0;
      })();
      const avgColor = avg>=4?"#1a6b3c":avg>=3?"#9a7230":avg>=2?"#e67e22":"#8b1a1a";
      const itemRows = sec.items.map((item,j)=>{
        const sc = form.scores[sec.fields[j]]||0;
        const c = sc>=4?"#1a6b3c":sc>=3?"#9a7230":sc>=2?"#e67e22":sc>=1?"#8b1a1a":"#aaa";
        return `<tr>
          <td style="text-align:right;padding:7px 12px;font-size:11.5px;color:#1a2d3e;border:1px solid #dce6f0">${item}</td>
          ${[1,2,3,4,5].map(n=>`<td style="text-align:center;padding:7px;font-size:13px;background:${sc===n?sec.color:"#fff"};color:${sc===n?"#fff":"#ccc"};border:1px solid #dce6f0;font-weight:900">${sc===n?"●":"○"}</td>`).join("")}
          <td style="text-align:center;padding:7px;font-weight:900;font-size:14px;color:${c};border:1px solid #dce6f0">${sc||"—"}</td>
        </tr>`;
      }).join("");
      return `
        <tr>
          <td colspan="7" style="padding:9px 14px;background:${sec.color};color:#fff;font-weight:900;font-size:12.5px;border:none">${sec.title}</td>
        </tr>
        ${itemRows}
        <tr style="background:#f5f9ff">
          <td style="text-align:right;padding:5px 12px;font-size:10px;color:#5a7080;font-style:italic;border:1px solid #dce6f0">متوسط المحور</td>
          <td colspan="5" style="border:1px solid #dce6f0"></td>
          <td style="text-align:center;padding:5px;font-weight:900;font-size:14px;color:${avgColor};border:1px solid #dce6f0">${avg||"—"}</td>
        </tr>`;
    }).join("");

    const goals = (form.visitGoals||[]).map(g=>`<span style="display:inline-block;background:#e8f8f8;border:1px solid #0e7c7b;color:#0a4d3c;padding:3px 10px;border-radius:5px;font-size:10.5px;margin:2px 3px">${g}</span>`).join("");

    printWindow(`<!DOCTYPE html><html dir="rtl" lang="ar"><head><meta charset="utf-8">
    <title>بطاقة تشخيص قياس التحصيل — ${selectedTeacher.name}</title>
    <style>
    @import url('https://fonts.googleapis.com/css2?family=Tajawal:wght@400;500;700;800;900&display=swap');
    *{margin:0;padding:0;box-sizing:border-box}
    body{font-family:'Tajawal',Arial,sans-serif;direction:rtl;background:#fff;color:#1a2d3e;-webkit-print-color-adjust:exact;print-color-adjust:exact}
    .page{width:210mm;min-height:297mm;margin:0 auto;padding:12mm 14mm 14mm;background:#fff}
    .hdr{background:linear-gradient(135deg,#071e34 0%,#0a3d5c 55%,#0e6d6b 100%);color:#fff;
         padding:16px 22px;border-radius:10px;margin-bottom:14px;
         display:grid;grid-template-columns:50px 1fr 150px;align-items:center;gap:14px}
    .hdr-logo{font-size:40px;opacity:.85;text-align:center}
    .hdr-center{text-align:center}
    .hdr h1{font-size:18px;font-weight:900;margin-bottom:4px}
    .hdr p{font-size:11px;opacity:.8}
    .hdr-dates{text-align:left;line-height:2.2}
    .hdr-dates div{font-size:11px;display:flex;gap:4px;align-items:center}
    .hdr-dates .lbl{opacity:.7;font-size:10px}
    .hdr-dates .val{font-weight:900;font-size:12px}
    .info-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:7px;margin-bottom:12px}
    .info-item{background:#f3f7fb;border-radius:7px;padding:7px 10px;border:1px solid #dce6f0}
    .info-item label{display:block;font-size:9px;color:#6a86a0;margin-bottom:2px;font-weight:700;text-transform:uppercase;letter-spacing:.3px}
    .info-item span{font-size:12.5px;font-weight:800;color:#1a2d3e}
    .goals-box{background:#f0fcfa;border:1px solid #9fd8d3;border-radius:8px;padding:10px 14px;margin-bottom:12px}
    .goals-title{font-size:11px;font-weight:900;color:#0a4d3c;margin-bottom:7px}
    table{width:100%;border-collapse:collapse;margin-bottom:12px;font-size:11.5px}
    .tbl-head th{background:#0a3d5c;color:#fff;padding:9px 10px;text-align:center;font-weight:800;font-size:11.5px}
    .tbl-head th:first-child{text-align:right;width:44%}
    .score-total{display:flex;align-items:center;justify-content:center;gap:30px;
                 background:linear-gradient(135deg,#071e34,#0a3d5c 50%,#0e7c7b);color:#fff;
                 border-radius:10px;margin:12px 0;padding:16px 24px}
    .score-big{font-size:46px;font-weight:900;line-height:1}
    .score-label{font-size:14px;background:rgba(255,255,255,.2);padding:4px 16px;border-radius:20px;margin-top:5px;display:inline-block}
    .obs{background:#f9fbfd;border:1px solid #dce6f0;border-radius:8px;padding:10px 14px;margin-bottom:9px}
    .obs-lbl{font-size:11px;font-weight:900;color:#0a3d5c;margin-bottom:5px}
    .obs-val{font-size:11.5px;color:#1a2d3e;min-height:28px;line-height:1.8;white-space:pre-wrap}
    .needs-tbl{width:100%;border-collapse:collapse;margin-bottom:14px;font-size:11.5px}
    .needs-tbl th{background:#4a2080;color:#fff;padding:8px 12px;font-weight:800;border:1px solid #c9b8e8}
    .needs-tbl td{border:1px solid #dce6f0;padding:9px 12px;background:#fff}
    .needs-tbl tr:nth-child(even) td{background:#faf8ff}
    .sigs{display:grid;grid-template-columns:1fr 1fr 1fr;gap:24px;margin-top:22px}
    .sig{text-align:center}
    .sig-space{height:50px;border-bottom:2px dashed #9ab0c8;margin-bottom:10px}
    .sig-name{font-weight:900;color:#0a3d5c;font-size:13px;margin-top:5px}
    .sig-title{font-size:11px;color:#6a86a0;margin-top:4px;font-weight:700}
    @media print{
      @page{size:A4;margin:0}
      body{-webkit-print-color-adjust:exact;print-color-adjust:exact}
      .page{padding:8mm 12mm 12mm}
    }
    </style></head><body>
    <div class="page">

      <div class="hdr">
        <div class="hdr-logo">📊</div>
        <div class="hdr-center">
          <h1>بطاقة تشخيص قياس التحصيل الدراسي</h1>
          <p>مدرسة الأمير عبدالمجيد المتوسطة الأولى — إدارة تعليم جدة</p>
        </div>
        <div class="hdr-dates">
          <div><span class="lbl">هجري:</span> <span class="val">${fmtHijri||"—"}</span></div>
          <div><span class="lbl">ميلادي:</span> <span class="val">${fmtGreg||"—"}</span></div>
        </div>
      </div>

      <div class="info-grid">
        <div class="info-item"><label>اسم المعلم</label><span>${selectedTeacher.name}</span></div>
        <div class="info-item"><label>المادة</label><span>${form.subject||"—"}</span></div>
        <div class="info-item"><label>الصف والفصل</label><span>${form.grade||"—"}</span></div>
        <div class="info-item"><label>عنوان الدرس</label><span>${form.lesson||"—"}</span></div>
        <div class="info-item"><label>الحصة</label><span>${form.period?"الحصة "+form.period:"—"}</span></div>
        <div class="info-item"><label>عدد الطلاب</label><span>${form.studentCount||"—"}</span></div>
        <div class="info-item"><label>الحاضرون</label><span>${form.presentCount||"—"}</span></div>
        <div class="info-item"><label>الغائبون</label><span>${form.absentCount||"—"}</span></div>
        <div class="info-item"><label>نوع الزيارة</label><span>${form.visitType||"—"}</span></div>
        <div class="info-item"><label>رقم الزيارة</label><span>${form.visitNum||"—"}</span></div>
        <div class="info-item"><label>هل المعلم جديد؟</label><span>${form.isNew||"—"}</span></div>
        <div class="info-item"><label>الغرض من الزيارة</label><span>${form.visitPurpose||"—"}</span></div>
      </div>

      ${goals?`<div class="goals-box"><div class="goals-title">🎯 الأساليب التي اتبعها المشرف للتعرف على المستوى</div>${goals}${form.methodsOther?`<div style="font-size:10.5px;margin-top:6px;color:#5a7080">أخرى: ${form.methodsOther}</div>`:""}</div>`:""}

      <table>
        <thead class="tbl-head">
          <tr>
            <th>عنصر التقييم</th>
            <th>1</th><th>2</th><th>3</th><th>4</th><th>5</th>
            <th>الدرجة</th>
          </tr>
        </thead>
        <tbody>${scoreRows}</tbody>
      </table>

      <div class="score-total">
        <div style="text-align:center">
          <div style="font-size:13px;opacity:.8;margin-bottom:4px">الدرجة الكلية للزيارة</div>
          <div class="score-big">${totalScore()||"—"}</div>
          <div class="score-label">${scoreLabel(totalScore())}</div>
        </div>
        <div style="font-size:11px;opacity:.75;text-align:right;line-height:2.1">
          <div>ممتاز ≥ 4.5</div>
          <div>جيد جداً ≥ 3.5</div>
          <div>جيد ≥ 2.5</div>
          <div>مقبول ≥ 1.5</div>
          <div>يحتاج دعم &lt; 1.5</div>
        </div>
      </div>

      ${form.performanceNote?`<div class="obs"><div class="obs-lbl">📝 ملاحظة</div><div class="obs-val">${form.performanceNote}</div></div>`:""}
      ${form.benefitFrom?`<div class="obs"><div class="obs-lbl">🎓 يستفاد من المعلم في</div><div class="obs-val">${form.benefitFrom}</div></div>`:""}
      ${form.recommendations?`<div class="obs"><div class="obs-lbl">📋 التوصيات</div><div class="obs-val">${form.recommendations}</div></div>`:""}

      ${form.needs&&form.needs.some(n=>n.need||n.program)?`
      <table class="needs-tbl">
        <thead><tr><th style="text-align:center;width:36px">#</th><th style="text-align:right">الاحتياج التدريبي</th><th style="text-align:right">البرنامج المقترح للمتابعة / للتطوير</th></tr></thead>
        <tbody>${form.needs.filter(n=>n.need||n.program).map((n,i)=>`<tr><td style="text-align:center;font-weight:800;font-size:12px">${i+1}</td><td>${n.need||""}</td><td>${n.program||""}</td></tr>`).join("")}</tbody>
      </table>`:""}

      <div class="sigs">
        <div class="sig">
          <div class="sig-space"></div>
          <div class="sig-name">${selectedTeacher.name}</div>
          <div class="sig-title">المعلم</div>
        </div>
        <div class="sig">
          <div class="sig-space"></div>
          <div class="sig-name">${form.principalName||"فازع عبدالله حسن القرني"}</div>
          <div class="sig-title">${form.principalName==="أمين الحنيطي"?"وكيل المدرسة":"مدير المدرسة"}</div>
        </div>
        <div class="sig">
          <div class="sig-space"></div>
          <div class="sig-name">${form.supervisorName||""}</div>
          <div class="sig-title">المشرف التربوي</div>
        </div>
      </div>

    </div>
    <script>window.onload=()=>window.print()</script></body></html>`);
  };

  const filteredTeachers = ASSESSMENT_TEACHERS.filter(t => {
    if (search && !t.name.includes(search)) return false;
    if (filter === "visited") return hasVisit(t.id);
    if (filter === "pending") return !hasVisit(t.id);
    return true;
  });

  /* ══ شاشة تفاصيل زيارة سابقة ══ */
  if (view === "detail" && detailRec) {
    const ts = totalScore();
    return (
      <div dir="rtl" style={{ fontFamily:"'Tajawal','Cairo',sans-serif" }}>
        <div style={{ display:"flex", alignItems:"center", gap:12, padding:"12px 16px",
          background:"#fff", borderBottom:"1px solid #d0dbe8", flexWrap:"wrap" }}>
          <button onClick={() => { setView("home"); setDetailRec(null); }}
            style={{ padding:"7px 14px", borderRadius:8, border:"1.5px solid #d0dbe8",
                     fontSize:13, fontWeight:700, cursor:"pointer", background:"#f0f4f8", color:"#5a7080" }}>
            → العودة
          </button>
          <div style={{ flex:1, fontWeight:700, color:"#0a3d5c", fontSize:14 }}>
            {detailRec.teacherName} — {detailRec.visitDate||detailRec.savedAt}
          </div>
        </div>
        <div style={{ maxWidth:860, margin:"0 auto", padding:"16px 14px 60px" }}>
          <div style={{ background:"linear-gradient(135deg,#071e34,#0a3d5c,#0e6d6b)", borderRadius:14,
            padding:"20px 24px", color:"#fff", marginBottom:16, textAlign:"center" }}>
            <div style={{ fontSize:11, opacity:.7, marginBottom:4 }}>{detailRec.teacherName}</div>
            <div style={{ fontSize:48, fontWeight:900 }}>{detailRec.totalScore||"—"}</div>
            <div style={{ fontSize:14, marginTop:4 }}>{scoreLabel(detailRec.totalScore||0)}</div>
          </div>
          {EVAL_SECTIONS.map(sec => {
            const vals = sec.fields.map(f=>detailRec.scores?.[f]||0).filter(v=>v>0);
            const avg = vals.length?Math.round(vals.reduce((a,b)=>a+b,0)/vals.length*10)/10:0;
            return (
              <div key={sec.id} style={{ background:"#fff", borderRadius:12, marginBottom:10,
                border:"1px solid #d0dbe8", overflow:"hidden" }}>
                <div style={{ background:sec.color, padding:"10px 14px", display:"flex",
                  justifyContent:"space-between", alignItems:"center" }}>
                  <span style={{ color:"#fff", fontWeight:800, fontSize:13 }}>{sec.title}</span>
                  <span style={{ background:"rgba(255,255,255,0.2)", color:"#fff", borderRadius:20,
                    padding:"2px 12px", fontWeight:900, fontSize:13 }}>{avg||"—"}/5</span>
                </div>
                <div style={{ padding:"10px 14px", display:"flex", flexWrap:"wrap", gap:8 }}>
                  {sec.items.map((item,j) => {
                    const val = detailRec.scores?.[sec.fields[j]]||0;
                    return (
                      <div key={j} style={{ display:"flex", alignItems:"center", gap:8, flex:"1 1 200px" }}>
                        <span style={{ fontSize:11, color:"#5a7080", flex:1 }}>{item}</span>
                        <span style={{ fontWeight:900, fontSize:14, color:scoreColor(val) }}>{val||"—"}</span>
                      </div>
                    );
                  })}
                </div>
              </div>
            );
          })}
          {[{l:"نقاط القوة",v:detailRec.strengths},{l:"جوانب تحتاج دعماً",v:detailRec.support},{l:"التوصيات",v:detailRec.recommendations}]
            .filter(x=>x.v).map(x=>(
            <div key={x.l} style={{ background:"#fff", borderRadius:12, padding:14, marginBottom:10,
              border:"1px solid #d0dbe8" }}>
              <div style={{ fontWeight:800, color:"#0a3d5c", fontSize:13, marginBottom:6 }}>{x.l}</div>
              <div style={{ fontSize:13, color:"#1a2d3e", lineHeight:1.8 }}>{x.v}</div>
            </div>
          ))}
        </div>
      </div>
    );
  }

  /* ══ نموذج التقييم ══ */
  if (view === "form" && selectedTeacher) {
    const ScoreRow = ({ item, field, cls }) => (
      <tr style={{ background: cls%2===0?"#f9fbfd":"#fff" }}>
        <td style={{ padding:"10px 12px", fontSize:12, fontWeight:500, color:"#1a2d3e", textAlign:"right" }}>{item}</td>
        {[1,2,3,4,5].map(n => (
          <td key={n} style={{ textAlign:"center", padding:"8px 4px" }}>
            <label style={{ cursor:"pointer" }}>
              <input type="radio" name={field} value={n} checked={form.scores[field]===n}
                onChange={()=>setScore(field,n)} style={{ display:"none" }} />
              <div style={{
                width:28, height:28, borderRadius:"50%", margin:"0 auto",
                display:"flex", alignItems:"center", justifyContent:"center",
                border:"2px solid", cursor:"pointer", fontSize:11, fontWeight:700, transition:"all .15s",
                borderColor: form.scores[field]===n
                  ? (n===1?"#c0392b":n===2?"#e67e22":n===3?"#d4ac0d":n===4?"#27ae60":"#0a3d5c")
                  : "#d0dbe8",
                background: form.scores[field]===n
                  ? (n===1?"#c0392b":n===2?"#e67e22":n===3?"#d4ac0d":n===4?"#27ae60":"#0a3d5c")
                  : "#fafcff",
                color: form.scores[field]===n ? "#fff" : "#5a7080",
              }} onClick={()=>setScore(field,n)}>{n}</div>
            </label>
          </td>
        ))}
        <td style={{ textAlign:"center", padding:"8px 6px" }}>
          <span style={{ fontWeight:900, fontSize:13, color:scoreColor(form.scores[field]||0) }}>
            {form.scores[field]||"—"}
          </span>
        </td>
      </tr>
    );

    const SectionCard = ({ sec }) => {
      const avg = calcSectionScore(sec.fields);
      return (
        <div style={{ background:"#fff", borderRadius:12, marginBottom:14,
          border:"1px solid #d0dbe8", overflow:"hidden", boxShadow:"0 2px 12px rgba(10,61,92,0.07)" }}>
          <div style={{ background:sec.color, padding:"11px 16px", display:"flex",
            alignItems:"center", justifyContent:"space-between" }}>
            <span style={{ color:"#fff", fontWeight:800, fontSize:14 }}>{sec.title}</span>
            {avg>0&&<span style={{ background:"rgba(255,255,255,0.2)", color:"#fff", borderRadius:20,
              padding:"2px 12px", fontWeight:900, fontSize:13 }}>المتوسط: {avg}</span>}
          </div>
          <div style={{ overflowX:"auto" }}>
            <table style={{ width:"100%", borderCollapse:"collapse", fontSize:12 }}>
              <thead>
                <tr style={{ background:"#f0f5fa" }}>
                  <th style={{ padding:"8px 12px", textAlign:"right", color:"#0a3d5c", fontWeight:700, borderBottom:"2px solid #d0dbe8" }}>المعيار</th>
                  {[1,2,3,4,5].map(n=><th key={n} style={{ padding:"8px 6px", textAlign:"center", color:scoreColor(n), fontWeight:900, borderBottom:"2px solid #d0dbe8" }}>{n}</th>)}
                  <th style={{ padding:"8px 6px", textAlign:"center", color:"#0a3d5c", fontWeight:700, borderBottom:"2px solid #d0dbe8" }}>الدرجة</th>
                </tr>
              </thead>
              <tbody>
                {sec.items.map((item,j)=>(
                  <ScoreRow key={j} item={item} field={sec.fields[j]} cls={j} />
                ))}
              </tbody>
            </table>
          </div>
        </div>
      );
    };

    const F = ({label, id, type="text", placeholder="", value, onChange, children}) => (
      <div style={{ display:"flex", flexDirection:"column", gap:4 }}>
        <label style={{ fontSize:11, fontWeight:700, color:"#5a7080" }}>{label}</label>
        {children || (
          <input type={type} value={value} onChange={onChange} placeholder={placeholder}
            style={{ padding:"8px 10px", border:"1.5px solid #d0dbe8", borderRadius:8,
                     fontFamily:"'Tajawal',sans-serif", fontSize:13, color:"#1a2d3e",
                     background:"#f9fbfd", direction:"rtl", outline:"none" }} />
        )}
      </div>
    );

    const RadioGroup = ({name, options, value, onChange}) => (
      <div style={{ display:"flex", gap:8 }}>
        {options.map(opt=>(
          <label key={opt} style={{ display:"flex", alignItems:"center", gap:7, padding:"7px 14px",
            border:`2px solid ${value===opt?"#0e7c7b":"#d0dbe8"}`,
            borderRadius:8, cursor:"pointer", fontSize:12, fontWeight:value===opt?700:400,
            background:value===opt?"#e8f8f8":"#fafcff", color:value===opt?"#0e7c7b":"#5a7080" }}>
            <input type="radio" name={name} value={opt} checked={value===opt}
              onChange={()=>onChange(opt)} style={{ display:"none" }} />
            {opt}
          </label>
        ))}
      </div>
    );

    return (
      <div dir="rtl" style={{ fontFamily:"'Tajawal','Cairo',sans-serif", background:"#f0f4f8", minHeight:"100vh" }}>
        {/* رأس النموذج */}
        <div style={{ background:"#fff", borderBottom:"1px solid #d0dbe8", padding:"12px 16px",
          display:"flex", alignItems:"center", gap:12, flexWrap:"wrap",
          position:"sticky", top:0, zIndex:50, boxShadow:"0 2px 8px rgba(10,61,92,0.08)" }}>
          <button onClick={() => setView("home")}
            style={{ padding:"7px 14px", borderRadius:8, border:"1.5px solid #d0dbe8",
                     fontSize:13, fontWeight:700, cursor:"pointer", background:"#f0f4f8", color:"#5a7080" }}>
            → العودة
          </button>
          <div style={{ flex:1, fontWeight:700, color:"#0a3d5c", fontSize:14 }}>
            {selectedTeacher.name}
          </div>
          <button onClick={handlePrint}
            style={{ padding:"8px 14px", borderRadius:8, border:"1.5px solid #d0dbe8",
                     fontSize:12, fontWeight:700, cursor:"pointer", background:"#f0f4f8", color:"#5a7080" }}>
            🖨️ طباعة
          </button>
          <button onClick={handleSave} disabled={saving}
            style={{ padding:"8px 18px", borderRadius:8, border:"none",
                     background:saving?"#aaa":"linear-gradient(135deg,#0e7c7b,#0a3d5c)",
                     color:"#fff", fontSize:13, fontWeight:700, cursor:saving?"not-allowed":"pointer",
                     fontFamily:"'Tajawal',sans-serif" }}>
            {saving?"⏳ جارٍ الحفظ...":saved?"✅ تم الحفظ":"💾 حفظ البطاقة"}
          </button>
        </div>

        <div style={{ maxWidth:900, margin:"0 auto", padding:"16px 14px 60px" }}>

          {/* التاريخ الهجري والميلادي */}
          <div style={{ background:"linear-gradient(135deg,#071e34,#0a3d5c,#0e6d6b)", borderRadius:12,
            marginBottom:14, padding:"16px 20px" }}>
            <div style={{ display:"flex", alignItems:"center", gap:10, marginBottom:14 }}>
              <div style={{ fontSize:22 }}>📅</div>
              <span style={{ color:"#fff", fontWeight:800, fontSize:15 }}>تاريخ الزيارة</span>
            </div>
            <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:16 }}>
              {/* هجري */}
              <div>
                <div style={{ fontSize:11, color:"rgba(255,255,255,0.75)", fontWeight:700, marginBottom:6 }}>التاريخ الهجري</div>
                <div style={{ display:"grid", gridTemplateColumns:"1fr 2fr 1fr", gap:6 }}>
                  {[
                    { label:"اليوم", val:form.hijriDay, key:"hijriDay",
                      opts:["",...Array.from({length:30},(_,i)=>String(i+1))] },
                    { label:"الشهر", val:form.hijriMonth, key:"hijriMonth",
                      opts:["",...HIJRI_MONTHS_ASS] },
                    { label:"السنة", val:form.hijriYear, key:"hijriYear",
                      opts:HIJRI_YEARS_ASS.map(String) },
                  ].map(s=>(
                    <div key={s.key}>
                      <div style={{ fontSize:9.5, color:"rgba(255,255,255,0.6)", marginBottom:3 }}>{s.label}</div>
                      <select value={s.val} onChange={e=>setForm(f=>({...f,[s.key]:e.target.value}))}
                        style={{ width:"100%", padding:"7px 6px", borderRadius:7,
                                 border:"1.5px solid rgba(255,255,255,0.3)",
                                 background:"rgba(255,255,255,0.15)", color:"#fff",
                                 fontFamily:"'Tajawal',sans-serif", fontSize:12, fontWeight:700, outline:"none" }}>
                        {s.opts.map(o=><option key={o} value={o} style={{color:"#000",background:"#fff"}}>{o||"--"}{s.key==="hijriYear"&&o?" هـ":""}</option>)}
                      </select>
                    </div>
                  ))}
                </div>
              </div>
              {/* ميلادي */}
              <div>
                <div style={{ fontSize:11, color:"rgba(255,255,255,0.75)", fontWeight:700, marginBottom:6 }}>التاريخ الميلادي</div>
                <div style={{ display:"grid", gridTemplateColumns:"1fr 2fr 1fr", gap:6 }}>
                  {[
                    { label:"اليوم", val:form.gregDay, key:"gregDay",
                      opts:["",...Array.from({length:31},(_,i)=>String(i+1))] },
                    { label:"الشهر", val:form.gregMonth, key:"gregMonth",
                      opts:["",...GREGORIAN_MONTHS_ASS] },
                    { label:"السنة", val:form.gregYear, key:"gregYear",
                      opts:GREGORIAN_YEARS_ASS.map(String) },
                  ].map(s=>(
                    <div key={s.key}>
                      <div style={{ fontSize:9.5, color:"rgba(255,255,255,0.6)", marginBottom:3 }}>{s.label}</div>
                      <select value={s.val} onChange={e=>setForm(f=>({...f,[s.key]:e.target.value}))}
                        style={{ width:"100%", padding:"7px 6px", borderRadius:7,
                                 border:"1.5px solid rgba(255,255,255,0.3)",
                                 background:"rgba(255,255,255,0.15)", color:"#fff",
                                 fontFamily:"'Tajawal',sans-serif", fontSize:12, fontWeight:700, outline:"none" }}>
                        {s.opts.map(o=><option key={o} value={o} style={{color:"#000",background:"#fff"}}>{o||"--"}{s.key==="gregYear"&&o?" م":""}</option>)}
                      </select>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>

          <div style={{ background:"#fff", borderRadius:12, marginBottom:14, overflow:"hidden",
            border:"1px solid #d0dbe8", boxShadow:"0 2px 12px rgba(10,61,92,0.07)" }}>
            <div style={{ background:"linear-gradient(135deg,#0a3d5c,#0d5280)", padding:"11px 16px",
              display:"flex", alignItems:"center", gap:10 }}>
              <div style={{ width:32, height:32, background:"rgba(255,255,255,0.2)", borderRadius:8,
                display:"flex", alignItems:"center", justifyContent:"center", fontSize:16 }}>📋</div>
              <span style={{ color:"#fff", fontWeight:800, fontSize:14 }}>البيانات الأساسية</span>
            </div>
            <div style={{ padding:"16px" }}>
              <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fill,minmax(180px,1fr))", gap:10, marginBottom:12 }}>
                {[
                  {l:"اسم المعلم",    v:selectedTeacher.name,  ro:true},
                  {l:"الجوال",        v:selectedTeacher.mobile, ro:true},
                  {l:"الفصل",        v:form.grade,      k:"grade",   ph:"الصف والفصل"},
                  {l:"عنوان الدرس",  v:form.lesson,     k:"lesson",  ph:"موضوع الحصة"},
                  {l:"عدد الطلاب",   v:form.studentCount,k:"studentCount",tp:"number"},
                  {l:"الحاضرون",     v:form.presentCount,k:"presentCount",tp:"number"},
                  {l:"الغائبون",     v:form.absentCount, k:"absentCount",tp:"number"},
                  {l:"رقم الزيارة",  v:form.visitNum,   k:"visitNum"},
                  {l:"الغرض من الزيارة", v:form.visitPurpose,k:"visitPurpose",ph:"الغرض من الزيارة"},
                ].map((f,i)=>(
                  <F key={i} label={f.l}>
                    <input type={f.tp||"text"} value={f.v||""} readOnly={f.ro}
                      placeholder={f.ph||""}
                      onChange={e => !f.ro && setForm(p=>({...p,[f.k]:e.target.value}))}
                      style={{ padding:"8px 10px", border:"1.5px solid #d0dbe8", borderRadius:8,
                               fontFamily:"'Tajawal',sans-serif", fontSize:12.5, color:"#1a2d3e",
                               background:f.ro?"#f0f4f8":"#f9fbfd", direction:"rtl", outline:"none" }} />
                  </F>
                ))}
                {/* المادة - قائمة منسدلة مواد المرحلة المتوسطة */}
                <F label="المادة">
                  <select value={form.subject} onChange={e=>setForm(f=>({...f,subject:e.target.value}))}
                    style={{ padding:"8px 10px", border:"1.5px solid #d0dbe8", borderRadius:8,
                             fontFamily:"'Tajawal',sans-serif", fontSize:12.5, color:"#1a2d3e",
                             background:"#f9fbfd", direction:"rtl", outline:"none", width:"100%" }}>
                    <option value="">-- اختر المادة --</option>
                    {["القرآن الكريم","التفسير","التوحيد","الفقه","الحديث","التربية الإسلامية","اللغة العربية","النحو والصرف","الإملاء والخط","الأدب والبلاغة","الرياضيات","العلوم","الفيزياء","الكيمياء","الأحياء","اللغة الإنجليزية","الحاسب الآلي","التقنية الرقمية","الاجتماعيات","التاريخ","الجغرافيا","التربية الوطنية","الاقتصاد المنزلي","التربية الفنية","التربية البدنية"].map(m=>(
                      <option key={m} value={m}>{m}</option>
                    ))}
                  </select>
                </F>
                {/* الحصة - من 1 إلى 7 */}
                <F label="الحصة">
                  <select value={form.period} onChange={e=>setForm(f=>({...f,period:e.target.value}))}
                    style={{ padding:"8px 10px", border:"1.5px solid #d0dbe8", borderRadius:8,
                             fontFamily:"'Tajawal',sans-serif", fontSize:12.5, color:"#1a2d3e",
                             background:"#f9fbfd", direction:"rtl", outline:"none", width:"100%" }}>
                    <option value="">-- اختر الحصة --</option>
                    {[1,2,3,4,5,6,7].map(n=>(
                      <option key={n} value={n}>الحصة {n}</option>
                    ))}
                  </select>
                </F>
              </div>
              <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:16 }}>
                <div>
                  <div style={{ fontSize:12, fontWeight:700, color:"#0a3d5c", marginBottom:6 }}>نوع الزيارة</div>
                  <RadioGroup name="vtype" options={["حضوري","عن بعد"]}
                    value={form.visitType} onChange={v=>setForm(f=>({...f,visitType:v}))} />
                </div>
                <div>
                  <div style={{ fontSize:12, fontWeight:700, color:"#0a3d5c", marginBottom:6 }}>هل المعلم جديد على المادة؟</div>
                  <RadioGroup name="isnew" options={["نعم","لا"]}
                    value={form.isNew} onChange={v=>setForm(f=>({...f,isNew:v}))} />
                </div>
              </div>
            </div>
          </div>

          {/* أهداف الزيارة */}
          <div style={{ background:"#fff", borderRadius:12, marginBottom:14, overflow:"hidden",
            border:"1px solid #d0dbe8", boxShadow:"0 2px 12px rgba(10,61,92,0.07)" }}>
            <div style={{ background:"linear-gradient(135deg,#0e7c7b,#12a09e)", padding:"11px 16px",
              display:"flex", alignItems:"center", gap:10 }}>
              <div style={{ width:32, height:32, background:"rgba(255,255,255,0.2)", borderRadius:8,
                display:"flex", alignItems:"center", justifyContent:"center", fontSize:16 }}>🎯</div>
              <span style={{ color:"#fff", fontWeight:800, fontSize:14 }}>الأساليب التي اتبعها المشرف للتعرف على المستوى</span>
            </div>
            <div style={{ padding:"14px 16px" }}>
              <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fill,minmax(240px,1fr))", gap:8 }}>
                {[
                  "الزيارة الصفية والاجتماع بالمعلم",
                  "معرفة مدى مشاركته في الأنشطة الخارجية للمادة",
                  "الاطلاع على الإعداد الكتابي للدرس",
                  "مناقشة مدير المدرسة",
                  "الاطلاع على الواجبات والتطبيقات",
                  "زيارة الموجه الطلابي",
                  "الاطلاع على التقويم والاختبارات",
                  "إجراء اختبار قصير للطلاب",
                ].map(m => {
                  const checked = (form.visitGoals||[]).includes(m);
                  return (
                    <label key={m} onClick={()=>setForm(f=>({...f,visitGoals:checked?(f.visitGoals||[]).filter(x=>x!==m):[...(f.visitGoals||[]),m]}))}
                      style={{ display:"flex", alignItems:"flex-start", gap:8, padding:"9px 12px",
                               border:`1.5px solid ${checked?"#0e7c7b":"#d0dbe8"}`,
                               borderRadius:8, cursor:"pointer", background:checked?"#e8f8f8":"#fafcff",
                               transition:"all .15s" }}>
                      <div style={{ width:20, height:20, border:`2px solid ${checked?"#0e7c7b":"#d0dbe8"}`,
                        borderRadius:5, display:"flex", alignItems:"center", justifyContent:"center",
                        background:checked?"#0e7c7b":"#fff", color:"#fff", fontSize:12, flexShrink:0, marginTop:1 }}>
                        {checked?"✓":""}
                      </div>
                      <span style={{ fontSize:12.5, color:checked?"#0e7c7b":"#1a2d3e", lineHeight:1.4 }}>{m}</span>
                    </label>
                  );
                })}
              </div>
              <div style={{ marginTop:10 }}>
                <label style={{ fontSize:11, fontWeight:700, color:"#5a7080", display:"block", marginBottom:4 }}>أساليب أخرى اتبعها المشرف (اذكر)</label>
                <input value={form.methodsOther||""} onChange={e=>setForm(f=>({...f,methodsOther:e.target.value}))}
                  placeholder="اذكر أي أساليب أخرى..."
                  style={{ width:"100%", padding:"8px 10px", border:"1.5px solid #d0dbe8", borderRadius:8,
                           fontFamily:"'Tajawal',sans-serif", fontSize:12.5, outline:"none", boxSizing:"border-box" }} />
              </div>
            </div>
          </div>

          {/* محاور التقييم */}
          {EVAL_SECTIONS.map(sec => <SectionCard key={sec.id} sec={sec} />)}

          {/* الدرجة الكلية */}
          {totalScore() > 0 && (
            <div style={{ background:"linear-gradient(135deg,#071e34,#0a3d5c,#0e6d6b)", borderRadius:14,
              padding:"20px", textAlign:"center", color:"#fff", marginBottom:14 }}>
              <div style={{ fontSize:12, opacity:.7 }}>الدرجة الكلية للزيارة</div>
              <div style={{ fontSize:52, fontWeight:900, margin:"8px 0 4px" }}>{totalScore()}</div>
              <div style={{ fontSize:14, background:"rgba(255,255,255,0.15)", borderRadius:20,
                padding:"4px 18px", display:"inline-block" }}>{scoreLabel(totalScore())}</div>
            </div>
          )}

          {/* الملاحظات والتوصيات */}
          {[
            {l:"مستوى الأداء * ممتاز (5) جيد جداً (4) جيد (3) جيد جداً (2) مقبول (1) ضعيف *", k:"performanceNote", rows:2},
            {l:"يستفاد من المعلم في", k:"benefitFrom", rows:2},
            {l:"توصيات", k:"recommendations", rows:3},
          ].map(({l,k,rows})=>(
            <div key={k} style={{ background:"#fff", borderRadius:12, marginBottom:10,
              border:"1px solid #d0dbe8", padding:14 }}>
              <label style={{ fontSize:12.5, fontWeight:700, color:"#0a3d5c", display:"block", marginBottom:6 }}>{l}</label>
              <textarea value={form[k]||""} onChange={e=>setForm(f=>({...f,[k]:e.target.value}))}
                rows={rows} placeholder="اكتب هنا..."
                style={{ width:"100%", padding:"9px 12px", border:"1.5px solid #d0dbe8", borderRadius:8,
                         fontFamily:"'Tajawal',sans-serif", fontSize:12.5, resize:"vertical",
                         direction:"rtl", outline:"none", boxSizing:"border-box" }} />
            </div>
          ))}

          {/* الاحتياجات التدريبية */}
          <div style={{ background:"#fff", borderRadius:12, marginBottom:14, overflow:"hidden",
            border:"1px solid #d0dbe8" }}>
            <div style={{ background:"linear-gradient(135deg,#4a2080,#6b35b0)", padding:"11px 16px" }}>
              <span style={{ color:"#fff", fontWeight:800, fontSize:14 }}>📚 الاحتياجات التدريبية</span>
            </div>
            <div style={{ padding:14 }}>
              <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:8, fontSize:11,
                fontWeight:700, color:"#0a3d5c", marginBottom:6, padding:"0 2px" }}>
                <span>الاحتياج التدريبي</span><span>البرنامج المقترح</span>
              </div>
              {form.needs.map((n,i)=>(
                <div key={i} style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:8, marginBottom:8 }}>
                  <input value={n.need} placeholder={`احتياج ${i+1}`}
                    onChange={e=>setForm(f=>({...f,needs:f.needs.map((x,j)=>j===i?{...x,need:e.target.value}:x)}))}
                    style={{ padding:"7px 10px", border:"1.5px solid #d0dbe8", borderRadius:8,
                             fontFamily:"'Tajawal',sans-serif", fontSize:12.5, outline:"none" }} />
                  <input value={n.program} placeholder="البرنامج المناسب"
                    onChange={e=>setForm(f=>({...f,needs:f.needs.map((x,j)=>j===i?{...x,program:e.target.value}:x)}))}
                    style={{ padding:"7px 10px", border:"1.5px solid #d0dbe8", borderRadius:8,
                             fontFamily:"'Tajawal',sans-serif", fontSize:12.5, outline:"none" }} />
                </div>
              ))}
            </div>
          </div>

          {/* التوقيعات */}
          <div style={{ background:"#fff", borderRadius:12, marginBottom:14, overflow:"hidden",
            border:"1px solid #d0dbe8", boxShadow:"0 2px 12px rgba(10,61,92,0.07)" }}>
            <div style={{ background:"linear-gradient(135deg,#071e34,#0a3d5c)", padding:"11px 16px",
              display:"flex", alignItems:"center", gap:10 }}>
              <span style={{ color:"#fff", fontWeight:800, fontSize:14 }}>✍️ التوقيعات</span>
            </div>
            <div style={{ padding:"20px 16px" }}>
              {/* حقول الأسماء */}
              <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:14, marginBottom:24 }}>
                <div>
                  <label style={{ fontSize:11, fontWeight:700, color:"#5a7080", display:"block", marginBottom:5 }}>المدير / الوكيل المُوقِّع</label>
                  <select value={form.principalName||"فازع عبدالله حسن القرني"}
                    onChange={e=>setForm(f=>({...f,principalName:e.target.value}))}
                    style={{ width:"100%", padding:"9px 12px", border:"1.5px solid #d0dbe8", borderRadius:8,
                             fontFamily:"'Tajawal',sans-serif", fontSize:13, color:"#1a2d3e",
                             background:"#f9fbfd", direction:"rtl", outline:"none", boxSizing:"border-box" }}>
                    <option value="فازع عبدالله حسن القرني">فازع عبدالله حسن القرني — مدير المدرسة</option>
                    <option value="أمين الحنيطي">أمين الحنيطي — وكيل المدرسة</option>
                  </select>
                </div>
                <div>
                  <label style={{ fontSize:11, fontWeight:700, color:"#5a7080", display:"block", marginBottom:5 }}>اسم المشرف التربوي</label>
                  <input value={form.supervisorName||""} onChange={e=>setForm(f=>({...f,supervisorName:e.target.value}))}
                    placeholder="اسم المشرف التربوي"
                    style={{ width:"100%", padding:"9px 12px", border:"1.5px solid #d0dbe8", borderRadius:8,
                             fontFamily:"'Tajawal',sans-serif", fontSize:13, color:"#1a2d3e",
                             background:"#f9fbfd", direction:"rtl", outline:"none", boxSizing:"border-box" }} />
                </div>
              </div>
              {/* خطوط التوقيع */}
              <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 1fr", gap:24 }}>
                {[
                  { title:"توقيع المعلم",       name:selectedTeacher?.name||"" },
                  { title: form.principalName==="أمين الحنيطي" ? "وكيل المدرسة" : "مدير المدرسة",
                    name:form.principalName||"فازع عبدالله حسن القرني" },
                  { title:"المشرف التربوي",      name:form.supervisorName||"" },
                ].map((s,i)=>(
                  <div key={i} style={{ textAlign:"center" }}>
                    <div style={{ height:52, borderBottom:"1.5px dashed #b0c4d8", marginBottom:8,
                      display:"flex", alignItems:"flex-end", justifyContent:"center", paddingBottom:6 }}>
                      <span style={{ fontSize:10, color:"#aaa" }}>التوقيع</span>
                    </div>
                    <div style={{ fontWeight:700, color:"#0a3d5c", fontSize:12.5 }}>{s.name||"\u00a0"}</div>
                    <div style={{ fontSize:11, color:"#5a7080", marginTop:3 }}>{s.title}</div>
                  </div>
                ))}
              </div>
            </div>
          </div>

        </div>
      </div>
    );
  }

  /* ══ الصفحة الرئيسية — قائمة المعلمين ══ */
  return (
    <div dir="rtl" style={{ fontFamily:"'Tajawal','Cairo',sans-serif", minHeight:"100vh", background:"#f0f4f8" }}>

      {/* Hero */}
      <div style={{ background:"linear-gradient(160deg,#071e34 0%,#0a3d5c 50%,#0e6d6b 100%)",
        padding:"28px 20px 50px", textAlign:"center", position:"relative", overflow:"hidden" }}>
        <div style={{ position:"relative", zIndex:2 }}>
          <div style={{ fontSize:32, marginBottom:6 }}>📊</div>
          <div style={{ fontSize:22, fontWeight:900, color:"#fff", marginBottom:4 }}>بطاقات تشخيص قياس التحصيل</div>
          <div style={{ fontSize:12, color:"rgba(255,255,255,0.6)" }}>مدرسة الأمير عبدالمجيد المتوسطة الأولى</div>
          <div style={{ display:"flex", gap:12, justifyContent:"center", marginTop:18, flexWrap:"wrap" }}>
            {[
              {n:ASSESSMENT_TEACHERS.length, l:"إجمالي المعلمين",    c:"#fff"},
              {n:totalVisited,               l:"تمت زيارتهم",         c:"#6dffa0"},
              {n:ASSESSMENT_TEACHERS.length-totalVisited, l:"لم تتم زيارتهم", c:"#ffcf6d"},
            ].map((s,i)=>(
              <div key={i} style={{ background:"rgba(255,255,255,0.1)", border:"1px solid rgba(255,255,255,0.15)",
                borderRadius:12, padding:"12px 22px", textAlign:"center", minWidth:110 }}>
                <div style={{ fontSize:26, fontWeight:900, color:s.c }}>{s.n}</div>
                <div style={{ fontSize:11, color:"rgba(255,255,255,0.6)", marginTop:3 }}>{s.l}</div>
              </div>
            ))}
          </div>
        </div>
      </div>

      <div style={{ maxWidth:900, margin:"-24px auto 0", padding:"0 14px 60px", position:"relative", zIndex:10 }}>

        {/* شريط البحث */}
        <div style={{ background:"#fff", borderRadius:14, boxShadow:"0 4px 20px rgba(10,61,92,0.1)",
          padding:"12px 16px", marginBottom:16, display:"flex", gap:10, alignItems:"center",
          border:"1px solid #d0dbe8" }}>
          <span style={{ fontSize:18, color:"#5a7080" }}>🔍</span>
          <input value={search} onChange={e=>setSearch(e.target.value)}
            placeholder="ابحث باسم المعلم..."
            style={{ flex:1, border:"none", outline:"none", fontFamily:"'Tajawal',sans-serif",
                     fontSize:14, color:"#1a2d3e", background:"transparent" }} />
          <div style={{ display:"flex", gap:6 }}>
            {["all","visited","pending"].map(f=>(
              <button key={f} onClick={()=>setFilter(f)}
                style={{ padding:"5px 12px", borderRadius:20, fontSize:11.5, fontWeight:700,
                         cursor:"pointer", border:`2px solid ${filter===f?"#0e7c7b":"#d0dbe8"}`,
                         background:filter===f?"#e8f8f8":"#fafcff",
                         color:filter===f?"#0e7c7b":"#5a7080", fontFamily:"'Tajawal',sans-serif" }}>
                {f==="all"?"الكل":f==="visited"?"تمت الزيارة":"لم تُزَر"}
              </button>
            ))}
          </div>
        </div>

        {/* شبكة المعلمين */}
        <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fill,minmax(260px,1fr))", gap:12 }}>
          {filteredTeachers.map(t => {
            const count = getVisitCount(t.id);
            const visited = count > 0;
            const lastRec = visited ? assessments[t.id][assessments[t.id].length-1] : null;
            return (
              <div key={t.id} style={{
                background:"#fff", borderRadius:12, border:"1.5px solid #d0dbe8",
                boxShadow:"0 2px 12px rgba(10,61,92,0.07)", padding:14, cursor:"pointer",
                display:"flex", flexDirection:"column", gap:10, position:"relative", overflow:"hidden",
                transition:"all .2s", borderRight:`4px solid ${visited?"#0e7c7b":"#c8973a"}`,
              }}
                onMouseOver={e=>{e.currentTarget.style.boxShadow="0 6px 24px rgba(10,61,92,0.14)";e.currentTarget.style.transform="translateY(-2px)";}}
                onMouseOut={e=>{e.currentTarget.style.boxShadow="0 2px 12px rgba(10,61,92,0.07)";e.currentTarget.style.transform="translateY(0)";}}>
                <div style={{ display:"flex", alignItems:"center", gap:10 }}>
                  <div style={{ width:44, height:44, borderRadius:12, flexShrink:0,
                    background:"linear-gradient(135deg,#0a3d5c,#0e7c7b)",
                    display:"flex", alignItems:"center", justifyContent:"center",
                    color:"#fff", fontWeight:900, fontSize:18, fontFamily:"serif" }}>
                    {t.name.charAt(0)}
                  </div>
                  <div style={{ flex:1, minWidth:0 }}>
                    <div style={{ fontWeight:700, fontSize:13, color:"#1a2d3e",
                      overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{t.name}</div>
                    <div style={{ fontSize:11, color:"#5a7080", direction:"ltr", textAlign:"right" }}>{t.mobile}</div>
                  </div>
                  <div style={{ padding:"3px 10px", borderRadius:20, fontSize:11, fontWeight:700, flexShrink:0,
                    background:visited?"#e8f8f0":"#fff8e8", color:visited?"#1a6b3c":"#9a7230",
                    border:`1px solid ${visited?"#a0d8b8":"#e8c96a"}` }}>
                    {visited?"✅ زيارة":"⏳ لم تُزَر"}
                  </div>
                </div>
                <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between",
                  paddingTop:8, borderTop:"1px solid #e8eef4" }}>
                  <div style={{ fontSize:11, color:"#5a7080" }}>
                    عدد الزيارات: <span style={{ fontWeight:700, color:"#0e7c7b" }}>{count}</span>
                    {lastRec&&<span style={{ marginRight:6, color:"#aaa" }}>| آخر: {lastRec.savedAt}</span>}
                  </div>
                  <div style={{ display:"flex", gap:6 }}>
                    {visited && (
                      <button onClick={e=>{e.stopPropagation();setDetailRec(assessments[t.id][assessments[t.id].length-1]);setView("detail");}}
                        style={{ padding:"5px 10px", background:"#f0f4f8", border:"1.5px solid #d0dbe8",
                                 borderRadius:7, fontSize:11, fontWeight:700, cursor:"pointer", color:"#5a7080" }}>
                        📋 عرض
                      </button>
                    )}
                    <button onClick={()=>{setSelectedTeacher(t);setForm(emptyForm());setView("form");}}
                      style={{ padding:"5px 12px", background:"#0a3d5c", border:"none",
                               borderRadius:7, fontSize:11, fontWeight:700, cursor:"pointer", color:"#fff",
                               fontFamily:"'Tajawal',sans-serif" }}>
                      + زيارة
                    </button>
                  </div>
                </div>
              </div>
            );
          })}
        </div>

        {filteredTeachers.length === 0 && (
          <div style={{ textAlign:"center", padding:"40px", color:"#5a7080" }}>
            <div style={{ fontSize:36, marginBottom:8 }}>🔍</div>
            <div style={{ fontWeight:700 }}>لا توجد نتائج</div>
          </div>
        )}
      </div>
    </div>
  );
}


// ═══════════════════════════════════════════════════════════════
//  📊 صفحة استمارة تقييم أداء المعلم — 33 معلماً
// ═══════════════════════════════════════════════════════════════

// ══════════════════════════════════════════════════════
//  📝 حقل التعليق والتغذية الراجعة لكل مؤشر (للمدير)
// ══════════════════════════════════════════════════════
function EvalFeedbackField({ criterionNum, formValues, setFormValues }) {
  const textKey = `feedback_text_${criterionNum}`;
  const imgsKey = `feedback_imgs_${criterionNum}`;
  const [open, setOpen] = React.useState(!!(formValues[textKey] || (formValues[imgsKey]||[]).length));
  const fileRef = React.useRef();

  const text = formValues[textKey] || "";
  const imgs = formValues[imgsKey] || [];

  const updText = (v) => setFormValues(p => ({...p, [textKey]: v}));
  const addImg  = (file) => {
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (e) => {
      const newImgs = [...imgs, {dataUrl: e.target.result, name: file.name}];
      setFormValues(p => ({...p, [imgsKey]: newImgs}));
    };
    reader.readAsDataURL(file);
  };
  const removeImg = (idx) => {
    const newImgs = imgs.filter((_,i)=>i!==idx);
    setFormValues(p => ({...p, [imgsKey]: newImgs}));
  };

  const hasFeedback = text || imgs.length > 0;

  return (
    <div style={{marginTop:8}}>
      <button onClick={()=>setOpen(p=>!p)}
        style={{display:"flex",alignItems:"center",gap:6,background:open?"#eff6ff":hasFeedback?"#f0fdf4":"#f8fafc",
          border:`1.5px solid ${open?"#bfdbfe":hasFeedback?"#86efac":"#e2e8f0"}`,
          borderRadius:10,padding:"5px 12px",cursor:"pointer",fontFamily:"'Cairo',sans-serif",
          fontSize:12,fontWeight:700,color:open?"#3b82f6":hasFeedback?"#059669":"#94a3b8"}}>
        <span>{hasFeedback?"💬":"➕"}</span>
        <span>{hasFeedback?"تعديل التغذية الراجعة":"إضافة تعليق وتغذية راجعة"}</span>
        {hasFeedback && <span style={{background:"#059669",color:"#fff",borderRadius:"50%",
          width:18,height:18,display:"flex",alignItems:"center",justifyContent:"center",fontSize:10}}>
          {imgs.length > 0 ? `${imgs.length}📷` : "✓"}
        </span>}
      </button>

      {open && (
        <div style={{marginTop:8,padding:12,background:"#f8fafc",borderRadius:12,border:"1.5px solid #e2e8f0"}}>
          <div style={{fontSize:12,fontWeight:700,color:"#0d3b6e",marginBottom:8}}>
            💬 التعليق والتغذية الراجعة من المدير
          </div>

          {/* محرر النص */}
          <textarea
            value={text}
            onChange={e=>updText(e.target.value)}
            placeholder="اكتب تعليقك وملاحظاتك للمعلم هنا... يمكن أن تتضمن نقاط القوة والضعف والتوصيات"
            style={{width:"100%",padding:"10px 12px",borderRadius:10,border:"1.5px solid #e2e8f0",
              fontSize:13,fontFamily:"'Cairo',sans-serif",minHeight:90,resize:"vertical",
              lineHeight:1.8,boxSizing:"border-box",color:"#1e293b",fontWeight:600,
              background:"#fff"}}
          />

          {/* رفع الصور */}
          <div style={{marginTop:8}}>
            <div style={{fontSize:11,fontWeight:700,color:"#64748b",marginBottom:6}}>📸 إرفاق صور توضيحية</div>
            <div style={{display:"flex",gap:8,flexWrap:"wrap",alignItems:"center"}}>
              {imgs.map((img, i) => (
                <div key={i} style={{position:"relative",width:72,height:72,borderRadius:10,overflow:"hidden",
                  border:"2px solid #bfdbfe",flexShrink:0}}>
                  <img src={img.dataUrl} alt={img.name}
                    style={{width:"100%",height:"100%",objectFit:"cover"}} />
                  <button onClick={()=>removeImg(i)}
                    style={{position:"absolute",top:2,right:2,background:"#dc2626",color:"#fff",
                      border:"none",borderRadius:"50%",width:20,height:20,cursor:"pointer",
                      display:"flex",alignItems:"center",justifyContent:"center",fontSize:10}}>
                    ✕
                  </button>
                </div>
              ))}
              <label style={{width:72,height:72,borderRadius:10,border:"2px dashed #bfdbfe",
                display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",
                cursor:"pointer",background:"#eff6ff",flexShrink:0}}>
                <span style={{fontSize:22}}>📷</span>
                <span style={{fontSize:9,color:"#3b82f6",fontWeight:700,marginTop:2}}>إضافة</span>
                <input type="file" accept="image/*" style={{display:"none"}} ref={fileRef}
                  onChange={e=>{const f=e.target.files?.[0];if(f)addImg(f);e.target.value="";}} />
              </label>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// ══════════════════════════════════════════════════════
//  📖 عرض التغذية الراجعة للمعلم (قراءة فقط — خط جميل)
// ══════════════════════════════════════════════════════
function EvalFeedbackDisplay({ text, imgs, criterionName }) {
  const [imgOpen, setImgOpen] = React.useState(null);
  if (!text && (!imgs || imgs.length === 0)) return null;
  return (
    <div style={{margin:"0 12px 12px",padding:"12px 14px",
      background:"linear-gradient(135deg,#fffbeb,#fef9ef)",
      border:"2px solid #fde68a",borderRadius:12}}>
      {/* عنوان */}
      <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:8}}>
        <div style={{width:28,height:28,borderRadius:"50%",background:"linear-gradient(135deg,#f59e0b,#d97706)",
          display:"flex",alignItems:"center",justifyContent:"center",fontSize:14,flexShrink:0}}>
          💬
        </div>
        <div>
          <div style={{fontWeight:900,fontSize:12,color:"#92400e"}}>تغذية راجعة من المدير</div>
          <div style={{fontSize:10,color:"#b45309",opacity:.8}}>فازع القرني</div>
        </div>
      </div>

      {/* النص بخط جميل وواضح */}
      {text && (
        <div style={{
          fontFamily:"'Cairo',sans-serif",
          fontSize:14,
          fontWeight:700,
          lineHeight:2,
          color:"#1e293b",
          background:"#fff",
          borderRadius:10,
          padding:"10px 14px",
          border:"1px solid #fde68a",
          marginBottom:imgs&&imgs.length>0?8:0,
          whiteSpace:"pre-wrap",
          letterSpacing:".01em",
        }}>
          {text}
        </div>
      )}

      {/* الصور */}
      {imgs && imgs.length > 0 && (
        <div>
          <div style={{fontSize:11,fontWeight:700,color:"#92400e",marginBottom:6}}>📸 صور توضيحية:</div>
          <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
            {imgs.map((img, i) => (
              <div key={i} onClick={()=>setImgOpen(img.dataUrl)}
                style={{width:80,height:80,borderRadius:10,overflow:"hidden",cursor:"pointer",
                  border:"2px solid #fde68a",boxShadow:"0 2px 6px rgba(0,0,0,.1)"}}>
                <img src={img.dataUrl} alt={`صورة ${i+1}`}
                  style={{width:"100%",height:"100%",objectFit:"cover"}} />
              </div>
            ))}
          </div>
        </div>
      )}

      {/* عارض الصورة الكاملة */}
      {imgOpen && (
        <div onClick={()=>setImgOpen(null)}
          style={{position:"fixed",inset:0,background:"rgba(0,0,0,.85)",zIndex:9999,
            display:"flex",alignItems:"center",justifyContent:"center",cursor:"pointer"}}>
          <div onClick={e=>e.stopPropagation()} style={{maxWidth:"90vw",maxHeight:"90vh",position:"relative"}}>
            <img src={imgOpen} alt="صورة توضيحية"
              style={{maxWidth:"100%",maxHeight:"90vh",borderRadius:12,boxShadow:"0 8px 32px rgba(0,0,0,.5)"}} />
            <button onClick={()=>setImgOpen(null)}
              style={{position:"absolute",top:-12,left:-12,background:"#dc2626",color:"#fff",
                border:"none",borderRadius:"50%",width:32,height:32,cursor:"pointer",fontSize:16,fontWeight:900}}>
              ✕
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

