// ══════════════════════════════════════════════════════════
// سجل رصد التقويم التكويني — جدول عرضي بأعمدة ملونة وفق لائحة تقويم الطالب
// ══════════════════════════════════════════════════════════
const FG_PALETTE = ["#0d9488","#2563eb","#7c3aed","#db2777","#ea580c","#ca8a04","#16a34a","#0891b2","#dc2626","#4f46e5","#9333ea","#475569"];
const FG_GROUP_COLORS = ["#0d9488","#7c3aed","#ea580c","#2563eb","#db2777"];
const FG_SEMESTERS = ["الفترة الأولى","الفترة الثانية","الفترة الثالثة"];
const FG_LEVELS = ["الصف الأول المتوسط","الصف الثاني المتوسط","الصف الثالث المتوسط"];
const fgId = () => Math.random().toString(36).slice(2, 9);
// معلمو المدرسة (من تقرير الحضور والانصراف) — يمكن تحديثها من داخل الصفحة
const FG_TEACHERS_DEFAULT = ["عبدالرحيم رضوان", "علي الغامدي", "فازع القرني", "احمد الشهري", "محمد الجوفي", "رمضان الزهراني", "فايز الزلفي", "وليد الزايدي", "يحي الزبيدي", "عبدالعزيز الزهراني", "هادي المقاطي العتيبي", "فارس البشري", "عادل الغامدي", "عبدالله السهيمي", "سعد العتيبي", "عمر العمشاني", "محمد القارحى", "ماجد الهذلي", "حاتم الشمراني", "محمد الحربي", "فهد ال رده", "عبدالعزيز الذبياني", "حسن العيسى", "أحمد عزي", "فيصل العتيبى", "صاطي الحارثي", "محمد الشهري", "مجاهد الزهراني", "طارق الزهراني", "جابر الشهري", "محمد وراد الحربي", "عوض العماري", "اسامه السفري"];
// فصول كل صف
const FG_SECTIONS = { "الصف الأول المتوسط": ["1","2","3","4","5","6","7","8"], "الصف الثاني المتوسط": ["1","2","3","4","5","6"], "الصف الثالث المتوسط": ["1","2","3","4","5","6"] };

// توزيع الدرجة داخل كل مكوّن من مكونات النموذج
function fgSplitPart(label, total) {
  // [الاسم، الدرجة، عدد الخانات]
  if (label.includes("المهام الأدائية")) {
    const q = total / 4;
    return [["المشاركة", q, 5], ["الواجبات", q, 5], ["المهام الأدائية", q, 5], ["المشروع / البحث", q, 4]];
  }
  if (label.includes("اختبار نهاية")) return [["اختبار نهائي", total]];
  if (total <= 20) return [["فترة أولى", total / 2], ["فترة ثالثة", total / 2]];
  if (label.includes("شفهية وتحريرية")) return [["تقويم شفهي", 15], ["فترة أولى", 15], ["فترة ثالثة", 15], ["اختبار نهائي", total - 45]];
  if (label.includes("تطبيقات")) return [["تطبيقات عملية", 20], ["فترة أولى", 20], ["اختبار نهائي", total - 40]];
  if (label.includes("متنوعة")) return [["تطبيقات عملية", 20], ["تقويم شفهي", 20], ["اختبار نهائي", total - 40]];
  return [["فترة أولى", 20], ["فترة ثالثة", 20], ["اختبار نهائي", total - 40]];
}

// نموذجا السجل وفق دليل تقويم الطالب:
//  final   : مواد لها اختبار نهائي  → المهام الأدائية والمشاركة ٤٠ + اختبارات تحريرية قصيرة ٢٠ + اختبار نهاية الفترة ٤٠
//  nofinal : مواد بلا اختبار نهائي  → المهام الأدائية والمشاركة ٤٠ + تقويمات تحريرية/شفهية/عملية ٦٠
const FG_FORMS = {
  final: { ic: "📝", t: "نموذج المواد ذات الاختبار النهائي", d: "٤٠ مهام أدائية ومشاركة + ٢٠ اختبارات قصيرة + ٤٠ اختبار نهائي", c: "#dc2626" },
  nofinal: { ic: "📘", t: "نموذج المواد بدون اختبار نهائي", d: "٤٠ مهام أدائية ومشاركة + ٦٠ تقويمات تحريرية وشفهية وعملية", c: "#2563eb" },
};
const fgFormOf = (key) => { const m = (typeof GA_MODELS !== "undefined" && GA_MODELS[key]) || null; return m && m.fe > 0 ? "final" : "nofinal"; };
function fgBuildColumns(modelKey, form) {
  const m = (typeof GA_MODELS !== "undefined" && GA_MODELS[modelKey]) || { parts: { "المهام الأدائية والمشاركة": 40 } };
  const f = form || fgFormOf(modelKey);
  const g1 = { id: fgId(), label: "المهام الأدائية والمشاركة", max: 40, color: FG_GROUP_COLORS[0] };
  const perf = [
    { label: "المشاركة والتفاعل الصفي", max: 10, entries: 5, groupId: g1.id, color: "#0d9488" },
    { label: "الواجبات", max: 10, entries: 5, groupId: g1.id, color: "#2563eb" },
    { label: "المهام الأدائية", max: 10, entries: 5, groupId: g1.id, color: "#7c3aed" },
    { label: "المشروع / البحث", max: 10, entries: 4, groupId: g1.id, color: "#db2777" },
  ];
  let groups, cols;
  if (f === "final") {
    const g2 = { id: fgId(), label: "الاختبارات التحريرية القصيرة", max: 20, color: FG_GROUP_COLORS[1] };
    const g3 = { id: fgId(), label: "اختبار نهاية الفترة", max: 40, color: "#dc2626", exam: true };
    groups = [g1, g2, g3];
    cols = [...perf,
      { label: "اختبار قصير (١)", max: 20, weight: 0.5, groupId: g2.id, color: "#ea580c" },
      { label: "اختبار قصير (٢)", max: 20, weight: 0.5, groupId: g2.id, color: "#ca8a04" },
      { label: "اختبار نهائي", max: 40, exam: true, groupId: g3.id, color: "#dc2626" }];
  } else {
    const p2 = Object.keys(m.parts || {}).find(l => !l.includes("المهام الأدائية")) || "تقويمات تحريرية";
    const prac = /تطبيقات|متنوعة/.test(p2), oral = /شفهية|متنوعة/.test(p2);
    const g2 = { id: fgId(), label: p2.includes("تقويم") ? p2 : "التقويمات التحريرية والشفهية", max: 60, color: FG_GROUP_COLORS[1] };
    groups = [g1, g2];
    cols = [...perf,
      { label: "اختبار قصير (١)", max: 20, groupId: g2.id, color: "#ea580c" },
      { label: "اختبار قصير (٢)", max: 20, groupId: g2.id, color: "#ca8a04" },
      { label: prac ? "تطبيقات عملية" : oral ? "تقويم شفهي" : "اختبار قصير (٣)", max: 20, groupId: g2.id, color: "#16a34a" }];
  }
  return { groups, cols: cols.map(c => ({ id: fgId(), entries: 1, weight: 1, ...c })), form: f, v: 4 };
}

function fgNewSheet(defaults = {}) {
  const model = defaults.model || "4";
  return {
    id: "fg-" + Date.now(), teacher: "", subject: "", level: FG_LEVELS[0], section: "1",
    semester: FG_SEMESTERS[0], year: "١٤٤٧هـ", edu: "الإدارة العامة للتعليم",
    school: "مدرسة الأمير عبدالمجيد المتوسطة", model, ...fgBuildColumns(model),
    students: Array.from({ length: 5 }, () => ({ id: fgId(), name: "", scores: {} })),
    ...defaults, updated: Date.now(),
  };
}

