const hfxNid = h => (h && hfxIds()[h]) || "";
const hfxTok = () => { try { const a = new Uint8Array(12); crypto.getRandomValues(a); return [...a].map(b => b.toString(36).padStart(2, "0")).join("").slice(0, 18); } catch { return Math.random().toString(36).slice(2) + Date.now().toString(36); } };
const hfxLink = c => { try { return `${location.origin}${location.pathname}#hfx=${c.id}.${c.tok}`; } catch { return `#hfx=${c.id}.${c.tok}`; } };
const HFX_ST = {
  draft: { l: "مسودة", c: "#64748b", bg: "#f1f5f9", ic: "📝" }, sent: { l: "أُرسل للمعلم", c: "#0369a1", bg: "#e0f2fe", ic: "📤" },
  opened: { l: "اطّلع عليه المعلم", c: "#7c3aed", bg: "#ede9fe", ic: "👁️" }, replied: { l: "أعاده المعلم موقّعاً", c: "#b45309", bg: "#fef3c7", ic: "✍️" },
  ack: { l: "اطّلع المعلم", c: "#0f766e", bg: "#ccfbf1", ic: "✅" }, closed: { l: "مكتمل", c: "#15803d", bg: "#dcfce7", ic: "🗂️" },
};
async function hfxLoadTeachers() {
  const [lic, prof, ph] = await Promise.all([maGet(LIC_NODE), maGet(HFX_TP), maGet(PH_NODE)]);
  const M = {};
  Object.values(ptObj(lic)).forEach(r => { if (r && r.name) { const k = asmK(r.name); M[k] = { k, n: String(r.name).trim(), h: r.idHash || "", n4: r.id4 || "", sp: r.spec || "" }; } });
  Object.values(ptObj(prof)).forEach(p => { if (p && p.n) { const k = p.k || asmK(p.n); M[k] = { ...(M[k] || {}), ...Object.fromEntries(Object.entries(p).filter(([, v]) => v !== "" && v != null)), k, n: p.n }; } });
  const P = ptObj(ph);
  return Object.values(M).map(t => ({ ...t, ph: t.ph || phOf(P, t.n) || "" })).sort((a, b) => a.n.localeCompare(b.n, "ar"));
}
// قراءة ملف المعلمين (Excel): الاسم + السجل المدني + أي أعمدة وظيفية أو جوال إن وُجدت
async function hfxParseExcel(file) {
  const XLSX = await loadXLSX(); const wb = XLSX.read(await file.arrayBuffer()); const out = new Map();
  const find = (r, re) => r.findIndex(x => re.test(x));
  wb.SheetNames.forEach(sn => {
    const rows = XLSX.utils.sheet_to_json(wb.Sheets[sn], { header: 1, defval: "" }); let hi = -1, C = {};
    for (let i = 0; i < Math.min(rows.length, 40) && hi < 0; i++) {
      const r = rows[i].map(x => String(x ?? "").trim());
      const a = find(r, /^(الإسم|الاسم|اسم الموظف|اسم المعلم|الاسم الرباعي|اسم الموظفـ?ة?)$/), b = find(r, /السجل المدني|رقم الهوية|الهوية الوطنية|رقم السجل/);
      if (a >= 0 && b >= 0) { hi = i; C = { n: a, id: b, sp: find(r, /التخصص/), lv: find(r, /المرتبة|المستوى|الرتبة/), jn: find(r, /رقم الوظيفة/), ttl: find(r, /المسمى/), ph: find(r, /الجوال|الهاتف|رقم التواصل|الموبايل/) }; }
    }
    if (hi < 0) return;
    rows.slice(hi + 1).forEach(r => { const nid = licNormId(r[C.id]); const n = String(r[C.n] ?? "").replace(/\s+/g, " ").trim(); if (nid.length !== 10 || !n) return;
      const g = k => C[k] >= 0 ? String(r[C[k]] ?? "").trim() : ""; if (!out.has(nid)) out.set(nid, { nid, n, sp: g("sp"), lv: g("lv"), jn: g("jn"), ttl: g("ttl"), ph: g("ph") }); });
  });
  return [...out.values()];
}

// ── لوحة التوقيع بالإصبع
function HfxSigPad({ title, onDone, onCancel }) {
  const ref = useRef(null); const [has, setHas] = useState(false); const st = useRef({ d: false, pts: [], bb: null });
  useEffect(() => {
    const cv = ref.current; const r = cv.getBoundingClientRect(); const dpr = Math.min(3, window.devicePixelRatio || 1);
    cv.width = r.width * dpr; cv.height = r.height * dpr; const g = cv.getContext("2d"); g.scale(dpr, dpr); g.lineCap = "round"; g.lineJoin = "round"; g.strokeStyle = HFX_INK;
    const pos = e => { const b = cv.getBoundingClientRect(); return { x: e.clientX - b.left, y: e.clientY - b.top, p: e.pressure || 0.5 }; };
    const grow = p => { const s = st.current; s.bb = s.bb ? { x0: Math.min(s.bb.x0, p.x), y0: Math.min(s.bb.y0, p.y), x1: Math.max(s.bb.x1, p.x), y1: Math.max(s.bb.y1, p.y) } : { x0: p.x, y0: p.y, x1: p.x, y1: p.y }; };
    const dn = e => { e.preventDefault(); cv.setPointerCapture && cv.setPointerCapture(e.pointerId); const p = pos(e); st.current.d = true; st.current.pts = [p]; grow(p); g.beginPath(); g.lineWidth = 2.6; g.arc(p.x, p.y, 1.2, 0, 7); g.fillStyle = HFX_INK; g.fill(); setHas(true); };
    const mv = e => { if (!st.current.d) return; e.preventDefault(); const p = pos(e); const L = st.current.pts; const q = L[L.length - 1]; L.push(p); grow(p);
      g.beginPath(); g.lineWidth = 1.8 + 1.6 * (p.p || 0.5); const m = { x: (q.x + p.x) / 2, y: (q.y + p.y) / 2 }; g.moveTo(q.x, q.y); g.quadraticCurveTo(q.x, q.y, m.x, m.y); g.lineTo(p.x, p.y); g.stroke(); };
    const up = () => { st.current.d = false; };
    cv.addEventListener("pointerdown", dn); cv.addEventListener("pointermove", mv); window.addEventListener("pointerup", up); cv.addEventListener("pointercancel", up);
    return () => { cv.removeEventListener("pointerdown", dn); cv.removeEventListener("pointermove", mv); window.removeEventListener("pointerup", up); cv.removeEventListener("pointercancel", up); };
  }, []);
  const clear = () => { const cv = ref.current; cv.getContext("2d").clearRect(0, 0, cv.width, cv.height); st.current.bb = null; setHas(false); };
  const done = () => {
    const cv = ref.current; const bb = st.current.bb; if (!bb) return; const dpr = cv.width / cv.getBoundingClientRect().width; const pad = 8;
    const x = Math.max(0, (bb.x0 - pad) * dpr), y = Math.max(0, (bb.y0 - pad) * dpr), w = Math.min(cv.width - x, (bb.x1 - bb.x0 + pad * 2) * dpr), h = Math.min(cv.height - y, (bb.y1 - bb.y0 + pad * 2) * dpr);
    const sc = Math.min(1, 520 / w); const o = document.createElement("canvas"); o.width = Math.max(1, Math.round(w * sc)); o.height = Math.max(1, Math.round(h * sc));
    o.getContext("2d").drawImage(cv, x, y, w, h, 0, 0, o.width, o.height); onDone(o.toDataURL("image/png"));
  };
  return <div className="hfx-ov" onClick={onCancel}><div className="hfx-md" onClick={e => e.stopPropagation()} dir="rtl">
    <b style={{ fontSize: 16 }}>✍️ {title || "التوقيع"}</b>
    <div style={{ fontSize: 12.5, fontWeight: 700, color: "#64748b", margin: "2px 0 8px" }}>وقّع بإصبعك داخل المربع كما توقّع على الورق</div>
    <div style={{ position: "relative", borderRadius: 16, border: "2px dashed #94a3b8", background: "#fff" }}>
      <canvas ref={ref} style={{ width: "100%", height: 220, display: "block", touchAction: "none", cursor: "crosshair" }} aria-label="مساحة التوقيع" />
      <div style={{ position: "absolute", left: 18, right: 18, bottom: 46, borderBottom: "1.5px solid #cbd5e1", pointerEvents: "none" }} />
      {!has && <div style={{ position: "absolute", inset: 0, display: "grid", placeItems: "center", color: "#cbd5e1", fontWeight: 900, fontSize: 22, pointerEvents: "none" }}>وقّع هنا</div>}
    </div>
    <div className="flex gap-2 mt-3"><button className="hfx-b pri" disabled={!has} onClick={done}>✓ اعتماد التوقيع</button><button className="hfx-b" onClick={clear}>مسح</button><button className="hfx-b" style={{ marginInlineStart: "auto" }} onClick={onCancel}>إلغاء</button></div>
  </div></div>;
}

const HFX_CSS = `
.hfx{font-family:${HFX_FONT};color:#0f172a}
.hfx *{box-sizing:border-box}
.hfx-hero{border-radius:26px;color:#fff;padding:18px 20px;background:radial-gradient(520px 220px at 100% -40%,rgba(212,160,23,.35),transparent 60%),linear-gradient(135deg,#0b3d36,#0f5c50 55%,#134e4a)}
.hfx-hero h2{margin:0;font-size:22px;font-weight:900}.hfx-hero p{margin:4px 0 0;font-size:13px;font-weight:700;opacity:.88}
.hfx-tabs{display:flex;gap:6px;flex-wrap:wrap}
.hfx-tab{font-family:inherit;cursor:pointer;border:1.5px solid #e2e8f0;background:#fff;border-radius:999px;padding:8px 16px;font-weight:900;font-size:13.5px;color:#475569}
.hfx-tab.on{background:#0b3d36;color:#fff;border-color:#0b3d36}
.hfx-b{font-family:inherit;cursor:pointer;border:1.5px solid #dbe4e1;background:#fff;border-radius:13px;padding:8px 14px;font-weight:900;font-size:13.5px;color:#0f172a;display:inline-flex;align-items:center;gap:6px;text-decoration:none;white-space:nowrap}
.hfx-b:disabled{opacity:.45;cursor:not-allowed}
.hfx-b.pri{background:#0b3d36;color:#fff;border-color:#0b3d36}.hfx-b.gold{background:#d4a017;color:#2a1d00;border-color:#d4a017}.hfx-b.wa{background:#25d366;color:#fff;border-color:#25d366}.hfx-b.red{color:#b91c1c;border-color:#fecaca}
.hfx-b:focus-visible,.hfx-tab:focus-visible,.hfx-card:focus-visible{outline:3px solid #fbbf24;outline-offset:2px}
.hfx-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(170px,1fr));gap:12px}
.hfx-card{font-family:inherit;cursor:pointer;text-align:right;border:1.5px solid #e2e8f0;background:#fff;border-radius:20px;padding:10px;display:grid;gap:8px;transition:transform .15s,box-shadow .15s}
.hfx-card:hover{transform:translateY(-2px);box-shadow:0 16px 30px -22px rgba(15,23,42,.6)}
.hfx-card .th{border-radius:12px;overflow:hidden;border:1px solid #e2e8f0;aspect-ratio:595/842;background:#fff}
.hfx-card .th img{width:100%;height:100%;display:block}
.hfx-card b{font-size:13.5px;font-weight:900;line-height:1.4}
.hfx-pill{display:inline-flex;align-items:center;gap:4px;border-radius:999px;padding:2px 10px;font-weight:900;font-size:11.5px;white-space:nowrap}
.hfx-ed{display:grid;grid-template-columns:minmax(300px,420px) minmax(0,1fr);gap:16px;align-items:start}
.hfx-pane{background:#fff;border:1px solid #e2e8f0;border-radius:20px;padding:14px;display:grid;gap:10px}
.hfx-f label{display:block;font-size:12.5px;font-weight:900;color:#334155;margin-bottom:4px}
.hfx-in{width:100%;font-family:inherit;font-size:14px;font-weight:700;border:1.5px solid #dbe4e1;border-radius:12px;padding:8px 11px;background:#fbfdfc;color:#0f172a}
.hfx-in:focus{outline:none;border-color:#0f766e;box-shadow:0 0 0 3px rgba(15,118,110,.15)}
.hfx-2{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.hfx-opt{display:flex;gap:8px;align-items:flex-start;font-size:13px;font-weight:800;padding:7px 9px;border-radius:12px;border:1.5px solid #e2e8f0;cursor:pointer;background:#fff}
.hfx-opt.on{border-color:#0f766e;background:#f0fdfa}
.hfx-sec{font-size:12.5px;font-weight:900;color:#0f766e;padding:6px 10px;border-radius:10px;background:#f0fdfa;border:1px solid #ccfbf1}
.hfx-prev{position:sticky;top:10px;border-radius:16px;overflow:hidden;box-shadow:0 30px 50px -36px rgba(15,23,42,.8);border:1px solid #e2e8f0}
.hfx-row{display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:10px;align-items:center;background:#fff;border:1.5px solid #eef2f6;border-radius:18px;padding:10px 12px}
.hfx-ov{position:fixed;inset:0;z-index:9000;background:rgba(15,23,42,.55);display:flex;align-items:flex-end;justify-content:center;padding:12px}
.hfx-md{width:min(560px,100%);max-height:92vh;overflow:auto;background:#fff;border-radius:24px;padding:16px}
.hfx-note{font-size:12.5px;font-weight:800;color:#475569;background:#f8fafc;border:1px solid #e2e8f0;border-radius:14px;padding:9px 12px;line-height:1.7}
@media (max-width:900px){.hfx-ed{grid-template-columns:1fr}.hfx-prev{position:static}}
`;

// حقول الإدخال حسب النموذج
function HfxInputs({ fk, v, set, who, ctx, skip = [] }) {
  const F = HFX_F[fk];
  const list = F.in.filter(f => (f.who || "a") === who && !skip.includes(f.k) && (!f.show || f.show(ctx || v)));
  return <>{list.map(f => {
    const val = v[f.k] ?? "";
    if (f.t === "radio") return <div key={f.k} className="hfx-f"><label>{f.l}</label><div className="grid gap-1">{f.opts.map(([o, l]) => <label key={o} className={`hfx-opt ${String(val) === o ? "on" : ""}`}><input type="radio" name={fk + f.k} checked={String(val) === o} onChange={() => set(f.k, o)} />{l}</label>)}{val !== "" && <button type="button" className="hfx-b" style={{ justifySelf: "start", padding: "3px 10px", fontSize: 12 }} onClick={() => set(f.k, "")}>إلغاء الاختيار</button>}</div></div>;
    if (f.t === "check") return <label key={f.k} className={`hfx-opt ${val ? "on" : ""}`}><input type="checkbox" checked={!!val} onChange={e => set(f.k, e.target.checked ? 1 : "")} />{f.l}</label>;
    if (f.t === "area") return <div key={f.k} className="hfx-f"><label>{f.l}</label><textarea className="hfx-in" rows={4} value={val} onChange={e => set(f.k, e.target.value)} /></div>;
    return <div key={f.k} className="hfx-f"><label>{f.l}{f.t === "date" && val ? <span style={{ color: "#0f766e", marginInlineStart: 6 }}>({maDay(maDate(val))} {hfxHijTxt(val)})</span> : null}</label>
      <input className="hfx-in" type={f.t === "num" ? "number" : f.t === "date" ? "date" : f.t === "time" ? "time" : "text"} inputMode={f.t === "num" ? "numeric" : undefined} value={val} onChange={e => set(f.k, e.target.value)} /></div>;
  })}</>;
}

// ── صفحة الإدارة
function HfxPage({ by = "الإدارة" }) {
  const [tab, setTab] = useState("list"); const [cfg, setCfg] = useState(null); const [T, setT] = useState(null); const [cases, setCases] = useState(null);
  const [ed, setEd] = useState(null); const [pick, setPick] = useState(null); const [q, setQ] = useState(""); const [flt, setFlt] = useState("all"); const [msg, setMsg] = useState(""); const [sig, setSig] = useState(false); const [imp, setImp] = useState(null); const [pe, setPe] = useState(null);
  const toast = t => { setMsg(t); setTimeout(() => setMsg(""), 3200); };
  const loadCases = async () => setCases(Object.values(ptObj(await maGet(HFX_NODE))).filter(c => c && c.id && !c.hid).sort((a, b) => (b.at || 0) - (a.at || 0)));
  const loadT = async () => setT(await hfxLoadTeachers());
  useEffect(() => { (async () => { setCfg({ mgr: "فازع القرني", mgrT: "مدير المدرسة", ...ptObj(await maGet(HFX_CFG)) }); })(); loadT(); loadCases(); const t = setInterval(loadCases, 45000); return () => clearInterval(t); }, []);
  // قادم من زر «📋 مساءلة» في سجل حضور المعلمين: يفتح النموذج المناسب للمعلم مباشرة
  useEffect(() => { if (!T || !cfg) return; let p = null; try { p = JSON.parse(localStorage.getItem("mosala_prefill") || "null"); } catch {} if (!p || !p.teacherName || Date.now() - (p.timestamp || 0) > 10 * 60000) return; localStorage.removeItem("mosala_prefill");
    const t = T.find(x => cvNorm(x.n) === cvNorm(p.teacherName)) || T.find(x => cvMatch(x.n, { e: { name: p.teacherName } }) === "e"); const fk = /absent|غائب|غياب/.test(String(p.status)) ? "gh" : "ta";
    if (t) newCase(fk, t); else { setTab("new"); setPick(fk); setQ(String(p.teacherName).split(" ")[0]); } }, [T, cfg]);
  if (!cfg || !T || !cases) return <div className="p-10 text-center font-bold text-gray-400">⏳ جاري التحميل…</div>;
  const ids = hfxIds();
  const saveCfg = async p => { const n = { ...cfg, ...p }; setCfg(n); await maPut(HFX_CFG, n); toast("✅ حُفظت الإعدادات"); };
  const newCase = (fk, t) => { const prof = t || {}; setEd({ id: "h" + Date.now().toString(36) + Math.random().toString(36).slice(2, 5), tok: hfxTok(), f: fk, tk: prof.k, n: prof.n, h: prof.h || "", n4: prof.n4 || "", ph: prof.ph || "", st: "draft", at: Date.now(), by, v: { hd: maKey(new Date()), sp: prof.sp || "", lv: prof.lv || "", jn: prof.jn || "", wk: prof.wk || "معلم", ttl: prof.ttl || "معلم", kd: "t", msig: true }, tv: {} }); setPick(null); setTab("ed"); };
  const L = cases.filter(c => (flt === "all" || (flt === "wait" ? ["sent", "opened"].includes(c.st) : flt === "rep" ? c.st === "replied" : c.st === flt)) && (!q || cvNorm(c.n || "").includes(cvNorm(q)) || (HFX_F[c.f] && HFX_F[c.f].n.includes(q))));
  const cnt = s => cases.filter(c => s === "wait" ? ["sent", "opened"].includes(c.st) : s === "rep" ? c.st === "replied" : c.st === s).length;
  const printC = c => hfxPrint([{ fk: c.f, c, x: { cfg, nid: hfxNid(c.h) } }], HFX_F[c.f].n + " — " + (c.n || ""));
  const hide = async c => { if (!window.confirm(`إخفاء نموذج «${HFX_F[c.f].n}» للمعلم ${c.n}؟ (يبقى محفوظاً في الخادم)`)) return; await maPut(`${HFX_NODE}/${c.id}/hid`, Date.now()); loadCases(); };
  const tq = pick ? T.filter(t => !q || cvNorm(t.n).includes(cvNorm(q))) : [];

  const importX = async e => { const f = e.target.files && e.target.files[0]; e.target.value = ""; if (!f) return; try { const list = await hfxParseExcel(f); if (!list.length) { alert("لم أجد عمودَي «الاسم» و«السجل المدني» في الملف"); return; } setImp(list); } catch (err) { alert("تعذّر قراءة الملف: " + (err?.message || err)); } };
  const doImport = async () => {
    const I = hfxIds(); const P = {}; let n = 0, phn = 0;
    for (const x of imp) { const h = await licHash(x.nid); I[h] = x.nid; const k = asmK(x.n); const cur = T.find(t => t.h === h) || T.find(t => t.k === k);
      const kk = cur ? cur.k : k; const p = { k: kk, n: cur ? cur.n : x.n, h, n4: x.nid.slice(-4) }; ["sp", "lv", "jn", "ttl"].forEach(f => { if (x[f]) p[f] = x[f]; }); P[`${HFX_TP}/${kk}`] = { ...(ptObj(cur)), ...p, ph: undefined }; n++;
      if (x.ph) { P[`${PH_NODE}/${asmK(p.n)}`] = { n: p.n, ph: phNorm(x.ph) }; phn++; } }
    Object.values(P).forEach(o => { if (o && typeof o === "object") Object.keys(o).forEach(k => o[k] === undefined && delete o[k]); });
    hfxIdsSet(I); await fbPatch(P); setImp(null); await loadT(); toast(`✅ استُورد ${maAr(n)} معلماً${phn ? ` و${maAr(phn)} رقم جوال` : ""} — أرقام الهوية محفوظة على هذا الجهاز فقط`);
  };
  const saveProf = async () => { const p = pe; const k = p.k || asmK(p.n); const nid = licNormId(p.nid || ""); let h = p.h || ""; if (nid.length === 10) { h = await licHash(nid); const I = hfxIds(); I[h] = nid; hfxIdsSet(I); }
    const rec = { k, n: p.n.trim(), h, n4: nid.length === 10 ? nid.slice(-4) : (p.n4 || ""), sp: p.sp || "", lv: p.lv || "", jn: p.jn || "", wk: p.wk || "", ttl: p.ttl || "" };
    await maPut(`${HFX_TP}/${k}`, rec); if (p.ph !== undefined) await maPut(`${PH_NODE}/${asmK(rec.n)}`, p.ph ? { n: rec.n, ph: phNorm(p.ph) } : null); setPe(null); await loadT(); toast("✅ حُفظت بيانات المعلم"); };

  return <div className="hfx px-2 md:px-6 py-3" dir="rtl"><style>{HFX_CSS}</style>
    <div className="grid gap-3" style={{ maxWidth: 1300, margin: "0 auto" }}>
      <div className="hfx-hero"><h2>📑 نماذج متابعة دوام الموظفين (حضوري)</h2><p>النماذج الرسمية طبق الأصل • تعبئة تلقائية من بيانات المعلمين • إرسال بالواتساب • تعبئة وتوقيع المعلم من جواله</p></div>
      <div className="hfx-tabs">{[["list", `📂 السجل (${maAr(cases.length)})`], ["new", "➕ نموذج جديد"], ["tch", `👥 المعلمون (${maAr(T.length)})`], ["cfg", "⚙️ الإعدادات"]].map(([k, l]) => <button key={k} className={`hfx-tab ${tab === k || (k === "new" && tab === "ed") ? "on" : ""}`} onClick={() => { setTab(k); setPick(null); }}>{l}</button>)}</div>

      {tab === "list" && <div className="grid gap-2">
        <div className="flex gap-2 flex-wrap items-center">{[["all", "الكل", cases.length], ["draft", "مسودات", cnt("draft")], ["wait", "بانتظار المعلم", cnt("wait")], ["rep", "أعادها المعلم", cnt("rep")], ["ack", "اطّلع", cnt("ack")], ["closed", "مكتملة", cnt("closed")]].map(([k, l, n]) => <button key={k} className={`hfx-tab ${flt === k ? "on" : ""}`} style={{ padding: "5px 12px", fontSize: 12.5 }} onClick={() => setFlt(k)}>{l} {maAr(n)}</button>)}
          <input className="hfx-in" style={{ flex: "1 1 200px", maxWidth: 320 }} value={q} onChange={e => setQ(e.target.value)} placeholder="🔎 بحث باسم المعلم أو النموذج…" /></div>
        {!L.length ? <div className="hfx-pane" style={{ textAlign: "center", color: "#64748b", fontWeight: 800 }}>لا توجد نماذج بعد. ابدأ من «➕ نموذج جديد».</div> : L.map(c => { const F = HFX_F[c.f] || {}; const s = HFX_ST[c.st] || HFX_ST.draft; return <div key={c.id} className="hfx-row">
          <div style={{ width: 44, height: 44, borderRadius: 14, display: "grid", placeItems: "center", fontSize: 22, background: F.c + "18" }}>{F.ic}</div>
          <div style={{ minWidth: 0 }}><b style={{ fontSize: 14.5 }}>{c.n || "—"}</b><div style={{ fontSize: 12.5, fontWeight: 800, color: "#64748b" }}>{F.n} • {hfxHijTxt(c.v && c.v.hd)}</div>
            <div className="flex gap-1 flex-wrap mt-1"><span className="hfx-pill" style={{ background: s.bg, color: s.c }}>{s.ic} {s.l}</span>{c.repAt && <span className="hfx-pill" style={{ background: "#f8fafc", color: "#475569" }}>أُعيد {new Date(c.repAt).toLocaleDateString("ar-SA-u-ca-islamic-umalqura-nu-arab", { day: "numeric", month: "short" })}</span>}{!hfxNid(c.h) && <span className="hfx-pill" style={{ background: "#fff7ed", color: "#9a3412" }} title="رقم الهوية غير محفوظ على هذا الجهاز">🪪 بلا هوية هنا</span>}</div></div>
          <div className="flex gap-1 flex-wrap justify-end"><button className="hfx-b pri" onClick={() => { setEd(JSON.parse(JSON.stringify(c))); setTab("ed"); }}>فتح</button><button className="hfx-b" onClick={() => printC(c)}>🖨</button><button className="hfx-b red" onClick={() => hide(c)} title="إخفاء">✕</button></div>
        </div>; })}
      </div>}

      {tab === "new" && !pick && <div className="grid gap-2"><div className="hfx-note">اختر النموذج، ثم المعلم. النموذج يُعبّأ فوق الأصل الرسمي نفسه دون أي تعديل في نصه أو شكله.</div>
        <div className="hfx-grid">{HFX_ORDER.map(k => { const F = HFX_F[k]; return <button key={k} className="hfx-card" onClick={() => { setPick(k); setQ(""); }}><div className="th"><img src={HFX_IMG[k]} alt="" /></div><b>{F.ic} {F.n}</b><span className="hfx-pill" style={{ background: F.tch === "view" ? "#f1f5f9" : "#ecfdf5", color: F.tch === "view" ? "#475569" : "#065f46", justifySelf: "start" }}>{F.tch === "reply" ? "✍️ يعبّئه المعلم ويوقّعه" : F.tch === "sign" ? "✍️ يوقّعه المعلم" : "👁️ للاطلاع"}</span></button>; })}</div></div>}
      {tab === "new" && pick && <div className="hfx-pane"><div className="flex items-center gap-2 flex-wrap"><b>{HFX_F[pick].ic} {HFX_F[pick].n} — اختر المعلم</b><button className="hfx-b" style={{ marginInlineStart: "auto" }} onClick={() => setPick(null)}>→ رجوع</button></div>
        <input className="hfx-in" autoFocus value={q} onChange={e => setQ(e.target.value)} placeholder="🔎 ابحث بالاسم…" />
        <div className="grid gap-1" style={{ maxHeight: "55vh", overflow: "auto" }}>{tq.map(t => <button key={t.k} className="hfx-opt" style={{ justifyContent: "space-between", alignItems: "center" }} onClick={() => newCase(pick, t)}><span>{t.n}</span><span className="flex gap-1">{ids[t.h] ? <span className="hfx-pill" style={{ background: "#dcfce7", color: "#166534" }}>🪪 الهوية</span> : <span className="hfx-pill" style={{ background: "#fff7ed", color: "#9a3412" }}>🪪 ناقصة</span>}{t.ph ? <span className="hfx-pill" style={{ background: "#dcfce7", color: "#166534" }}>📱</span> : <span className="hfx-pill" style={{ background: "#f1f5f9", color: "#94a3b8" }}>📱 —</span>}</span></button>)}
          {!tq.length && <div style={{ color: "#64748b", fontWeight: 800, fontSize: 13 }}>لا يوجد معلمون — استورد ملف المعلمين من تبويب «👥 المعلمون».</div>}</div></div>}

      {tab === "ed" && ed && <HfxEditor key={ed.id} init={ed} cfg={cfg} T={T} by={by} toast={toast} onSaved={c => { setEd(c); loadCases(); }} onClose={() => { setEd(null); setTab("list"); loadCases(); }} onTeacher={t => setPe({ ...t, nid: hfxNid(t.h) })} />}

      {tab === "tch" && <div className="grid gap-3">
        <div className="hfx-pane"><b>📥 استيراد ملف المعلمين (Excel)</b>
          <div className="hfx-note">نفس ملف «تقرير الحضور والانصراف» أو أي ملف فيه عمودا <b>الاسم</b> و<b>السجل المدني</b>. يقرأ أيضاً إن وُجدت: التخصص، المرتبة، رقم الوظيفة، المسمى، الجوال.<br />🔒 رقم الهوية الكامل يُحفظ على <b>هذا الجهاز فقط</b> ولا يُرفع للخادم — والمعلم يُدخل هويته بنفسه لفتح نموذجه.</div>
          <label className="hfx-b gold" style={{ justifySelf: "start" }}>📂 اختيار ملف Excel<input type="file" accept=".xlsx,.xls,.csv" style={{ display: "none" }} onChange={importX} /></label></div>
        <div className="hfx-pane"><div className="flex items-center gap-2 flex-wrap"><b>👥 المعلمون</b><span style={{ fontSize: 12.5, fontWeight: 800, color: "#64748b" }}>🪪 الهوية على هذا الجهاز: {maAr(T.filter(t => ids[t.h]).length)} من {maAr(T.length)} • 📱 الجوال: {maAr(T.filter(t => t.ph).length)}</span><button className="hfx-b" style={{ marginInlineStart: "auto" }} onClick={() => setPe({ n: "", nid: "", ph: "", wk: "معلم", ttl: "معلم" })}>＋ معلم</button></div>
          <input className="hfx-in" value={q} onChange={e => setQ(e.target.value)} placeholder="🔎 بحث…" />
          <div className="grid gap-1">{T.filter(t => !q || cvNorm(t.n).includes(cvNorm(q))).map(t => <button key={t.k} className="hfx-opt" style={{ justifyContent: "space-between", alignItems: "center" }} onClick={() => setPe({ ...t, nid: hfxNid(t.h) })}><span>{t.n}<small style={{ color: "#94a3b8", marginInlineStart: 6 }}>{[t.sp, t.lv].filter(Boolean).join(" • ")}</small></span><span className="flex gap-1">{ids[t.h] ? <span className="hfx-pill" style={{ background: "#dcfce7", color: "#166534" }}>🪪 …{maAr(t.n4 || "")}</span> : <span className="hfx-pill" style={{ background: "#fff7ed", color: "#9a3412" }}>🪪 ناقصة</span>}<span className="hfx-pill" style={{ background: t.ph ? "#dcfce7" : "#f1f5f9", color: t.ph ? "#166534" : "#94a3b8" }}>📱 {t.ph ? maAr(t.ph.slice(-4)) : "—"}</span></span></button>)}</div></div>
      </div>}

      {tab === "cfg" && <div className="hfx-pane" style={{ maxWidth: 620 }}>
        <div className="hfx-2"><div className="hfx-f"><label>اسم الرئيس المباشر (يُكتب في النماذج)</label><input className="hfx-in" defaultValue={cfg.mgr} onBlur={e => e.target.value.trim() && e.target.value.trim() !== cfg.mgr && saveCfg({ mgr: e.target.value.trim() })} /></div>
          <div className="hfx-f"><label>صفته (محضر الانقطاع)</label><input className="hfx-in" defaultValue={cfg.mgrT} onBlur={e => e.target.value.trim() !== cfg.mgrT && saveCfg({ mgrT: e.target.value.trim() })} /></div></div>
        <div className="hfx-f"><label>رقم التواصل (قرار حسم التأخير)</label><input className="hfx-in" inputMode="tel" defaultValue={cfg.phone || ""} onBlur={e => e.target.value.trim() !== (cfg.phone || "") && saveCfg({ phone: e.target.value.trim() })} /></div>
        <div className="hfx-f"><label>توقيع الرئيس المباشر (اختياري — يظهر في خانة توقيعه)</label>
          <div className="flex gap-2 items-center flex-wrap">{cfg.sig ? <img src={cfg.sig} alt="التوقيع" style={{ height: 60, background: "#fff", border: "1px solid #e2e8f0", borderRadius: 10, padding: 4 }} /> : <span style={{ color: "#94a3b8", fontWeight: 800, fontSize: 13 }}>لا يوجد توقيع محفوظ</span>}
            <button className="hfx-b" onClick={() => setSig(true)}>✍️ {cfg.sig ? "تغيير" : "إضافة"} التوقيع</button>{cfg.sig && <button className="hfx-b red" onClick={() => window.confirm("حذف التوقيع المحفوظ؟") && saveCfg({ sig: "" })}>حذف</button>}</div></div>
        <div className="hfx-note">الختم الرسمي لا يُضاف إلكترونياً — يُختم على النسخة المطبوعة.</div>
      </div>}
    </div>
    {sig && <HfxSigPad title="توقيع الرئيس المباشر" onCancel={() => setSig(false)} onDone={s => { setSig(false); saveCfg({ sig: s }); }} />}
    {imp && <div className="hfx-ov" onClick={() => setImp(null)}><div className="hfx-md" onClick={e => e.stopPropagation()} dir="rtl"><b style={{ fontSize: 16 }}>📥 استيراد {maAr(imp.length)} اسماً</b>
      <div className="grid gap-1 mt-2" style={{ maxHeight: "50vh", overflow: "auto" }}>{imp.map(x => <div key={x.nid} className="hfx-opt" style={{ justifyContent: "space-between" }}><span>{x.n}</span><small style={{ color: "#64748b" }}>…{maAr(x.nid.slice(-4))}{x.ph ? " • 📱" : ""}</small></div>)}</div>
      <div className="flex gap-2 mt-3"><button className="hfx-b pri" onClick={doImport}>✅ استيراد</button><button className="hfx-b" onClick={() => setImp(null)}>إلغاء</button></div></div></div>}
    {pe && <div className="hfx-ov" onClick={() => setPe(null)}><div className="hfx-md" onClick={e => e.stopPropagation()} dir="rtl"><b style={{ fontSize: 16 }}>👤 بيانات المعلم</b>
      <div className="grid gap-2 mt-2">{[["n", "الاسم"], ["nid", "رقم الهوية (يبقى على هذا الجهاز)"], ["ph", "الجوال"], ["sp", "التخصص"], ["lv", "المستوى / المرتبة"], ["jn", "رقم الوظيفة"], ["wk", "العمل الحالي"], ["ttl", "مسمى الوظيفة"]].map(([k, l]) => <div key={k} className="hfx-f"><label>{l}</label><input className="hfx-in" value={pe[k] || ""} inputMode={k === "nid" || k === "ph" ? "numeric" : undefined} onChange={e => setPe({ ...pe, [k]: k === "nid" ? licNormId(e.target.value).slice(0, 10) : e.target.value })} /></div>)}</div>
      <div className="flex gap-2 mt-3"><button className="hfx-b pri" disabled={!String(pe.n || "").trim() || (pe.nid && pe.nid.length !== 10)} onClick={saveProf}>💾 حفظ</button><button className="hfx-b" onClick={() => setPe(null)}>إلغاء</button></div></div></div>}
    {msg && <div style={{ position: "fixed", bottom: 24, left: "50%", transform: "translateX(-50%)", zIndex: 9500, background: "#0f172a", color: "#fff", padding: "12px 20px", borderRadius: 14, fontWeight: 800, maxWidth: "92vw", textAlign: "center" }}>{msg}</div>}
  </div>;
}

// ── محرر النموذج (الإدارة)
function HfxEditor({ init, cfg, T, by, toast, onSaved, onClose, onTeacher }) {
  const [c, setC] = useState(init); const [busy, setBusy] = useState(false); const [nidIn, setNidIn] = useState("");
  const F = HFX_F[c.f]; const nid = hfxNid(c.h); const t = T.find(x => x.k === c.tk) || {};
  const ph = c.ph || t.ph || "";
  const set = (k, v) => setC(x => ({ ...x, v: { ...x.v, [k]: v } }));
  const setT = (k, v) => setC(x => ({ ...x, tv: { ...ptObj(x.tv), [k]: v } }));
  const RK = { draft: 0, sent: 1, opened: 2, ack: 3, replied: 3, closed: 4 };
  // دمج آمن: لا تُكتب نسخة الإدارة فوق ما أرسله المعلم في الأثناء
  const save = async (patch = {}) => { setBusy(true); const cur = ptObj(await maGet(`${HFX_NODE}/${c.id}`)); let n = { ...c, ...patch, ph, upAt: Date.now() };
    if (cur.id) { if ((cur.repAt || 0) > (c.repAt || 0)) n = { ...n, tv: cur.tv, ts: cur.ts, repAt: cur.repAt }; ["openAt", "ackAt"].forEach(k => { if (cur[k] && !n[k]) n[k] = cur[k]; }); if (!patch.st && (RK[cur.st] || 0) > (RK[n.st] || 0)) n.st = cur.st; }
    const ok = await maPut(`${HFX_NODE}/${n.id}`, n); setBusy(false); if (ok) { setC(n); onSaved(n); } else toast("⚠️ تعذّر الحفظ — تحقق من الاتصال"); return ok ? n : null; };
  const addNid = async () => { const n = licNormId(nidIn); if (n.length !== 10) return; const h = await licHash(n); const I = hfxIds(); I[h] = n; hfxIdsSet(I); setC(x => ({ ...x, h, n4: n.slice(-4) })); setNidIn(""); toast("✅ حُفظت الهوية على هذا الجهاز"); };
  const waTxt = n => `المكرم الأستاذ/ ${n.n} وفقه الله\nالسلام عليكم ورحمة الله وبركاته\n\nنرفق لكم نموذج «${F.n}» من ${HFX_SCHOOL}.\n${F.tch === "reply" ? "نأمل الاطلاع عليه وتعبئة الإفادة والتوقيع ثم الإرسال" : F.tch === "sign" ? "نأمل الاطلاع عليه والتوقيع ثم الإرسال" : "نأمل الاطلاع عليه"} عبر الرابط التالي (يُفتح برقم هويتكم):\n${hfxLink(n)}\n\nمع التحية — ${cfg.mgr || "إدارة المدرسة"}`;
  const send = async () => { if (!c.h) { toast("أضف رقم هوية المعلم أولاً — به يفتح المعلم النموذج"); return; } const w = window.open("", "_blank"); const n = await save(c.st === "draft" ? { st: "sent", sentAt: Date.now() } : { sentAt: Date.now() }); if (n) { const u = waUrl(ph, waTxt(n)); if (w) w.location.href = u; else window.location.href = u; } else if (w) w.close(); };
  const close = async () => { const n = await save({ st: "closed", closedAt: Date.now(), v: { ...c.v, dd: c.v.dd || (c.v.dec ? maKey(new Date()) : "") } }); if (n) toast("🗂️ اكتمل النموذج"); };
  const s = HFX_ST[c.st] || HFX_ST.draft;
  const tvc = { ...c, v: { ...c.v } };
  return <div className="hfx-ed">
    <div className="grid gap-2">
      <div className="hfx-pane">
        <div className="flex items-center gap-2 flex-wrap"><b style={{ fontSize: 15 }}>{F.ic} {F.n}</b><span className="hfx-pill" style={{ background: s.bg, color: s.c }}>{s.ic} {s.l}</span><button className="hfx-b" style={{ marginInlineStart: "auto", padding: "4px 10px" }} onClick={onClose}>→ السجل</button></div>
        <div style={{ fontSize: 14, fontWeight: 900 }}>👤 {c.n}</div>
        <div className="flex gap-1 flex-wrap">{nid ? <span className="hfx-pill" style={{ background: "#dcfce7", color: "#166534" }}>🪪 {maAr(nid)}</span> : <span className="hfx-pill" style={{ background: "#fff7ed", color: "#9a3412" }}>🪪 الهوية غير محفوظة على هذا الجهاز</span>}{ph ? <span className="hfx-pill" style={{ background: "#dcfce7", color: "#166534" }}>📱 {maAr(ph)}</span> : <span className="hfx-pill" style={{ background: "#fff7ed", color: "#9a3412" }}>📱 لا يوجد جوال</span>}<button className="hfx-b" style={{ padding: "2px 10px", fontSize: 12 }} onClick={() => onTeacher(t.k ? t : { k: c.tk, n: c.n, h: c.h })}>تعديل بياناته</button></div>
        {!nid && <div className="flex gap-2"><input className="hfx-in" inputMode="numeric" placeholder="رقم الهوية (١٠ أرقام)" value={nidIn} onChange={e => setNidIn(licNormId(e.target.value).slice(0, 10))} /><button className="hfx-b" disabled={nidIn.length !== 10} onClick={addNid}>حفظ</button></div>}
        <div className="hfx-note" style={{ fontSize: 12 }}>{F.dur}</div>
      </div>
      <div className="hfx-pane"><div className="hfx-sec">١) بيانات الإدارة</div><HfxInputs fk={c.f} v={c.v} set={set} who="a" />
        {cfg.sig && <label className={`hfx-opt ${c.v.msig !== false ? "on" : ""}`}><input type="checkbox" checked={c.v.msig !== false} onChange={e => set("msig", e.target.checked)} />إضافة توقيع الرئيس المباشر المحفوظ</label>}</div>
      {F.in.some(f => f.who === "t") && <details className="hfx-pane" open={!!(c.tv && Object.keys(ptObj(c.tv)).length)}><summary style={{ cursor: "pointer", fontWeight: 900, fontSize: 13.5 }}>٢) جزء المعلم {c.st === "replied" || c.st === "closed" ? "— ✍️ أعاده المعلم" : "— يعبّئه المعلم من جواله"}</summary>
        <div className="grid gap-2 mt-2">{c.ts ? <div className="flex items-center gap-2"><img src={c.ts} alt="توقيع المعلم" style={{ height: 48, background: "#fff", border: "1px solid #e2e8f0", borderRadius: 8 }} /><span style={{ fontSize: 12, fontWeight: 800, color: "#64748b" }}>توقيع المعلم{c.repAt ? ` • ${new Date(c.repAt).toLocaleString("ar-SA")}` : ""}</span></div> : null}
          <HfxInputs fk={c.f} v={ptObj(c.tv)} set={setT} who="t" ctx={{ ...c.v, ...ptObj(c.tv) }} /></div></details>}
      {F.in.some(f => f.who === "d") && <div className="hfx-pane"><div className="hfx-sec">٣) رأي الرئيس المباشر</div><HfxInputs fk={c.f} v={c.v} set={set} who="d" /></div>}
      <div className="hfx-pane">
        <div className="flex gap-2 flex-wrap">
          <button className="hfx-b pri" disabled={busy} onClick={async () => { if (await save()) toast("✅ تم الحفظ"); }}>💾 حفظ</button>
          <button className="hfx-b wa" disabled={busy} onClick={send}>📲 {c.st === "draft" ? "إرسال للمعلم" : "إعادة الإرسال"} بالواتساب</button>
          <button className="hfx-b gold" onClick={() => hfxPrint([{ fk: c.f, c, x: { cfg, nid } }], F.n + " — " + c.n)}>🖨 طباعة / PDF</button>
          {c.st !== "closed" && (c.st === "replied" || c.st === "ack" || F.tch === "view") && <button className="hfx-b" disabled={busy} onClick={close}>🗂️ اعتماد واكتمال</button>}
        </div>
        {c.st !== "draft" && <div style={{ fontSize: 12, fontWeight: 800, color: "#64748b", wordBreak: "break-all" }} dir="ltr">🔗 {hfxLink(c)}</div>}
        {!nid && <div style={{ fontSize: 12, fontWeight: 800, color: "#9a3412" }}>⚠️ بدون رقم الهوية على هذا الجهاز تُطبع خانات الهوية فارغة.</div>}
      </div>
    </div>
    <div className="hfx-prev"><HfxSheet fk={c.f} c={tvc} x={{ cfg, nid }} /></div>
  </div>;
}

// ── بوابة المعلم: يفتح الرابط من الواتساب ← يُدخل هويته ← يطّلع ويعبّئ ويوقّع ← يرسل
function HfxTeacherPortal({ onBack }) {
  const raw = (() => { try { return decodeURIComponent(window.location.hash.replace(/^#hfx=/, "")); } catch { return ""; } })();
  const [id, tok] = raw.split(".");
  const [c, setC] = useState(undefined); const [cfg, setCfg] = useState({}); const [nid, setNid] = useState(""); const [ok, setOk] = useState(false); const [err, setErr] = useState("");
  const [tv, setTv] = useState({}); const [ts, setTs] = useState(""); const [sig, setSig] = useState(false); const [busy, setBusy] = useState(false); const [done, setDone] = useState(false); const [zoom, setZoom] = useState(false);
  useEffect(() => { (async () => { const [x, g] = await Promise.all([id ? maGet(`${HFX_NODE}/${id}`) : null, maGet(HFX_CFG)]); setCfg({ mgr: "فازع القرني", mgrT: "مدير المدرسة", ...ptObj(g) }); setC(x && x.id && x.tok === tok && !x.hid ? x : null); if (x) { setTv(ptObj(x.tv)); setTs(x.ts || ""); } })(); }, []);
  const verify = async () => { setErr(""); const n = licNormId(nid); if (n.length !== 10) { setErr("أدخل رقم الهوية كاملاً (١٠ أرقام)"); return; } const h = await licHash(n); if (h !== c.h) { setErr("رقم الهوية لا يطابق صاحب النموذج"); return; } setOk(true);
    if (["sent", "draft"].includes(c.st)) { const p = { st: "opened", openAt: Date.now() }; setC(x => ({ ...x, ...p })); fbPatch({ [`${HFX_NODE}/${c.id}/st`]: "opened", [`${HFX_NODE}/${c.id}/openAt`]: p.openAt }); } };
  const wrap = ch => <div className="hfx" dir="rtl" style={{ minHeight: "100vh", background: "linear-gradient(160deg,#ecfdf5,#f8fafc 50%)", padding: "14px 10px 40px" }}><style>{HFX_CSS}</style><div style={{ maxWidth: 760, margin: "0 auto" }} className="grid gap-3">
    <div className="hfx-hero" style={{ padding: "14px 16px" }}><div style={{ fontSize: 12.5, fontWeight: 800, opacity: .85 }}>{HFX_SCHOOL}</div><h2 style={{ fontSize: 19 }}>📑 {c && HFX_F[c.f] ? HFX_F[c.f].n : "نموذج متابعة الدوام"}</h2></div>{ch}</div></div>;
  if (c === undefined) return wrap(<div className="hfx-pane" style={{ textAlign: "center" }}>⏳ جاري فتح النموذج…</div>);
  if (!c) return wrap(<div className="hfx-pane" style={{ textAlign: "center" }}><div style={{ fontSize: 40 }}>🔗</div><b>الرابط غير صالح أو انتهت صلاحيته</b><div style={{ fontSize: 13, color: "#64748b", fontWeight: 700 }}>تواصل مع إدارة المدرسة لإعادة الإرسال</div>{onBack && <button className="hfx-b" style={{ justifySelf: "center" }} onClick={onBack}>الصفحة الرئيسية</button>}</div>);
  const F = HFX_F[c.f];
  if (!ok) return wrap(<div className="hfx-pane"><b style={{ fontSize: 16 }}>🔒 للاطلاع على النموذج أدخل رقم هويتك</b><div style={{ fontSize: 13, color: "#64748b", fontWeight: 700 }}>النموذج موجّه إلى: <b style={{ color: "#0f172a" }}>{c.n}</b></div>
    <input className="hfx-in" style={{ fontSize: 20, letterSpacing: 2, textAlign: "center" }} inputMode="numeric" autoComplete="off" maxLength={10} value={nid} onChange={e => setNid(licNormId(e.target.value).slice(0, 10))} onKeyDown={e => e.key === "Enter" && verify()} placeholder="١٠ أرقام" />
    {err && <div style={{ color: "#b91c1c", fontWeight: 900, fontSize: 13 }}>{err}</div>}<button className="hfx-b pri" style={{ justifyContent: "center", padding: 12, fontSize: 16 }} onClick={verify}>فتح النموذج</button></div>);
  const answered = ["replied", "closed"].includes(c.st) && !done; const viewOnly = F.tch === "view";
  const tIn = F.in.filter(f => f.who === "t" && f.k !== "td");
  const live = { ...c, tv: { ...tv, td: tv.td || maKey(new Date()) }, ts };
  const submit = async () => {
    if (F.tch === "reply" && tIn.some(f => f.t === "area") && !String(tv.rsn || "").trim()) { alert("اكتب الإفادة أولاً"); return; }
    if (!ts) { alert("وقّع أولاً"); return; }
    setBusy(true); const at = Date.now(); const ntv = { ...tv, td: maKey(new Date()) };
    const okk = await fbPatch({ [`${HFX_NODE}/${c.id}/tv`]: ntv, [`${HFX_NODE}/${c.id}/ts`]: ts, [`${HFX_NODE}/${c.id}/st`]: "replied", [`${HFX_NODE}/${c.id}/repAt`]: at });
    setBusy(false); if (okk) { setC(x => ({ ...x, tv: ntv, ts, st: "replied", repAt: at })); setDone(true); } else alert("تعذّر الإرسال — تحقق من الاتصال وأعد المحاولة");
  };
  const ack = async () => { setBusy(true); const at = Date.now(); const okk = await fbPatch({ [`${HFX_NODE}/${c.id}/st`]: "ack", [`${HFX_NODE}/${c.id}/ackAt`]: at }); setBusy(false); if (okk) { setC(x => ({ ...x, st: "ack", ackAt: at })); setDone(true); } };
  const sheet = <div className="hfx-prev" style={{ position: "static" }} onClick={() => setZoom(true)}><HfxSheet fk={c.f} c={live} x={{ cfg, nid: licNormId(nid) }} /></div>;
  return wrap(<>
    {done ? <div className="hfx-pane" style={{ borderColor: "#86efac", background: "#f0fdf4" }}><b style={{ fontSize: 16, color: "#166534" }}>✅ {viewOnly ? "تم تسجيل اطلاعك" : "تم إرسال النموذج للإدارة"}، شكراً لك</b><div style={{ fontSize: 13, fontWeight: 700, color: "#166534" }}>يمكنك حفظ نسخة PDF من الزر أدناه.</div></div>
      : answered ? <div className="hfx-pane" style={{ borderColor: "#fde68a", background: "#fffbeb" }}><b style={{ color: "#92400e" }}>✍️ سبق أن أرسلت هذا النموذج{c.repAt ? ` (${new Date(c.repAt).toLocaleString("ar-SA")})` : ""}</b></div>
      : <div className="hfx-note">اطّلع على النموذج أدناه (اضغط عليه للتكبير){viewOnly ? "، ثم اضغط «تم الاطلاع»." : "، ثم عبّئ جزءك ووقّع واضغط «إرسال»."}</div>}
    {sheet}
    {!answered && !done && (viewOnly ? <button className="hfx-b pri" style={{ justifyContent: "center", padding: 13, fontSize: 16 }} disabled={busy || c.st === "ack"} onClick={ack}>{c.st === "ack" ? "✓ سبق تسجيل الاطلاع" : "✓ تم الاطلاع"}</button> : <div className="hfx-pane">
      {tIn.length > 0 && <><div className="hfx-sec">✍️ جزء المعلم</div><HfxInputs fk={c.f} v={tv} set={(k, v) => setTv(x => ({ ...x, [k]: v }))} who="t" ctx={{ ...ptObj(c.v), ...tv }} skip={["td"]} /></>}
      <div className="flex items-center gap-2 flex-wrap">{ts ? <img src={ts} alt="توقيعك" style={{ height: 56, background: "#fff", border: "1px solid #e2e8f0", borderRadius: 10, padding: 4 }} /> : null}<button className="hfx-b gold" onClick={() => setSig(true)}>✍️ {ts ? "إعادة التوقيع" : "التوقيع بإصبعك"}</button></div>
      <button className="hfx-b pri" style={{ justifyContent: "center", padding: 13, fontSize: 16 }} disabled={busy} onClick={submit}>{busy ? "⏳ جاري الإرسال…" : "📤 إرسال للإدارة"}</button>
    </div>)}
    <button className="hfx-b" style={{ justifyContent: "center" }} onClick={() => hfxPrint([{ fk: c.f, c: live, x: { cfg, nid: licNormId(nid) } }], F.n)}>🖨 حفظ نسخة PDF</button>
    {sig && <HfxSigPad title="توقيعك" onCancel={() => setSig(false)} onDone={s => { setTs(s); setSig(false); }} />}
    {zoom && <div className="hfx-ov" style={{ alignItems: "flex-start", overflow: "auto", padding: 0 }} onClick={() => setZoom(false)}><div style={{ width: "max(760px,100%)", background: "#fff" }}><HfxSheet fk={c.f} c={live} x={{ cfg, nid: licNormId(nid) }} /></div></div>}
  </>);
}

