// قص يدوي: اسحب مستطيلاً على الصفحة
function NqCropper({ page, init, onDone, onClose }) {
  const ref = useRef(null); const [b, setB] = useState(init || null); const st = useRef(null);
  const pt = e => { const r = ref.current.getBoundingClientRect(); return [Math.min(1, Math.max(0, (e.clientX - r.left) / r.width)), Math.min(1, Math.max(0, (e.clientY - r.top) / r.height))]; };
  return <div className="nq-modal" style={{ zIndex: 900, alignItems: "flex-start", overflowY: "auto" }}><div className="nq-card" style={{ maxWidth: 760, width: "100%" }}>
    <div style={{ display: "flex", gap: 8, alignItems: "center", flexWrap: "wrap", marginBottom: 8 }}><b style={{ flex: 1 }}>✂️ اسحب بإصبعك أو بالفأرة مستطيلاً حول السؤال أو الشكل</b><button className="nq-b nq-green" disabled={!b} onClick={() => onDone(b)}>✓ اعتماد القص</button><button className="nq-b nq-ghost" onClick={onClose}>إلغاء</button></div>
    <div ref={ref} style={{ position: "relative", touchAction: "none", userSelect: "none", cursor: "crosshair" }}
      onPointerDown={e => { e.preventDefault(); ref.current.setPointerCapture && ref.current.setPointerCapture(e.pointerId); const p = pt(e); st.current = p; setB([p[0], p[1], p[0], p[1]]); }}
      onPointerMove={e => { if (!st.current) return; const p = pt(e); const s = st.current; setB([Math.min(s[0], p[0]), Math.min(s[1], p[1]), Math.max(s[0], p[0]), Math.max(s[1], p[1])]); }}
      onPointerUp={() => { st.current = null; setB(x => x && x[2] - x[0] > .01 && x[3] - x[1] > .005 ? x : null); }}>
      <img src={page.src} alt="" draggable={false} style={{ width: "100%", display: "block", borderRadius: 8, border: "1px solid #e2e8f0" }} />
      {b && <div style={{ position: "absolute", left: `${b[0] * 100}%`, top: `${b[1] * 100}%`, width: `${(b[2] - b[0]) * 100}%`, height: `${(b[3] - b[1]) * 100}%`, border: "3px solid #2563eb", background: "rgba(37,99,235,.12)", borderRadius: 4, pointerEvents: "none" }} />}
    </div>
  </div></div>;
}

