  const loadDay = async () => { const d = ptObj(await maGet(`${DC_NODE}/${dateK}`)); const qq = await dcQGet(); qq.forEach(x => { if (x.v && x.v.dk === dateK && x.v.id && x.path.startsWith(DC_NODE + "/")) d[x.v.id] = x.v; }); setDay(d); };
