  R.forEach(r => { const o = byCk[r.ck] = byCk[r.ck] || { ck: r.ck, lv: +String(r.ck)[0] - 1, s: 0, c: 0, stu: new Set(), cats: {} }; if (r.k === "c") o.c++; else { o.s++; o.stu.add(r.sid); } const lb = dcLbl(r); o.cats[lb] = (o.cats[lb] || 0) + 1; });
